    const beachLabel = formatBudgetChip(beachAmt, cur);
    const quietPhrase = formatBudgetPhrase(quietAmt, cur);
    const beachPhrase = formatBudgetPhrase(beachAmt, cur);

    const bubble = $("#invite-user-bubble");
