      const fd = new FormData(e.target);
      if (mode === "flights") {
        const origin = String(fd.get("origin") || "BOM").toUpperCase().slice(0, 3);
        const destination = String(fd.get("destination") || "DEL").toUpperCase().slice(0, 3);
        const depart = fd.get("depart") || isoPlus(14);
        const ret = fd.get("return") || "";
        const trip = fd.get("trip_type") || tripType || "oneway";
        const adults = fd.get("adults") || "1";
        const cabin = fd.get("cabin") || "Economy";
        const tripLabel = trip === "round" ? "Round trip" : trip === "multi" ? "Multi-city" : "One way";
        pushRecent({
          key: `f:${origin}-${destination}:${trip}`,
          kind: "flight",
          label: `${origin} → ${destination}`,
          sub: destination,
          trip,
          tripLabel,
          depart,
          returnDate: ret || "",
          from: origin,
          to: destination,
          city: destination,
        });
        let url = `/flights/results/?from=${encodeURIComponent(origin)}&to=${encodeURIComponent(
          destination
        )}&depart=${encodeURIComponent(depart)}&trip=${encodeURIComponent(
          trip === "round" ? "round" : "oneway"
        )}&adults=${encodeURIComponent(adults)}&cabin=${encodeURIComponent(
          String(cabin).toUpperCase().replace(/\s+/g, "_")
        )}`;
        if (trip === "round" && ret) url += `&return=${encodeURIComponent(ret)}`;
        if (trip === "multi") {
          // The V2 results page has no multi-city mode yet; keep the production SPA for it.
          url = `/flights?origin=${encodeURIComponent(origin)}&destination=${encodeURIComponent(
            destination
          )}&depart_date=${encodeURIComponent(depart)}&trip_type=multi&adults=${encodeURIComponent(
            adults
