    function renderPax(faceBtn) {
      let adults = Number($("#adults-val")?.value || 1);
      let cabin = $("#cabin-val")?.value || "Economy";
      openPop("pax", faceBtn);

      function paint() {
        pop.innerHTML = `
          <div class="dock-pop__head"><p class="dock-pop__title">Travellers</p></div>
          <div class="dock-pop__pax">
            <div class="dock-pop__row">
              <div class="dock-pop__row-label"><strong>Adults</strong><span>Age 12+</span></div>
              <div class="dock-pop__step">
                <button type="button" data-ad="-1" aria-label="Fewer adults" ${adults <= 1 ? "disabled" : ""}>−</button>
                <b>${adults}</b>
                <button type="button" data-ad="1" aria-label="More adults" ${adults >= 9 ? "disabled" : ""}>+</button>
              </div>
            </div>
            <div class="dock-pop__row-label"><strong>Cabin</strong><span>How you like to fly</span></div>
            <div class="dock-pop__cabins">
              ${CABINS.map(
                (c) =>
                  `<button type="button" data-cabin="${escapeHtml(c)}" class="${
                    c === cabin ? "is-on" : ""
                  }">${escapeHtml(c)}</button>`
