        $(".dock-pop__done", pop)?.addEventListener("click", () => {
          const a = $("#adults-val");
          const c = $("#cabin-val");
          if (a) a.value = String(adults);
          if (c) c.value = cabin;
          syncPaxFace();
          closePop();
        });
