      input.addEventListener("keydown", (e) => {
        if (pop.hidden || state.kind !== "suggest" || state.anchor !== input) return;
        const opts = $$(".dock-pop__opt", pop);
        if (!opts.length) return;
        if (e.key === "ArrowDown") {
          e.preventDefault();
          state.activeIdx = Math.min(opts.length - 1, state.activeIdx + 1);
          opts.forEach((o, i) => o.classList.toggle("is-active", i === state.activeIdx));
        } else if (e.key === "ArrowUp") {
          e.preventDefault();
          state.activeIdx = Math.max(0, state.activeIdx - 1);
          opts.forEach((o, i) => o.classList.toggle("is-active", i === state.activeIdx));
        } else if (e.key === "Enter") {
          e.preventDefault();
          opts[state.activeIdx]?.click();
