  function hopCode(city) {
    const name = String(city || "").trim();
    if (!name) return "···";
    if (HOP_CODES[name]) return HOP_CODES[name];
    const key = Object.keys(HOP_CODES).find((k) => name.toLowerCase().startsWith(k.toLowerCase()));
    if (key) return HOP_CODES[key];
    return name.replace(/[^A-Za-z]/g, "").slice(0, 3).toUpperCase() || "···";
  }

