  function parseIso(iso) {
    if (!iso) return null;
    const d = new Date(`${iso}T12:00:00`);
    return Number.isNaN(d.getTime()) ? null : d;
  }

  /** Standard face format: 02 Nov 2026 */
  function formatFaceDate(iso) {
    const d = parseIso(iso);
    if (!d) return "Select date";
    const dd = String(d.getDate()).padStart(2, "0");
    const mon = d.toLocaleDateString("en-GB", { month: "short" });
    return `${dd} ${mon} ${d.getFullYear()}`;
  }

  /** Longer label inside the calendar */
  function formatCalTitle(iso) {
    const d = parseIso(iso);
    if (!d) return "Select a date";
    return d.toLocaleDateString("en-GB", {
      weekday: "short",
      day: "numeric",
      month: "long",
      year: "numeric",
    });
  }

  function toIso(d) {
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  }

  function filterAirports(q) {
    const s = String(q || "")
      .trim()
      .toLowerCase();
    if (!s) return AIRPORTS.slice(0, 8);
    return AIRPORTS.filter(
      (a) =>
        a.code.toLowerCase().includes(s) ||
        a.city.toLowerCase().includes(s) ||
        a.name.toLowerCase().includes(s)
    ).slice(0, 8);
  }

  function filterCities(q) {
    const s = String(q || "")
      .trim()
      .toLowerCase();
    if (!s) return CITIES.slice(0, 8);
    return CITIES.filter((c) => c.city.toLowerCase().includes(s) || c.meta.toLowerCase().includes(s)).slice(
      0,
      8
    );
  }

  function wireDockPickers() {
    const pop = $("#dock-pop");
    const dock = $("#search");
    if (!pop || !dock) return;

    let state = { kind: null, anchor: null, calMonth: null, activeIdx: 0, suggestReq: 0 };
    let suggestAbort = null;
    let lastSuggestPaint = [];

    function closePop() {
      pop.hidden = true;
      pop.innerHTML = "";
      pop.classList.remove("dock-pop--cal");
      $$("[aria-expanded='true']").forEach((el) => el.setAttribute("aria-expanded", "false"));
      state = { kind: null, anchor: null, calMonth: null, activeIdx: 0 };
    }

    function placePop(anchor) {
      const aRect = (anchor.closest?.(".cell") || anchor).getBoundingClientRect();
      const popW = Math.min(340, window.innerWidth - 24);
      let left = Math.max(12, Math.min(aRect.left, window.innerWidth - popW - 12));
      let top = aRect.bottom + 8;
      pop.style.width = `${popW}px`;
      pop.style.left = `${left}px`;
      pop.style.top = `${top}px`;
      requestAnimationFrame(() => {
        const pr = pop.getBoundingClientRect();
        if (pr.bottom > window.innerHeight - 12) {
          pop.style.top = `${Math.max(12, aRect.top - pr.height - 8)}px`;
        }
      });
    }

    function openPop(kind, anchor) {
      state.kind = kind;
      state.anchor = anchor;
      $$("[aria-expanded='true']").forEach((el) => {
        if (el !== anchor) el.setAttribute("aria-expanded", "false");
      });
      anchor.setAttribute("aria-expanded", "true");
      pop.classList.toggle("dock-pop--cal", kind === "calendar");
      pop.hidden = false;
      placePop(anchor.closest(".cell") || anchor);
    }

    function localSuggestRows(type, q, ds) {
      return type === "city"
        ? filterCities(q).map((c) => ({
            key: c.city,
            code: "",
            city: c.city,
            meta: c.meta,
            value: c.city,
          }))
        : ds && typeof ds.localAirportRows === "function"
          ? ds.localAirportRows(q, 8)
          : filterAirports(q).map((a) => ({
              key: a.code,
              code: a.code,
              city: a.city,
              meta: a.name,
              value: a.code,
            }));
    }

    function paintSuggestItems(input, items, paintOpts = {}) {
      state.activeIdx = 0;
      openPop("suggest", input);
      const qLen = String(input.value || "").trim().length;
      if (!items.length) {
        if (paintOpts.allowEmpty) {
          lastSuggestPaint = [];
          pop.innerHTML = `<p class="dock-pop__empty">No matches. Try a city or code.</p>`;
          return;
        }
        if (lastSuggestPaint.length) return;
        if (paintOpts.pending || qLen >= 2) {
          pop.innerHTML = `<p class="dock-pop__empty dock-pop__pending" role="status">Searching…</p>`;
          return;
        }
        return;
      }
      lastSuggestPaint = items;
      pop.innerHTML = `<ul class="dock-pop__list" role="listbox">${items
        .map(
          (it, i) => `
        <li>
          <button type="button" class="dock-pop__opt${i === 0 ? " is-active" : ""}" role="option" data-value="${escapeHtml(
            it.value
          )}" data-idx="${i}">
            <span class="dock-pop__copy">
              <span class="dock-pop__city">${escapeHtml(it.city)}</span>
              <span class="dock-pop__meta">${escapeHtml(it.meta)}</span>
            </span>
            ${it.code ? `<span class="dock-pop__code">${escapeHtml(it.code)}</span>` : ""}
          </button>
        </li>`
        )
        .join("")}</ul>`;

      $$(".dock-pop__opt", pop).forEach((btn) => {
        btn.addEventListener("mousedown", (e) => e.preventDefault());
        btn.addEventListener("click", () => {
          input.value = btn.dataset.value;
          closePop();
          input.focus();
        });
      });
    }

    function paintSuggestInstant(input) {
      const type = input.dataset.suggest;
      const q = String(input.value || "").trim();
      const ds = window.ItineroDestinationSuggest;
      const local = localSuggestRows(type, q, ds);
      if (local.length) {
        paintSuggestItems(input, local);
        return;
      }
      if (q.length >= 1 && !local.length) {
        paintSuggestItems(input, [], { pending: true });
      } else if (q.length === 0) {
        paintSuggestItems(input, local);
      }
    }

    function enrichSuggest(input) {
      const type = input.dataset.suggest;
      const q = String(input.value || "").trim();
      const qAtStart = q;
      const ds = window.ItineroDestinationSuggest;
      const local = localSuggestRows(type, q, ds);

      if (q.length < 2 || !ds) return;

      if (suggestAbort) suggestAbort.abort();
      suggestAbort = new AbortController();
      const apiSignal = suggestAbort.signal;

      const req = ++state.suggestReq;
      const finish = (items, settled) => {
        if (req !== state.suggestReq || state.anchor !== input) return;
        if (String(input.value || "").trim() !== qAtStart) return;
        const rows = items && items.length ? items : local;
        if (rows.length) paintSuggestItems(input, rows);
        else if (settled) paintSuggestItems(input, [], { allowEmpty: true });
      };

      if (type === "city" && typeof ds.query === "function") {
        ds.query(q, {
          mode: "hotel",
          limit: 8,
          signal: apiSignal,
          onPartial: (rows) => {
            if (req !== state.suggestReq || state.anchor !== input) return;
            const items = (rows || []).map((row) => ({
              key: row.city || row.title,
              code: "",
              city: row.city || row.title,
              meta: row.sub || row.tag || "",
              value: row.city || row.title,
            }));
            const merged = ds.filterRows ? ds.filterRows(q, items) : items;
            if (merged.length) paintSuggestItems(input, merged);
          },
        })
          .then((payload) => {
            const items = (payload.rows || []).map((row) => ({
              key: row.city || row.title,
              code: "",
              city: row.city || row.title,
              meta: row.sub || row.tag || "",
              value: row.city || row.title,
            }));
            const merged = ds.filterRows ? ds.filterRows(q, items) : items;
            finish(merged.length ? merged : local, true);
          })
          .catch(() => finish(local, true));
        return;
      }

      if (type === "airport" && typeof ds.queryAirports === "function") {
        ds.queryAirports(q, { limit: 8, signal: apiSignal }).then((payload) => {
          if (payload && payload.aborted) return;
          const items =
            typeof ds.mergeAirportRows === "function"
              ? ds.mergeAirportRows(local, payload.rows || [], 8)
              : (payload.rows || []).length
                ? payload.rows
                : local;
          finish(items, true);
        }).catch(() => {});
      }
    }

    function renderSuggest(input) {
      paintSuggestInstant(input);
      enrichSuggest(input);
    }

    function calHiddenFor(key) {
      if (key === "depart") return $("#depart-date");
      if (key === "return") return $("#return-date");
      if (key === "depart2") return $("#depart2-date");
      if (key === "checkin") return $("#checkin-date");
      if (key === "checkout") return $("#checkout-date");
      if (key === "xp-start") return $("#xp-start-date");
      if (key === "xp-end") return $("#xp-end-date");
      return null;
    }

    function calLabelFor(key) {
      return (
        {
          depart: "Depart",
          return: "Return",
          depart2: "Flight 2 · Depart",
          checkin: "Check-in",
          checkout: "Check-out",
          "xp-start": "Check-in",
          "xp-end": "Check-out",
        }[key] || "Date"
      );
    }

    function applyDate(faceBtn, iso) {
      const key = faceBtn.dataset.cal;
      const hidden = calHiddenFor(key);
      if (hidden) hidden.value = iso;
      faceBtn.textContent = formatFaceDate(iso);
      if (key === "depart" && tripType === "round") {
        const retIn = $("#return-date");
        const retFace = $("#return-face");
        if (retIn && (!retIn.value || retIn.value < iso)) {
          const next = parseIso(iso);
          next.setDate(next.getDate() + 7);
          retIn.value = toIso(next);
          if (retFace) retFace.textContent = formatFaceDate(retIn.value);
        }
      }
      if (key === "checkin") {
        const cout = $("#checkout-date");
        const coutFace = $("#checkout-face");
        if (cout && (!cout.value || cout.value <= iso)) {
          const next = parseIso(iso);
          next.setDate(next.getDate() + 1);
          const nextIso = toIso(next);
          cout.value = nextIso;
          if (coutFace) coutFace.textContent = formatFaceDate(nextIso);
        }
      }
      if (key === "xp-start") {
        const xend = $("#xp-end-date");
        const xendFace = $("#xp-end-face");
        if (xend && (!xend.value || xend.value <= iso)) {
          const next = parseIso(iso);
          next.setDate(next.getDate() + 1);
          const nextIso = toIso(next);
          xend.value = nextIso;
          if (xendFace) xendFace.textContent = formatFaceDate(nextIso);
        }
      }
      closePop();
    }

    function renderCalendar(faceBtn) {
      const key = faceBtn.dataset.cal;
      const hidden = calHiddenFor(key);
      const selected = hidden?.value || "";
      let minIso = isoPlus(0);
      if (key === "return") minIso = $("#depart-date")?.value || isoPlus(0);
      if (key === "depart2") minIso = $("#depart-date")?.value || isoPlus(0);
      if (key === "checkout") minIso = $("#checkin-date")?.value || isoPlus(0);
      if (key === "xp-end") minIso = $("#xp-start-date")?.value || isoPlus(0);
      const label = calLabelFor(key);
      const base = state.calMonth
        ? new Date(state.calMonth.getFullYear(), state.calMonth.getMonth(), 1)
        : selected
          ? parseIso(selected)
          : new Date();
      state.calMonth = new Date(base.getFullYear(), base.getMonth(), 1);

      const y = state.calMonth.getFullYear();
      const m = state.calMonth.getMonth();
      const monthLabel = state.calMonth.toLocaleDateString("en-GB", { month: "long", year: "numeric" });
      // Monday-first (ISO week)
      const firstDow = (new Date(y, m, 1).getDay() + 6) % 7;
      const daysInMonth = new Date(y, m + 1, 0).getDate();
      const todayIso = isoPlus(0);
      const tomorrowIso = isoPlus(1);
      const weekend = (() => {
        const d = new Date();
        const day = d.getDay();
        const add = day === 6 ? 0 : day === 0 ? 6 : 6 - day;
        d.setDate(d.getDate() + add);
        return toIso(d);
      })();

      const prevDisabled = toIso(new Date(y, m, 0)) < minIso;

      openPop("calendar", faceBtn);
      window.ItineroCalendar.mount(pop, { value: selected, min: minIso, onPick: (iso) => applyDate(faceBtn, iso) });
      return;
      const cells = [];
      for (let i = 0; i < firstDow; i++) cells.push(`<span class="dock-pop__day-spacer"></span>`);
      for (let d = 1; d <= daysInMonth; d++) {
        const iso = `${y}-${String(m + 1).padStart(2, "0")}-${String(d).padStart(2, "0")}`;
        const disabled = iso < minIso;
        const on = iso === selected;
        const today = iso === todayIso;
        cells.push(
          `<button type="button" class="dock-pop__day${on ? " is-on" : ""}${today ? " is-today" : ""}" data-iso="${iso}" aria-label="${formatCalTitle(
            iso
          )}" ${disabled ? "disabled" : ""}>${d}</button>`
        );
      }

      const quick = [
        { id: "today", label: "Today", iso: todayIso },
        { id: "tomorrow", label: "Tomorrow", iso: tomorrowIso },
        { id: "weekend", label: "Weekend", iso: weekend },
      ].filter((q) => q.iso >= minIso);

      pop.innerHTML = `
        <div class="dock-pop__cal">
          <div class="dock-pop__cal-top">
            <p class="dock-pop__title">${label}</p>
            <p class="dock-pop__picked">${formatCalTitle(selected || todayIso)}</p>
          </div>
          <div class="dock-pop__quick" role="group" aria-label="Quick dates">
            ${quick
              .map(
                (q) =>
                  `<button type="button" class="dock-pop__chip${selected === q.iso ? " is-on" : ""}" data-quick="${
                    q.iso
                  }">${q.label}</button>`
              )
              .join("")}
          </div>
          <div class="dock-pop__head dock-pop__head--cal">
            <button type="button" class="dock-pop__navbtn" data-nav="-1" aria-label="Previous month" ${
              prevDisabled ? "disabled" : ""
            }>‹</button>
            <p class="dock-pop__month">${monthLabel}</p>
            <button type="button" class="dock-pop__navbtn" data-nav="1" aria-label="Next month">›</button>
          </div>
          <div class="dock-pop__week" aria-hidden="true">
            <span>Mo</span><span>Tu</span><span>We</span><span>Th</span><span>Fr</span><span>Sa</span><span>Su</span>
          </div>
          <div class="dock-pop__grid">${cells.join("")}</div>
        </div>`;

      $$("[data-nav]", pop).forEach((b) =>
        b.addEventListener("click", () => {
          state.calMonth = new Date(y, m + Number(b.dataset.nav), 1);
          renderCalendar(faceBtn);
        })
      );
      $$("[data-quick]", pop).forEach((b) =>
        b.addEventListener("click", () => applyDate(faceBtn, b.dataset.quick))
      );
      $$(".dock-pop__day[data-iso]", pop).forEach((b) =>
        b.addEventListener("click", () => applyDate(faceBtn, b.dataset.iso))
      );
    }

    function syncPaxFace() {
      const adults = Number($("#adults-val")?.value || 1);
      const cabin = $("#cabin-val")?.value || "Economy";
      const face = $("#pax-face");
      if (face) face.textContent = `${adults} Adult${adults > 1 ? "s" : ""} · ${cabin}`;
    }

    function syncGuestsFace() {
      const n = Number($("#guests-val")?.value || 2);
      const face = $("#guests-face");
      if (face) face.textContent = `${n} guest${n > 1 ? "s" : ""}`;
      const xn = Number($("#xp-guests-val")?.value || 2);
      const xface = $("#xp-guests-face");
      if (xface) xface.textContent = `${xn} guest${xn > 1 ? "s" : ""}`;
    }

    function renderPax(faceBtn) {
      let adults = Number($("#adults-val")?.value || 1);
      let cabin = $("#cabin-val")?.value || "Economy";
      openPop("pax", faceBtn);

      function paint() {
        pop.innerHTML = `
          <div class="dock-pop__head"><p class="dock-pop__title">Travellers</p></div>
          <div class="dock-pop__pax">
            <div class="dock-pop__row">
              <div class="dock-pop__row-label"><strong>Adults</strong><span>Age 12+</span></div>
              <div class="dock-pop__step">
                <button type="button" data-ad="-1" aria-label="Fewer adults" ${adults <= 1 ? "disabled" : ""}>−</button>
                <b>${adults}</b>
                <button type="button" data-ad="1" aria-label="More adults" ${adults >= 9 ? "disabled" : ""}>+</button>
              </div>
            </div>
            <div class="dock-pop__row-label"><strong>Cabin</strong><span>How you like to fly</span></div>
            <div class="dock-pop__cabins">
              ${CABINS.map(
                (c) =>
                  `<button type="button" data-cabin="${escapeHtml(c)}" class="${
                    c === cabin ? "is-on" : ""
                  }">${escapeHtml(c)}</button>`
              ).join("")}
            </div>
            <button type="button" class="dock-pop__done">Done</button>
          </div>`;

        $$("[data-ad]", pop).forEach((b) =>
          b.addEventListener("click", () => {
            adults = Math.min(9, Math.max(1, adults + Number(b.dataset.ad)));
            paint();
          })
        );
        $$("[data-cabin]", pop).forEach((b) =>
          b.addEventListener("click", () => {
            cabin = b.dataset.cabin;
            paint();
          })
        );
        $(".dock-pop__done", pop)?.addEventListener("click", () => {
          const a = $("#adults-val");
          const c = $("#cabin-val");
          if (a) a.value = String(adults);
          if (c) c.value = cabin;
          syncPaxFace();
          closePop();
        });
      }
      paint();
    }

    function renderGuests(faceBtn) {
      const xp = faceBtn?.dataset.guests === "xp";
      const valEl = xp ? "#xp-guests-val" : "#guests-val";
      let n = Number($(valEl)?.value || 2);
      openPop("guests", faceBtn);

      function paint() {
        pop.innerHTML = `
          <div class="dock-pop__head"><p class="dock-pop__title">Guests</p></div>
          <div class="dock-pop__pax">
            <div class="dock-pop__row">
              <div class="dock-pop__row-label"><strong>Guests</strong><span>Rooms stay at 1 for now</span></div>
              <div class="dock-pop__step">
                <button type="button" data-g="-1" aria-label="Fewer guests" ${n <= 1 ? "disabled" : ""}>−</button>
                <b>${n}</b>
                <button type="button" data-g="1" aria-label="More guests" ${n >= 8 ? "disabled" : ""}>+</button>
              </div>
            </div>
            <button type="button" class="dock-pop__done">Done</button>
          </div>`;
        $$("[data-g]", pop).forEach((b) =>
          b.addEventListener("click", () => {
            n = Math.min(8, Math.max(1, n + Number(b.dataset.g)));
            paint();
          })
        );
        $(".dock-pop__done", pop)?.addEventListener("click", () => {
          const g = $(valEl);
          if (g) g.value = String(n);
          syncGuestsFace();
          closePop();
        });
      }
      paint();
    }

    const debouncedEnrich =
      window.ItineroDestinationSuggest && typeof window.ItineroDestinationSuggest.debounce === "function"
        ? window.ItineroDestinationSuggest.debounce((input) => enrichSuggest(input))
        : null;

    $$("input[data-suggest]").forEach((input) => {
      input.addEventListener("focus", () => renderSuggest(input));
      input.addEventListener("input", () => {
        if (suggestAbort) suggestAbort.abort();
        const ds = window.ItineroDestinationSuggest;
        if (ds && typeof ds.abortAirportInflight === "function") ds.abortAirportInflight();
        paintSuggestInstant(input);
        if (debouncedEnrich) debouncedEnrich(input);
        else enrichSuggest(input);
      });
      input.addEventListener("keydown", (e) => {
        if (pop.hidden || state.kind !== "suggest" || state.anchor !== input) return;
        const opts = $$(".dock-pop__opt", pop);
        if (!opts.length) return;
        if (e.key === "ArrowDown") {
          e.preventDefault();
          state.activeIdx = Math.min(opts.length - 1, state.activeIdx + 1);
          opts.forEach((o, i) => o.classList.toggle("is-active", i === state.activeIdx));
        } else if (e.key === "ArrowUp") {
          e.preventDefault();
          state.activeIdx = Math.max(0, state.activeIdx - 1);
          opts.forEach((o, i) => o.classList.toggle("is-active", i === state.activeIdx));
        } else if (e.key === "Enter") {
          e.preventDefault();
          opts[state.activeIdx]?.click();
        } else if (e.key === "Escape") {
          closePop();
        }
      });
    });

    ["depart-face", "return-face", "depart2-face", "checkin-face", "checkout-face", "xp-start-face", "xp-end-face"].forEach((id) => {
      $(`#${id}`)?.addEventListener("click", () => {
        state.calMonth = null;
        renderCalendar($(`#${id}`));
      });
    });
    $("#pax-face")?.addEventListener("click", () => renderPax($("#pax-face")));
    $("#guests-face")?.addEventListener("click", () => renderGuests($("#guests-face")));
    $("#origin2-input")?.addEventListener("input", () => {
      $("#origin2-input").dataset.auto = "0";
    });

    document.addEventListener("click", (e) => {
      if (pop.hidden) return;
      if (pop.contains(e.target)) return;
      if (state.anchor && (state.anchor === e.target || state.anchor.contains?.(e.target))) return;
      if (e.target.closest?.(".cell") && e.target.closest(".cell").contains(state.anchor)) return;
      closePop();
    });
    window.addEventListener(
      "resize",
      () => {
        if (!pop.hidden && state.anchor) placePop(state.anchor.closest(".cell") || state.anchor);
      },
      { passive: true }
    );
    window.addEventListener(
      "scroll",
      () => {
        if (!pop.hidden && state.anchor) placePop(state.anchor.closest(".cell") || state.anchor);
      },
      { passive: true }
    );

    // Seed faces from hidden dates
    const depart = $("#depart-date");
    const ret = $("#return-date");
    const dep2 = $("#depart2-date");
    const cin = $("#checkin-date");
    const cout = $("#checkout-date");
    const xstart = $("#xp-start-date");
    const xend = $("#xp-end-date");
    if (depart && !depart.value) depart.value = isoPlus(14);
    if (ret && !ret.value) {
      const d = parseIso(depart.value);
      d.setDate(d.getDate() + 7);
      ret.value = toIso(d);
    }
    if (dep2 && !dep2.value) {
      const d = parseIso(depart.value);
      d.setDate(d.getDate() + 3);
      dep2.value = toIso(d);
    }
    if (cin && !cin.value) cin.value = isoPlus(21);
    if (cout && !cout.value) cout.value = isoPlus(24);
    if (xstart && !xstart.value) xstart.value = isoPlus(21);
    if (xend && !xend.value) xend.value = isoPlus(24);
    const faces = [
      ["depart-face", depart],
      ["return-face", ret],
      ["depart2-face", dep2],
      ["checkin-face", cin],
      ["checkout-face", cout],
      ["xp-start-face", xstart],
      ["xp-end-face", xend],
    ];
    faces.forEach(([id, input]) => {
      const el = $(`#${id}`);
      if (el) el.textContent = formatFaceDate(input?.value);
    });
    syncPaxFace();
    syncGuestsFace();
  }

  const PROTO_SESSION = "itinero_proto_session_v1";
  const TOKEN_KEY = "itinero_auth_token";

  function readSession() {
    const chrome = window.ItineroChrome;
    if (chrome?.readSession) return chrome.readSession();
    try {
      const raw = localStorage.getItem(PROTO_SESSION);
      const s = raw ? JSON.parse(raw) : null;
      if (!s || typeof s !== "object") return null;
      if (s.email || s.phone || s.id) return s;
      return null;
    } catch (_) {
      return null;
    }
  }

  function initialsFromSession(s) {
    if (s?.name) return s.name.trim().charAt(0).toUpperCase();
    const hint = String(s?.email || s?.phone || "A");
    return (hint.charAt(0) || "A").toUpperCase();
  }

  function localWatches() {
    try {
      const raw = JSON.parse(localStorage.getItem("itinero.wl.watches.v1") || "[]");
      return Array.isArray(raw) ? raw : [];
    } catch (_) {
      return [];
    }
  }

  function watchTitle(w) {
    if (!w || typeof w !== "object") return "Price watch";
    if (w.route) return String(w.route);
    if (w.name) return String(w.name);
    if (String(w.kind || "").toLowerCase() === "hotel") {
      return String(w.destination || w.destinationLabel || "Stay watch");
    }
    const o = w.origin || w.originLabel || "";
    const d = w.destination || w.destinationLabel || "";
    if (o && d) return `${o} → ${d}`;
    return "Price watch";
  }

  function watchHint(w) {
    if (!w || typeof w !== "object") return "";
    if (w.note) return String(w.note);
    if (w.lastAlertedAt) return "We emailed you when the live fare dropped.";
    const price = Number(w.lastPrice || w.baselinePrice || w.price || 0);
    const cur = String(w.currency || "").toUpperCase();
    if (price > 0) {
      try {
        return `Watching around ${new Intl.NumberFormat("en-US", {
          style: "currency",
          currency: cur || "USD",
          maximumFractionDigits: 0,
        }).format(price)} · not a price lock`;
      } catch (_) {
        return `Watching around ${cur} ${Math.round(price)} · not a price lock`;
      }
    }
    return "We email you if the live fare drops — not a price lock.";
  }

  function watchHref(w) {
    if (w?.href) return String(w.href);
    const o = encodeURIComponent(w?.origin || "");
    const d = encodeURIComponent(w?.destination || "");
    if (o && d) return `/flights/?from=${o}&to=${d}`;
    return "/flights/";
  }

  function mergeWatches(serverRows, localRows) {
    const out = [];
    const seen = new Set();
    const push = (w) => {
      if (!w || typeof w !== "object") return;
      const key =
        String(w.id || "") ||
        `${w.kind || "flight"}:${w.origin || ""}-${w.destination || ""}-${w.route || w.name || ""}`;
      if (!key || seen.has(key)) return;
      seen.add(key);
      out.push(w);
    };
    (serverRows || []).forEach(push);
    (localRows || []).forEach(push);
    return out;
  }

  function paintAlertsAuth(session) {
    const copy = $("#alerts-empty-copy") || $("#alerts-empty")?.querySelector(".sheet__empty-copy");
    const cta = $("#alerts-cta") || $("#alerts-panel")?.querySelector(".sheet__link");
    if (session) {
      if (copy) {
        copy.textContent =
          "Price watches and trip drafts show up here when you save them. We never invent placeholders.";
      }
      if (cta) {
        cta.hidden = false;
        cta.textContent = "Manage account";
        cta.setAttribute("href", "/account/");
      }
    } else {
      if (copy) {
        copy.textContent =
          "After you sign in, price watches and trip drafts show up here. We never use invented placeholders.";
      }
      if (cta) {
        cta.hidden = false;
        cta.textContent = "Sign in for live alerts";
        cta.setAttribute("href", "/homepage/signin.html");
      }
    }
  }

  async function refreshAlertsPanel(session) {
    paintAlertsAuth(session);
    const empty = $("#alerts-empty");
    const list = $("#alerts-list");
    const cta = $("#alerts-cta") || $("#alerts-panel")?.querySelector(".sheet__link");
    let server = [];
    if (session) {
      try {
        const chrome = window.ItineroChrome;
        const res = await fetch("/api/watches", {
          ...(chrome?.authFetchOpts?.() || { credentials: "include" }),
          headers: chrome?.authHeaders?.() || { Accept: "application/json" },
        });
        const data = await res.json().catch(() => ({}));
        if (res.ok && Array.isArray(data.watches)) server = data.watches;
      } catch (_) {
        /* keep local watches */
      }
    }
    const watches = mergeWatches(server, localWatches()).slice(0, 8);
    if (!watches.length) {
      if (empty) empty.hidden = false;
      if (list) {
        list.hidden = true;
        list.innerHTML = "";
      }
      paintAlertsAuth(session);
      return;
    }
    if (empty) empty.hidden = true;
    if (list) {
      list.hidden = false;
      list.innerHTML = watches
        .map((w) => {
          const href = escapeHtml(watchHref(w));
          const title = escapeHtml(watchTitle(w));
          const hint = escapeHtml(watchHint(w));
          return `<li><a href="${href}"><strong>${title}</strong><span>${hint}</span></a></li>`;
        })
        .join("");
    }
    if (cta) {
      if (session) {
        cta.hidden = false;
        cta.textContent = "Manage account";
        cta.setAttribute("href", "/account/");
      } else {
        cta.hidden = false;
        cta.textContent = "Sign in for live alerts";
        cta.setAttribute("href", "/homepage/signin.html");
      }
    }
  }

  function paintAuthChrome(session) {
    const signin = $("#top-signin");
    const account = $("#top-account");
    const drawerSignin = $("#drawer-signin");
    const drawerSignup = $("#drawer-signup");
    const drawerSignout = $("#drawer-signout");
    const drawerNote = $("#drawer-auth-note");
    const contact = session?.email || session?.phone || "";

    if (session) {
      if (signin) signin.hidden = true;
      if (account) account.hidden = false;
      const avatar = $("#account-avatar");
      const label = $("#account-label");
      const email = $("#account-email");
      if (avatar) avatar.textContent = initialsFromSession(session);
      if (label) label.textContent = session.name || "Account";
      if (email) email.textContent = contact;
      if (drawerSignin) drawerSignin.hidden = true;
      if (drawerSignup) drawerSignup.hidden = true;
      if (drawerSignout) drawerSignout.hidden = false;
      if (drawerNote) drawerNote.textContent = contact ? `Signed in as ${contact}` : "Signed in";
    } else {
      if (signin) signin.hidden = false;
      if (account) account.hidden = true;
      if (drawerSignin) {
        drawerSignin.hidden = false;
        drawerSignin.textContent = "Sign in";
        drawerSignin.href = "/homepage/signin.html";
      }
      if (drawerSignup) drawerSignup.hidden = false;
      if (drawerSignout) drawerSignout.hidden = true;
      if (drawerNote) drawerNote.textContent = "Sync trips, DNA, and alerts across devices.";
    }
    paintAlertsAuth(session);
  }

  function wireAuthChrome() {
    const chrome = window.ItineroChrome;
    // Shared chrome owns menu/sign-out when present — avoid double listeners.
    if (chrome?.wireChrome) {
      const sync = (session) => {
        chrome.wireChrome();
        paintAuthChrome(session || chrome.readSession?.() || readSession());
      };
      // Prefer cookie hydrate before paint so signed-in chrome doesn't flash Sign in.
      Promise.resolve(chrome.fetchAuthConfig?.())
        .then(() => chrome.hydrateAuth?.())
        .then((session) => sync(session))
        .catch(() => sync(readSession()));
      const drawerSignout = $("#drawer-signout");
      if (drawerSignout && !drawerSignout.dataset.authWired) {
        drawerSignout.dataset.authWired = "1";
        drawerSignout.addEventListener("click", () => {
          if (chrome.signOut) chrome.signOut();
        });
      }
      if (new URLSearchParams(location.search).has("signedin")) {
        const url = new URL(location.href);
        url.searchParams.delete("signedin");
        history.replaceState({}, "", url.pathname + url.search);
      }
      return;
    }

    paintAuthChrome(readSession());

    const account = $("#top-account");
    const btn = $("#account-btn");
    const menu = $("#account-menu");
    if (btn && !btn.dataset.authWired) {
      btn.dataset.authWired = "1";
      const closeMenu = () => {
        if (!menu || !btn) return;
        menu.hidden = true;
        btn.setAttribute("aria-expanded", "false");
      };
      btn.addEventListener("click", (e) => {
        e.stopPropagation();
        if (!menu) return;
        const open = menu.hidden;
        menu.hidden = !open;
        btn.setAttribute("aria-expanded", open ? "true" : "false");
      });
      document.addEventListener("click", (e) => {
        if (!account?.contains(e.target)) closeMenu();
      });
      const signOut = async () => {
        try {
          await fetch("/api/v1/auth/logout", {
            method: "POST",
            credentials: "include",
            headers: { Accept: "application/json", "Content-Type": "application/json" },
          });
        } catch (_) {}
        try {
          localStorage.removeItem(PROTO_SESSION);
          localStorage.removeItem(TOKEN_KEY);
        } catch (_) {}
        closeMenu();
        location.href = "/homepage/";
      };
      $("#signout-btn")?.addEventListener("click", signOut);
      $("#drawer-signout")?.addEventListener("click", signOut);
    }

    if (new URLSearchParams(location.search).has("signedin")) {
      const url = new URL(location.href);
      url.searchParams.delete("signedin");
      history.replaceState({}, "", url.pathname + url.search);
    }
  }

  function wireCurrency() {
    const host = $("#home-currency");
    const loc = window.ItineroLocale;
    if (!host || !loc) return;
    const cur = loc.currency ? loc.currency() : "USD";
    const refresh = () => {
      HOME_LOCALE = (loc.get && loc.get()) || HOME_LOCALE;
      hydrateBrandCatalog();
      renderBrowse();
      paintInviteLocale();
    };
    if (typeof loc.mountCurrency === "function") {
      loc.mountCurrency(host, { currency: cur, onChange: refresh });
    } else if (host.tagName === "SELECT") {
      if (typeof loc.optionHtml === "function") host.innerHTML = loc.optionHtml(cur);
      else host.innerHTML = `<option value="${escapeHtml(cur)}">${escapeHtml(cur)}</option>`;
      host.value = cur;
      host.addEventListener("change", () => {
        if (typeof loc.setCurrency === "function") loc.setCurrency(host.value, { lock: true });
        refresh();
      });
    }
    // Locale events cover auto-mounted controls (DOMContentLoaded) and external setCurrency.
    window.addEventListener("itinero:locale", () => {
      if (host._currencyCtl && typeof host._currencyCtl.paint === "function") host._currencyCtl.paint();
      refresh();
    });
  }

  async function bootLocale() {
    const loc = window.ItineroLocale;
    if (!loc || typeof loc.detect !== "function") {
      HOME_LOCALE = {};
      return HOME_LOCALE;
    }
    try {
      HOME_LOCALE = (await loc.detect({ precise: true, preciseTimeoutMs: 4200 })) || loc.get() || {};
    } catch (_) {
      HOME_LOCALE = (loc.get && loc.get()) || {};
    }
    return HOME_LOCALE;
  }

  async function bootBrandMedia() {
    const bm = window.ItineroBrandMedia;
    if (!bm || typeof bm.load !== "function") return false;
    try {
      await bm.load();
      hydrateBrandCatalog();
      bm.startHeroRotation($("#stage-img"), $("#stage-place"));
      return true;
    } catch (_) {
      return false;
    }
  }

  async function init() {
    $$(".dock__mode").forEach((b) => b.addEventListener("click", () => setMode(b.dataset.mode)));
    $$(".dock__trip-btn").forEach((b) => b.addEventListener("click", () => setTripType(b.dataset.trip)));
    $$("a[data-mode]").forEach((a) =>
      a.addEventListener("click", () => {
        if (a.dataset.mode) setMode(a.dataset.mode);
      })
    );

    // Wire suggest/calendar before locale/hero async — Next injects HTML then loads app.js late.
    wireDockPickers();
    wireSearch();

    const top = $("#top");
    const onScroll = () => top?.classList.toggle("is-solid", window.scrollY > 48);
    window.addEventListener("scroll", onScroll, { passive: true });
    onScroll();

    const year = $("#footer-year");
    if (year) year.textContent = String(new Date().getFullYear());

    await bootLocale();
    wireCurrency();
    await bootBrandMedia();

    renderBrowse();
    scrubSeededRecent();
    renderRecent();
    wireRecent();
    wireStartPaths();
    wireInvite();
    wireChrome();
    wireAuthChrome();
    // Final auth paint after chrome + app listeners are ready (Notifications CTA too).
    Promise.resolve(window.ItineroChrome?.hydrateAuth?.())
      .then((session) => {
        window.ItineroChrome?.wireChrome?.();
        paintAuthChrome(session || readSession());
      })
      .catch(() => paintAuthChrome(readSession()));
    wireHeroChat();
    wireReveals();
    setMode("flights");
    requestAnimationFrame(() => $(".stage")?.classList.add("is-ready"));
  }

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", () => {
    init();
  });
  else init();
})();

