/** Shared static-page footer newsletter (matches SPA PageLayout subscribe). */
(function () {
  "use strict";
  function bind(form) {
    if (!form || form.getAttribute("data-itinero-news") === "1") return;
    form.setAttribute("data-itinero-news", "1");
    var status =
      form.querySelector(".footer__subscribeStatus") ||
      document.getElementById("footer-newsletter-status");
    var input = form.querySelector('input[type="email"]');
    var btn = form.querySelector('button[type="submit"]');
    form.addEventListener("submit", function (e) {
      e.preventDefault();
      if (!input || !input.value.trim()) return;
      if (btn) btn.disabled = true;
      if (status) {
        status.hidden = false;
        status.textContent = "…";
      }
      fetch("/api/newsletter/subscribe", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          email: input.value.trim(),
          acq_source: "newsletter",
          acq_medium: "footer",
          acq_campaign: "site_newsletter",
          landing_path: window.location.pathname || "/",
        }),
      })
        .then(function (res) {
          return res.json().then(function (data) {
            if (!res.ok) throw new Error(data.detail || data.message || "Could not subscribe");
            return data;
          });
        })
        .then(function () {
          if (status) status.textContent = "Subscribed — watch your inbox for trip ideas.";
          input.value = "";
        })
        .catch(function (err) {
          if (status) status.textContent = (err && err.message) || "Could not subscribe. Try again.";
        })
        .finally(function () {
          if (btn) btn.disabled = false;
        });
    });
  }
  function boot() {
    document.querySelectorAll("form.footer__subscribe").forEach(bind);
  }
  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }
})();

