/**
 * Homepage brand media — destination-keyed catalog + optional LiteAPI hotel photos.
 * Source of truth: /homepage/brand-media.json
 */
(function (root) {
  "use strict";

  var CATALOG_URL = "/homepage/brand-media.json?v=6";
  var catalog = null;
  var heroTimer = 0;
  var heroIdx = 0;
  /** Unsplash photo ids claimed this homepage pass (hero first, then shelves). */
  var claimedPhotos = Object.create(null);
  /** Last-resort travel photo — homepage must never paint blank media. */
  var DEFAULT_UNSPLASH =
    "https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w={w}&q={q}";

  function localeCurrency() {
    if (root.ItineroLocale && typeof root.ItineroLocale.currency === "function") {
      return root.ItineroLocale.currency() || "USD";
    }
    try {
      var raw = localStorage.getItem("itinero_currency") || "";
      if (/^[A-Z]{3}$/.test(raw)) return raw;
    } catch (_) {}
    return "USD";
  }

  function localeSnapshot() {
    if (root.ItineroLocale && typeof root.ItineroLocale.get === "function") {
      return root.ItineroLocale.get() || {};
    }
    return {};
  }

  function moneyFmt(amount, currency) {
    var cur = String(currency || localeCurrency() || "USD").toUpperCase();
    if (root.ItineroLocale && typeof root.ItineroLocale.money === "function") {
      var pretty = root.ItineroLocale.money(amount, cur);
      if (pretty) return pretty;
    }
    return formatPrice(amount, cur);
  }

  function daySeed() {
    var d = new Date();
    return Math.floor(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / 86400000);
  }

  function hash(str) {
    var h = 0;
    var s = String(str || "");
    for (var i = 0; i < s.length; i++) h = (h * 31 + s.charCodeAt(i)) >>> 0;
    return h;
  }

  function sizeUrl(tpl, w, q) {
    if (!tpl) return "";
    return String(tpl)
      .replace(/\{w\}/g, String(w || 1600))
      .replace(/\{q\}/g, String(q || 75));
  }

  /**
   * Always return a paint-able Unsplash URL for a destination (or global default).
   * Used when LiteAPI / remote thumbs fail so shelves never go blank.
   */
  function unsplashFallback(destinationId, opts) {
    opts = opts || {};
    var w = opts.w || opts.cardW || 900;
    var q = opts.q || opts.cardQ || 75;
    var d = dest(destinationId);
    if (d) {
      var heroes = Array.isArray(d.heroes) ? d.heroes.filter(Boolean) : [];
      for (var i = 0; i < heroes.length; i++) {
        var url = sizeUrl(heroes[i], w, q);
        if (url) return url;
      }
    }
    return sizeUrl(DEFAULT_UNSPLASH, w, q);
  }

  function dest(id) {
    if (!catalog || !catalog.destinations) return null;
    return catalog.destinations[id] || null;
  }

  function photoKey(tpl) {
    var m = String(tpl || "").match(/\/(photo-[a-zA-Z0-9_-]+)/);
    return m ? m[1] : String(tpl || "");
  }

  function resetPhotoClaims() {
    claimedPhotos = Object.create(null);
  }

  function claimHeroPlaylist() {
    if (!catalog) return;
    var playlist = catalog.hero_playlist || [];
    playlist.forEach(function (id) {
      var d = dest(id);
      var heroes = d && Array.isArray(d.heroes) ? d.heroes.filter(Boolean) : [];
      if (!heroes.length) return;
      /* heroes[0] is reserved for the hero stage for playlist destinations */
      claimedPhotos[photoKey(heroes[0])] = "hero";
    });
  }

  /**
   * Role-aware photo pick. Hero playlist locks heroes[0]; shelves prefer later
   * frames and never reuse a claimed Unsplash id when an alternate exists.
   */
  function pickTpl(d, opts) {
    opts = opts || {};
    if (!d) return "";
    var heroes = Array.isArray(d.heroes) ? d.heroes.filter(Boolean) : [];
    if (!heroes.length) return "";
    var role = opts.role || "shelf";
    var salt = opts.salt || d.label || "";

    if (role === "hero") {
      var hi = (daySeed() + hash(salt)) % heroes.length;
      var heroTpl = heroes[hi] || heroes[0];
      claimedPhotos[photoKey(heroTpl)] = "hero";
      return heroTpl;
    }

    var order = [];
    var i;
    for (i = 1; i < heroes.length; i++) order.push(heroes[i]);
    order.push(heroes[0]);
    /* Prefer unclaimed; salt rotates among unclaimed when several exist */
    var free = order.filter(function (tpl) {
      return !claimedPhotos[photoKey(tpl)];
    });
    var pool = free.length ? free : order;
    var pick = pool[(daySeed() + hash(role + ":" + salt)) % pool.length];
    claimedPhotos[photoKey(pick)] = role;
    return pick;
  }

  /** @deprecated — use pickTpl with role */
  function pickHeroTpl(d, salt) {
    return pickTpl(d, { role: "hero", salt: salt });
  }

  function mediaFor(id, opts) {
    opts = opts || {};
    var d = dest(id);
    if (!d) {
      return { city: id, img: "", bg: "", line: "", region: "", destination: id, photo: "" };
    }
    var tpl = pickTpl(d, {
      role: opts.role || "shelf",
      salt: opts.salt || id,
    });
    var cardW = opts.cardW || 700;
    var heroW = opts.heroW || 1600;
    return {
      destination: id,
      city: d.label,
      region: d.region || "",
      iata: d.iata || "",
      lat: d.lat,
      lng: d.lng,
      line: d.line || "",
      photo: photoKey(tpl),
      img: sizeUrl(tpl, cardW, opts.cardQ || 75),
      bg: sizeUrl(tpl, heroW, opts.heroQ || 70),
    };
  }

  function mapRoute(row) {
    var m = mediaFor(row.destination, {
      role: "route",
      cardW: 1100,
      heroW: 1600,
      salt: "route:" + (row.from || "") + "-" + (row.to || ""),
    });
    return {
      from: row.from,
      to: row.to,
      city: m.city || row.destination,
      blurb: row.blurb || m.line,
      tag: row.tag || "Open live fares",
      img: m.img,
      bg: m.bg,
      photo: m.photo,
      destination: row.destination,
      /* Never invent fares — CTA only */
      price: "",
    };
  }

  function flightRoutes(opts) {
    opts = opts || {};
    if (!catalog) return [];
    claimHeroPlaylist();
    var loc = localeSnapshot();
    var country = String(opts.country || loc.country || "").toUpperCase();
    var airport = String(opts.airport || loc.airport || "")
      .trim()
      .toUpperCase();
    var by = catalog.flight_routes_by_country || {};
    var rows = (by[country] || by.default || catalog.flight_deals || []).slice();
    if (airport) {
      rows.sort(function (a, b) {
        var aHit = a.from === airport ? 1 : 0;
        var bHit = b.from === airport ? 1 : 0;
        return bHit - aHit;
      });
    }
    return rows.map(mapRoute);
  }

  /** @deprecated use flightRoutes — kept for older app.js callers */
  function flightDeals() {
    return flightRoutes();
  }

  function worldStays() {
    if (!catalog) return [];
    claimHeroPlaylist();
    return (catalog.world_stays || []).map(function (row) {
      var m = mediaFor(row.destination, {
        role: "stay",
        cardW: 400,
        heroW: 1600,
        salt: "world:" + row.destination,
      });
      return {
        city: m.city,
        title: row.title || "Hotels in " + m.city,
        where: row.where || m.region,
        score: "",
        label: "",
        reviews: "",
        price: "",
        img: m.img,
        bg: m.bg,
        photo: m.photo,
        destination: row.destination,
        search: row.search || m.city,
        lat: m.lat,
        lng: m.lng,
        live: false,
      };
    });
  }

  function nearByCity() {
    if (!catalog) return {};
    claimHeroPlaylist();
    var out = {};
    var src = catalog.near_by_city || {};
    Object.keys(src).forEach(function (home) {
      out[home] = (src[home] || []).map(function (row) {
        var m = mediaFor(row.destination, {
          role: "stay",
          cardW: 400,
          heroW: 1600,
          salt: "near:" + home + ":" + (row.title || row.destination),
        });
        return {
          city: row.city || m.city,
          title: row.title,
          where: row.where,
          score: "",
          label: "",
          reviews: "",
          price: "",
          img: m.img,
          bg: m.bg,
          photo: m.photo,
          destination: row.destination,
          search: row.search || row.city || m.city,
          lat: m.lat,
          lng: m.lng,
          live: false,
        };
      });
    });
    return out;
  }

  function resolveForkPath(path) {
    if (!path) return null;
    var m = mediaFor(path.destination, {
      role: "fork",
      cardW: 1200,
      heroW: 1600,
      salt: "fork:" + path.destination,
    });
    return {
      label: path.label,
      city: m.city,
      hint: path.hint || m.line,
      price: "Explore stays",
      area: path.area || m.region,
      img: m.img,
      bg: m.bg,
      photo: m.photo,
      destination: path.destination,
    };
  }

  function forkByCity() {
    if (!catalog) return {};
    var out = {};
    var src = catalog.fork_by_city || {};
    Object.keys(src).forEach(function (home) {
      var f = src[home];
      out[home] = {
        title: f.title,
        sub: f.sub,
        a: resolveForkPath(f.a),
        b: resolveForkPath(f.b),
      };
    });
    return out;
  }

  function forkFallback(country) {
    if (!catalog) return null;
    var cc = String(country || localeSnapshot().country || "")
      .trim()
      .toUpperCase();
    var by = catalog.fork_fallback_by_country || {};
    var f = (cc && by[cc]) || catalog.fork_fallback;
    if (!f) return null;
    return {
      title: f.title,
      sub: f.sub,
      a: resolveForkPath(f.a),
      b: resolveForkPath(f.b),
    };
  }

  /** Resolve weekend fork for a home city + country (US State College, IN Mumbai, …). */
  function forkForHome(home, country) {
    var byCity = forkByCity();
    if (home && byCity[home]) return byCity[home];
    return forkFallback(country);
  }

  function isoPlus(days) {
    var d = new Date();
    d.setDate(d.getDate() + days);
    return d.toISOString().slice(0, 10);
  }

  function badHotelSrc(src) {
    return !src || /hotel_room\.png|no[-_]?image|no[-_]?photo|placeholder|image[-_]?unavailable|blank\.gif/i.test(src);
  }

  function hotelThumb(h) {
    if (!h) return "";
    var imgs = Array.isArray(h.images) ? h.images : [];
    var raw = h.image || h.main_photo || imgs[0] || "";
    var src = typeof raw === "string" ? raw : (raw && raw.url) || "";
    return badHotelSrc(src) ? "" : src;
  }

  function hotelScore(h) {
    var rating = Number(h.rating) || Number(h.score) || 0;
    if (rating > 0 && rating <= 5) return Number((rating * 2).toFixed(1));
    if (rating > 0) return Number(rating.toFixed(1));
    return 0;
  }

  function formatPrice(amount, currency) {
    var n = Number(amount);
    if (!(n > 0)) return "";
    var cur = String(currency || localeCurrency() || "USD").toUpperCase();
    try {
      var locale = cur === "INR" ? "en-IN" : cur === "GBP" ? "en-GB" : "en-US";
      return new Intl.NumberFormat(locale, {
        style: "currency",
        currency: cur,
        maximumFractionDigits: 0,
      }).format(n);
    } catch (_) {
      return cur + " " + Math.round(n).toLocaleString("en-US");
    }
  }

  function scoreLabel(score) {
    if (score >= 9) return "Superb";
    if (score >= 8.5) return "Excellent";
    if (score >= 8) return "Very good";
    if (score >= 7) return "Good";
    return "Guest rated";
  }

  function mapHotelCard(h, city, data) {
    var thumb = hotelThumb(h);
    if (!thumb) return null;
    if (h.has_price === false) return null;
    var price = Number(h.pricePerNight) || Number(h.totalPrice) || 0;
    if (!(price > 0)) return null;
    var score = hotelScore(h);
    var cur = data.currency || h.currency || localeCurrency();
    var liveCity = (data.geo && (data.geo.city || data.geo.name)) || h.city || city;
    return {
      city: liveCity,
      title: h.name || "Stay",
      where: liveCity + " · live stay",
      score: score ? String(score) : "",
      label: score ? scoreLabel(score) : "",
      reviews: "",
      price: moneyFmt(price, cur),
      img: thumb,
      bg: thumb,
      destination: city,
      search: city,
      liveHotelId: String(h.id || h.hotelId || ""),
      live: true,
      lat: h.latitude != null ? Number(h.latitude) : undefined,
      lng: h.longitude != null ? Number(h.longitude) : undefined,
    };
  }

  function fetchHotels(city, lat, lng, pageSize) {
    var p = new URLSearchParams({
      city: city || "",
      check_in: isoPlus(21),
      check_out: isoPlus(23),
      guests: "2",
      rooms: "1",
      currency: localeCurrency(),
      language: "en",
      page: "1",
      page_size: String(pageSize || 6),
    });
    var loc = localeSnapshot();
    if (loc.country) p.set("nationality", String(loc.country).slice(0, 2));
    if (lat != null && !Number.isNaN(Number(lat))) p.set("latitude", String(lat));
    if (lng != null && !Number.isNaN(Number(lng))) p.set("longitude", String(lng));
    return fetch("/api/hotels/search?" + p.toString(), { headers: { Accept: "application/json" } })
      .then(function (res) {
        if (!res.ok) throw new Error("search_" + res.status);
        return res.json();
      })
      .then(function (data) {
        var hotels = Array.isArray(data.hotels) ? data.hotels : [];
        var geoCity = (data.geo && (data.geo.city || data.geo.name)) || city;
        return {
          data: data,
          city: geoCity,
          cards: hotels.map(function (h) {
            return mapHotelCard(h, geoCity, data);
          }).filter(Boolean),
        };
      })
      .catch(function () {
        return { data: {}, city: city, cards: [] };
      });
  }

  function fetchCityHotel(city, lat, lng) {
    return fetchHotels(city, lat, lng, 6).then(function (pack) {
      return pack.cards[0] || null;
    });
  }

  /** Live hotels near lat/lng (or city). Empty array on failure — never invent. */
  function fetchNearbyHotels(opts) {
    opts = opts || {};
    var loc = localeSnapshot();
    var city = opts.city || loc.city || "";
    var lat = opts.lat != null ? opts.lat : loc.lat;
    var lng = opts.lng != null ? opts.lng : loc.lng;
    var limit = Math.max(2, Math.min(8, opts.limit || 4));
    if (!city && (lat == null || lng == null)) return Promise.resolve([]);
    return fetchHotels(city || "nearby", lat, lng, Math.max(limit, 8)).then(function (pack) {
      return pack.cards.slice(0, limit);
    });
  }

  function enrichStay(item) {
    var city = item.search || item.city;
    if (!city) return Promise.resolve(item);
    return fetchCityHotel(city, item.lat, item.lng).then(function (live) {
      if (!live) return item;
      return Object.assign({}, item, live, {
        destination: item.destination || live.destination,
        search: item.search || live.search,
      });
    });
  }

  function enrichStayList(list, concurrency) {
    var items = Array.isArray(list) ? list.slice() : [];
    var limit = Math.max(1, concurrency || 3);
    var i = 0;
    var out = new Array(items.length);

    function worker() {
      if (i >= items.length) return Promise.resolve();
      var idx = i++;
      return enrichStay(items[idx]).then(function (row) {
        out[idx] = row;
        return worker();
      });
    }

    var starters = [];
    for (var w = 0; w < Math.min(limit, items.length); w++) starters.push(worker());
    return Promise.all(starters).then(function () {
      return out;
    });
  }

  function stopHeroRotation() {
    if (heroTimer) {
      root.clearInterval(heroTimer);
      heroTimer = 0;
    }
  }

  function applyHeroFrame(imgEl, placeEl, id) {
    var d = dest(id);
    if (!d || !imgEl) return;
    var heroes = Array.isArray(d.heroes) ? d.heroes.filter(Boolean) : [];
    var attempt = 0;

    function tryHero() {
      var tpl = heroes[attempt] || "";
      var url = tpl ? sizeUrl(tpl, 2400, 80) : unsplashFallback(id, { w: 2400, q: 80 });
      if (!url) {
        url = sizeUrl(DEFAULT_UNSPLASH, 2400, 80);
      }
      if (tpl) claimedPhotos[photoKey(tpl)] = "hero";
      var probe = new Image();
      probe.onload = function () {
        imgEl.style.transition = "opacity 0.55s ease";
        imgEl.style.opacity = "0";
        root.setTimeout(function () {
          imgEl.src = url;
          imgEl.dataset.destination = id;
          if (tpl) imgEl.dataset.photo = photoKey(tpl);
          imgEl.style.opacity = "1";
          if (placeEl) {
            placeEl.textContent = d.label + (d.region ? " · " + d.region : "");
            placeEl.hidden = false;
          }
        }, 240);
      };
      probe.onerror = function () {
        attempt += 1;
        if (attempt < heroes.length) {
          tryHero();
          return;
        }
        /* Exhausted destination heroes — paint global Unsplash so hero never blanks. */
        var emergency = sizeUrl(DEFAULT_UNSPLASH, 2400, 80);
        imgEl.src = emergency;
        imgEl.dataset.destination = id;
        imgEl.dataset.photo = photoKey(DEFAULT_UNSPLASH);
        imgEl.style.opacity = "1";
        if (placeEl) {
          placeEl.textContent = d.label + (d.region ? " · " + d.region : "");
          placeEl.hidden = false;
        }
      };
      probe.src = url;
    }

    tryHero();
  }

  function startHeroRotation(imgEl, placeEl, opts) {
    opts = opts || {};
    stopHeroRotation();
    if (!catalog || !imgEl) return { stop: stopHeroRotation };
    resetPhotoClaims();
    claimHeroPlaylist();
    var playlist = (catalog.hero_playlist || []).filter(function (id) {
      return !!dest(id);
    });
    if (!playlist.length) return { stop: stopHeroRotation };

    heroIdx = daySeed() % playlist.length;
    if (opts.immediate !== false) {
      var firstId = playlist[heroIdx];
      var first = dest(firstId);
      var heroes = first && Array.isArray(first.heroes) ? first.heroes.filter(Boolean) : [];
      var tpl = heroes[0] || "";
      var boot = sizeUrl(tpl, 2400, 80) || unsplashFallback(firstId, { w: 2400, q: 80 });
      if (boot) {
        imgEl.src = boot;
        imgEl.dataset.destination = firstId;
        if (tpl) imgEl.dataset.photo = photoKey(tpl);
        imgEl.onerror = function () {
          if (imgEl.dataset.unsplashFallback === "1") return;
          imgEl.dataset.unsplashFallback = "1";
          imgEl.src = unsplashFallback(firstId, { w: 2400, q: 80 });
        };
      }
      if (placeEl && first) {
        placeEl.textContent = first.label + (first.region ? " · " + first.region : "");
        placeEl.hidden = false;
      }
    }

    var reduce =
      root.matchMedia && root.matchMedia("(prefers-reduced-motion: reduce)").matches;
    var ms = Number(catalog.hero_rotation_ms) || 14000;
    if (reduce || playlist.length < 2 || opts.rotate === false) {
      return { stop: stopHeroRotation, index: heroIdx, playlist: playlist };
    }

    heroTimer = root.setInterval(function () {
      heroIdx = (heroIdx + 1) % playlist.length;
      applyHeroFrame(imgEl, placeEl, playlist[heroIdx]);
    }, ms);

    return { stop: stopHeroRotation, index: heroIdx, playlist: playlist };
  }

  function initialHeroUrl() {
    if (!catalog) return "";
    var playlist = catalog.hero_playlist || [];
    if (!playlist.length) return "";
    var id = playlist[daySeed() % playlist.length];
    var d = dest(id);
    var heroes = d && Array.isArray(d.heroes) ? d.heroes.filter(Boolean) : [];
    return sizeUrl(heroes[0] || "", 2400, 80);
  }

  function load() {
    return fetch(CATALOG_URL, { headers: { Accept: "application/json" } })
      .then(function (res) {
        if (!res.ok) throw new Error("brand_media_" + res.status);
        return res.json();
      })
      .then(function (data) {
        catalog = data;
        resetPhotoClaims();
        return data;
      });
  }

  function ready() {
    return !!catalog;
  }

  function claimedPhotoList() {
    return Object.keys(claimedPhotos);
  }

  root.ItineroBrandMedia = {
    load: load,
    ready: ready,
    mediaFor: mediaFor,
    unsplashFallback: unsplashFallback,
    flightDeals: flightDeals,
    flightRoutes: flightRoutes,
    worldStays: worldStays,
    nearByCity: nearByCity,
    forkByCity: forkByCity,
    forkFallback: forkFallback,
    forkForHome: forkForHome,
    enrichStayList: enrichStayList,
    fetchNearbyHotels: fetchNearbyHotels,
    localeCurrency: localeCurrency,
    startHeroRotation: startHeroRotation,
    stopHeroRotation: stopHeroRotation,
    initialHeroUrl: initialHeroUrl,
    daySeed: daySeed,
    resetPhotoClaims: resetPhotoClaims,
    claimHeroPlaylist: claimHeroPlaylist,
    claimedPhotoList: claimedPhotoList,
    photoKey: photoKey,
  };
})(window);

