/* Itinero calendar: the same picker as flight checkout, for every non-React page. */
(function () {
  if (window.ItineroCalendar) return;

  var MONTHS = ["January", "February", "March", "April", "May", "June", "July", "August", "September", "October", "November", "December"];
  var WD = ["Su", "Mo", "Tu", "We", "Th", "Fr", "Sa"];

  function pad(n) { return String(n).padStart(2, "0"); }
  function iso(y, m, d) { return y + "-" + pad(m + 1) + "-" + pad(d); }
  function todayIso() { var t = new Date(); return iso(t.getFullYear(), t.getMonth(), t.getDate()); }
  function valid(s) { return /^\d{4}-\d{2}-\d{2}$/.test(s || ""); }

  /* Renders the picker into `box`. opts: value, min, max, startView, onPick, onClear */
  function mount(box, opts) {
    var min = valid(opts.min) ? opts.min : "";
    var max = valid(opts.max) ? opts.max : "";
    var value = valid(opts.value) ? opts.value : "";
