    ["IDR", "Indonesian Rupiah"],
    ["PHP", "Philippine Peso"],
    ["KRW", "South Korean Won"],
    ["CHF", "Swiss Franc"],
    ["NZD", "New Zealand Dollar"],
    ["SAR", "Saudi Riyal"],
    ["QAR", "Qatari Riyal"],
    ["TRY", "Turkish Lira"],
    ["ZAR", "South African Rand"],
    ["BRL", "Brazilian Real"],
    ["MXN", "Mexican Peso"],
    ["SEK", "Swedish Krona"],
    ["NOK", "Norwegian Krone"],
    ["DKK", "Danish Krone"],
    ["PLN", "Polish Zloty"],
    ["ILS", "Israeli Shekel"],
    ["PKR", "Pakistani Rupee"],
    ["BDT", "Bangladeshi Taka"],
    ["LKR", "Sri Lankan Rupee"],
    ["VND", "Vietnamese Dong"],
    ["TWD", "New Taiwan Dollar"],
  ];

  const TZ_HINTS = [
    { match: /Kolkata|Calcutta/i, country: "IN", currency: "INR" },
    { match: /Dubai/i, country: "AE", currency: "AED" },
    { match: /Karachi/i, country: "PK", currency: "PKR" },
    { match: /Dhaka/i, country: "BD", currency: "BDT" },
    { match: /Colombo/i, country: "LK", currency: "LKR" },
    { match: /Kathmandu/i, country: "NP", currency: "NPR" },
    { match: /Singapore/i, country: "SG", currency: "SGD" },
    { match: /Hong_Kong/i, country: "HK", currency: "HKD" },
    { match: /Tokyo/i, country: "JP", currency: "JPY" },
    { match: /Seoul/i, country: "KR", currency: "KRW" },
    { match: /Shanghai|Beijing|Hong_Kong/i, country: "CN", currency: "CNY" },
    { match: /Bangkok/i, country: "TH", currency: "THB" },
    { match: /Jakarta/i, country: "ID", currency: "IDR" },
    { match: /Kuala_Lumpur/i, country: "MY", currency: "MYR" },
    { match: /Manila/i, country: "PH", currency: "PHP" },
    { match: /Ho_Chi_Minh|Saigon/i, country: "VN", currency: "VND" },
    { match: /Riyadh/i, country: "SA", currency: "SAR" },
    { match: /Qatar/i, country: "QA", currency: "QAR" },
    { match: /Istanbul/i, country: "TR", currency: "TRY" },
    { match: /London/i, country: "GB", currency: "GBP" },
    { match: /Dublin/i, country: "IE", currency: "EUR" },
    { match: /Paris|Berlin|Madrid|Rome|Amsterdam|Lisbon|Brussels|Vienna|Athens|Helsinki|Stockholm/i, country: "", currency: "EUR" },
    { match: /Zurich/i, country: "CH", currency: "CHF" },
    // Non-US America/* must stay above the US list (Toronto, Mexico City, São Paulo, …).
    { match: /Toronto|Vancouver|Edmonton|Winnipeg|Halifax|St_Johns|Montreal/i, country: "CA", currency: "CAD" },
    { match: /Mexico_City|Cancun|Tijuana|Monterrey/i, country: "MX", currency: "MXN" },
    { match: /Sao_Paulo|Noronha|Belem|Fortaleza|Recife|Bahia/i, country: "BR", currency: "BRL" },
    { match: /Argentina|Buenos_Aires|Cordoba|Mendoza/i, country: "AR", currency: "ARS" },
    { match: /Bogota|Lima|Santiago|Caracas|Guayaquil|La_Paz/i, country: "", currency: "USD" },
    // US zones — State College PA resolves as America/New_York.
    { match: /New_York|Chicago|Denver|Los_Angeles|Phoenix|Anchorage|Honolulu|Detroit|Boise|Juneau|Sitka|Yakutat|Nome|Adak|Metlakatla|Indiana\/|Kentucky\/|North_Dakota\/|Menominee|Shiprock|Puerto_Rico/i, country: "US", currency: "USD" },
    { match: /Sydney|Melbourne|Perth|Brisbane|Adelaide/i, country: "AU", currency: "AUD" },
    { match: /Auckland/i, country: "NZ", currency: "NZD" },
    { match: /Johannesburg|Cape_Town/i, country: "ZA", currency: "ZAR" },
    { match: /Cairo/i, country: "EG", currency: "EGP" },
    { match: /Nairobi/i, country: "KE", currency: "KES" },
    { match: /Lagos/i, country: "NG", currency: "NGN" },
  ];

  /** Higher wins when merging unlocked currency. User lock always wins. */
  const SOURCE_RANK = {
    unknown: 0,
    default: 0,
    timezone: 1,
    network: 2,
    ipwho: 2,
    edge: 3,
    mock: 3,
    precise: 4,
    reverse: 4,
    user: 5,
  };

  let state = empty();
  let detectPromise = null;

  function empty() {
    return {
      currency: "",
      currencyLocked: false,
      currencySource: "",
      city: "",
      cityLocked: false,
      airport: "",
      country: "",
      countryName: "",
      lat: null,
      lng: null,
      source: "",
    };
  }

  function sourceRank(src) {
    return SOURCE_RANK[String(src || "").toLowerCase()] || 0;
  }

  /**
   * Stale soft-default from older builds wrote IN/INR with source "default".
   * Treat that as unlocked junk so a real US geo / timezone can replace it.
   */
  function scrubStaleMarketDefault(snap) {
    const next = { ...empty(), ...snap };
    const src = String(next.source || "").toLowerCase();
    if (
      !next.currencyLocked &&
      (src === "default" || src === "unknown") &&
      next.country === "IN" &&
      next.currency === "INR"
    ) {
      next.currency = "";
      next.currencySource = "";
      next.country = "";
      next.countryName = "";
      next.city = next.cityLocked ? next.city : "";
      next.lat = next.cityLocked ? next.lat : null;
      next.lng = next.cityLocked ? next.lng : null;
      next.source = "";
    }
    return next;
  }

  function validCurrency(code) {
    const c = String(code || "").trim().toUpperCase();
    return /^[A-Z]{3}$/.test(c) ? c : "";
  }

  function readStore() {
    try {
      const raw = JSON.parse(localStorage.getItem(STORE_KEY) || "null");
      if (!raw || typeof raw !== "object") return empty();
      return { ...empty(), ...raw, currency: validCurrency(raw.currency) };
    } catch (_) {
      return empty();
    }
  }

  function writeStore(next) {
    state = { ...empty(), ...next, currency: validCurrency(next.currency) };
    try {
      localStorage.setItem(STORE_KEY, JSON.stringify(state));
      if (state.currency) localStorage.setItem(CURRENCY_KEY, state.currency);
      else localStorage.removeItem(CURRENCY_KEY);
    } catch (_) {}
    return state;
  }

  function emit() {
    try {
      root.dispatchEvent(new CustomEvent(EVENT, { detail: { ...state } }));
    } catch (_) {}
  }

  function accountPrefs() {
    try {
      const session = JSON.parse(localStorage.getItem(SESSION_KEY) || "null");
      if (!session?.email) return {};
      const all = JSON.parse(localStorage.getItem(ACCOUNT_KEY) || "{}");
      const p = all[session.email] || {};
      return {
        city: String(p.homeCity || "").trim(),
        airport: String(p.homeAirport || "").trim().toUpperCase().slice(0, 3),
        currency: validCurrency(p.currency),
        country: String(p.nationality || "").trim().toUpperCase(),
      };
    } catch (_) {
      return {};
    }
  }

  function tzHint() {
    try {
      const tz = Intl.DateTimeFormat().resolvedOptions().timeZone || "";
      const hit = TZ_HINTS.find((row) => row.match.test(tz));
      return hit ? { country: hit.country, currency: hit.currency, source: "timezone" } : {};
    } catch (_) {
      return {};
    }
  }

  function mergeDetected(base, incoming) {
    const next = { ...base };
    const inSrc = String(incoming.source || "").toLowerCase();
    const inRank = sourceRank(inSrc);
    const curRank = sourceRank(next.currencySource || next.source);

    if (!next.cityLocked && incoming.city) next.city = incoming.city;
    if (!next.airport && incoming.airport) next.airport = incoming.airport;

    // Country / coords: prefer equal-or-better sources; never keep fake default over real geo.
    if (incoming.country && (inRank >= sourceRank(next.source) || !next.country)) {
      next.country = incoming.country;
    }
    if (incoming.countryName && (inRank >= sourceRank(next.source) || !next.countryName)) {
      next.countryName = incoming.countryName;
    }
    if (incoming.lat != null && incoming.lng != null) {
      if (inRank >= sourceRank(next.source) || next.lat == null || next.lng == null) {
        next.lat = incoming.lat;
        next.lng = incoming.lng;
      }
    }

    // Currency: user lock wins. Otherwise only adopt when unlocked and source is stronger,
    // or currency is still empty. Never keep INR from a weaker/default stamp over US geo.
    if (!next.currencyLocked && incoming.currency) {
      if (!next.currency || inRank >= curRank) {
        next.currency = incoming.currency;
        next.currencySource = inSrc || next.currencySource || "network";
      }
    }

    if (incoming.source && inRank >= sourceRank(next.source)) {
      next.source = incoming.source;
    }
    return next;
  }

  function localeFor(cur) {
    if (cur === "INR") return "en-IN";
    if (cur === "GBP") return "en-GB";
    if (cur === "EUR") return "en-IE";
    if (cur === "JPY") return "ja-JP";
    return "en-US";
  }

  function money(n, currency) {
    const val = Number(n);
    if (!(val > 0)) return "";
    const cur = validCurrency(currency || state.currency) || "USD";
    try {
      return new Intl.NumberFormat(localeFor(cur), {
        style: "currency",
        currency: cur,
        maximumFractionDigits: 0,
      }).format(val);
    } catch (_) {
      return `${cur} ${Math.round(val)}`;
    }
  }

  function geoMockParams() {
    try {
      const q = new URLSearchParams(location.search || "");
      let country = String(q.get("mock_country") || "").trim().toUpperCase().slice(0, 2);
      let city = String(q.get("mock_city") || "").replace(/\+/g, " ").trim();
      if (!country && !city) {
        const raw = localStorage.getItem("itinero_geo_mock") || "";
        if (raw) {
          const parsed = JSON.parse(raw);
          country = String(parsed.country || "").trim().toUpperCase().slice(0, 2);
          city = String(parsed.city || "").trim();
        }
      }
      if (!country && !city) return "";
      const p = new URLSearchParams();
      if (country) p.set("mock_country", country);
      if (city) p.set("mock_city", city);
      return p.toString();
    } catch (_) {
      return "";
    }
  }

  async function fetchNetwork() {
    try {
      const mockQs = geoMockParams();
      const url = mockQs ? `/api/geo/network?${mockQs}` : "/api/geo/network";
      const res = await fetch(url, { headers: { Accept: "application/json" } });
      const data = await res.json().catch(() => ({}));
      if (!data?.ok) return null;
      // Ignore empty unknown payloads — timezone / precise fill gaps without a fake market.
      if (!data.city && !data.country_code && !data.currency && data.source === "unknown") {
        return null;
      }
      const lat = Number(data.latitude);
      const lng = Number(data.longitude);
      return {
        city: String(data.city || "").trim(),
        country: String(data.country_code || "").trim().toUpperCase(),
        countryName: String(data.country || "").trim(),
        currency: validCurrency(data.currency),
        lat: Number.isFinite(lat) ? lat : null,
        lng: Number.isFinite(lng) ? lng : null,
        source: data.source || "network",
      };
    } catch (_) {
      return null;
    }
  }

  async function fetchAirport(lat, lng, city) {
    try {
      const p = new URLSearchParams({ limit: "1" });
      if (lat != null && lng != null) {
        p.set("lat", String(lat));
        p.set("lng", String(lng));
      } else if (city) {
        p.set("q", city);
      } else {
        return "";
      }
      const res = await fetch("/api/flights/airports?" + p.toString(), {
        headers: { Accept: "application/json" },
      });
      const data = await res.json().catch(() => ({}));
      const row = Array.isArray(data?.airports)
        ? data.airports[0]
        : Array.isArray(data?.items)
          ? data.items[0]
          : Array.isArray(data)
            ? data[0]
            : data?.airport;
      const code = String(row?.code || row?.iata || "").toUpperCase();
      return /^[A-Z]{3}$/.test(code) ? code : "";
    } catch (_) {
      return "";
    }
  }

  async function convertUsd(amount, dst) {
    const cur = validCurrency(dst || state.currency) || "USD";
    if (cur === "USD") return Number(amount);
    try {
      const res = await fetch(
        `/api/fx/convert?amount=${encodeURIComponent(amount)}&src=USD&dst=${encodeURIComponent(cur)}`
      );
      const data = await res.json().catch(() => ({}));
      const out = Number(data.result ?? data.value ?? data.converted);
      return out > 0 ? out : null;
    } catch (_) {
      return null;
    }
  }

  async function reverseCoords(lat, lng) {
    try {
      const res = await fetch(
        `/api/geo/reverse?lat=${encodeURIComponent(lat)}&lng=${encodeURIComponent(lng)}`,
        { headers: { Accept: "application/json" } }
      );
      const data = await res.json().catch(() => ({}));
      if (!data?.ok && !data?.city) return null;
      return {
        city: String(data.city || "").trim(),
        country: String(data.country_code || data.country || "").trim().toUpperCase(),
        countryName: String(data.country || "").trim(),
        currency: validCurrency(data.currency),
        lat,
        lng,
        source: data.source || "precise",
      };
    } catch (_) {
      return null;
    }
  }

  /**
   * Soft browser geolocation — never rejects. Denied / timeout → null.
   * Does not lock city so IP/network still wins when permission is refused.
   */
  function requestPrecise(opts) {
    const timeoutMs = Math.max(1500, Number(opts && opts.timeoutMs) || 4500);
    if (typeof navigator === "undefined" || !navigator.geolocation) {
      return Promise.resolve(null);
    }
    return new Promise((resolve) => {
      let settled = false;
      const finish = (value) => {
        if (settled) return;
        settled = true;
        resolve(value);
      };
      const timer = setTimeout(() => finish(null), timeoutMs);
      try {
        navigator.geolocation.getCurrentPosition(
          async (pos) => {
            clearTimeout(timer);
            const lat = Number(pos?.coords?.latitude);
            const lng = Number(pos?.coords?.longitude);
            if (!Number.isFinite(lat) || !Number.isFinite(lng)) {
              finish(null);
              return;
            }
            const rev = await reverseCoords(lat, lng);
            finish(
              rev || {
                lat,
                lng,
                source: "precise",
              }
            );
          },
          () => {
            clearTimeout(timer);
            finish(null);
          },
          { enableHighAccuracy: false, maximumAge: 600000, timeout: Math.min(timeoutMs, 4000) }
        );
      } catch (_) {
        clearTimeout(timer);
        finish(null);
      }
    });
  }

  async function detect(opts) {
    const force = !!(opts && opts.force);
    const wantPrecise = !opts || opts.precise !== false;
    if (detectPromise && !force) return detectPromise;
    detectPromise = (async () => {
      let next = scrubStaleMarketDefault(readStore());
      const prefs = accountPrefs();
      if (prefs.currency) {
        next.currency = prefs.currency;
        next.currencyLocked = true;
        next.currencySource = "user";
      }
      if (prefs.city) {
        next.city = prefs.city;
        next.cityLocked = true;
      }
      if (prefs.airport) next.airport = prefs.airport;
      if (prefs.country && !next.country) next.country = prefs.country;

      const net = await fetchNetwork();
      if (net) next = mergeDetected(next, net);

      if (wantPrecise && !next.cityLocked) {
        const precise = await requestPrecise({ timeoutMs: (opts && opts.preciseTimeoutMs) || 4500 });
        if (precise) next = mergeDetected(next, precise);
      }

      if (!next.currency) {
        const tz = tzHint();
        next = mergeDetected(next, tz);
      }
      if (!next.currency) {
        next.currency = "USD";
        next.currencySource = next.currencySource || "unknown";
      }

      if (!next.airport && (next.lat != null || next.city)) {
        next.airport = await fetchAirport(next.lat, next.lng, next.city);
      }

      writeStore(next);
      emit();
      return { ...state };
    })();
    try {
      return await detectPromise;
    } finally {
      detectPromise = null;
    }
  }

  function setCurrency(code, opts) {
    const cur = validCurrency(code);
    if (!cur) return get();
    const lock = !opts || opts.lock !== false;
    writeStore({
      ...readStore(),
      ...state,
      currency: cur,
      currencyLocked: lock,
      currencySource: "user",
    });
    emit();
    return get();
  }

  function setHome(partial, opts) {
    const lock = !opts || opts.lock !== false;
    const next = { ...readStore(), ...state };
    if (partial.city != null) {
      next.city = String(partial.city || "").trim();
      next.cityLocked = lock;
    }
    if (partial.airport != null) next.airport = String(partial.airport || "").trim().toUpperCase().slice(0, 3);
    if (partial.country != null) next.country = String(partial.country || "").trim().toUpperCase();
    if (partial.lat != null) next.lat = Number(partial.lat);
    if (partial.lng != null) next.lng = Number(partial.lng);
    writeStore(next);
    emit();
    return get();
  }

  function reset() {
    writeStore(empty());
    emit();
    return get();
  }

  function get() {
    if (!state.currency && !state.city) state = readStore();
    return { ...state };
  }

  function currency() {
    return get().currency || "USD";
  }

  function cityLabel() {
    const s = get();
    return s.city || s.countryName || s.country || "";
  }

  function optionHtml(selected) {
    const cur = validCurrency(selected) || currency();
    return CURRENCIES.map(([code, name]) => {
      const on = code === cur ? " selected" : "";
      return `<option value="${code}"${on}>${code} · ${name}</option>`;
    }).join("");
  }

  /** Compact trigger label — code + short name; never dump the full catalog. */
  function shortName(name) {
    const raw = String(name || "").trim();
    if (!raw) return "";
    // Prefer a short first token for long names ("Indian Rupee" → "Indian").
    if (raw.length <= 10) return raw;
    const first = raw.split(/\s+/)[0] || raw;
    return first.length <= 12 ? first : first.slice(0, 10);
  }

  function currencyLabel(code, opts) {
    const c = validCurrency(code) || currency() || "USD";
    const row = CURRENCIES.find((r) => r[0] === c);
    const full = row ? row[1] : c;
    const short = shortName(full);
    const mode = (opts && opts.mode) || "auto";
    if (mode === "code") return c;
    if (mode === "full") return `${c} · ${full}`;
    return short ? `${c} · ${short}` : c;
  }

  function findName(code) {
    const c = validCurrency(code) || "";
    const row = CURRENCIES.find((r) => r[0] === c);
    return row ? row[1] : c;
  }

  const CHEVRON =
    '<svg class="currency-ctl__chev" viewBox="0 0 24 24" width="14" height="14" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M6 9l6 6 6-6"/></svg>';

  function paintTrigger(rootEl, code) {
    const btn = rootEl.querySelector(".currency-ctl__btn");
    const label = rootEl.querySelector(".currency-ctl__label");
    if (!btn || !label) return;
    const c = validCurrency(code) || currency() || "USD";
    const full = findName(c);
    const short = shortName(full);
    const title = `${c} · ${full}`;
    label.innerHTML =
      `<span class="currency-ctl__code">${c}</span>` +
      (short
        ? `<span class="currency-ctl__sep" aria-hidden="true"> · </span><span class="currency-ctl__name">${short}</span>`
        : "");
    btn.setAttribute("aria-label", `Currency ${title}`);
    btn.setAttribute("title", title);
    rootEl.dataset.currency = c;
  }

  function closeMenu(rootEl) {
    const btn = rootEl.querySelector(".currency-ctl__btn");
    const menu = rootEl.querySelector(".currency-ctl__menu");
    if (!btn || !menu) return;
    menu.hidden = true;
    menu.innerHTML = ""; // keep options out of a11y/visible_text while closed
    btn.setAttribute("aria-expanded", "false");
  }

  function openMenu(rootEl) {
    const btn = rootEl.querySelector(".currency-ctl__btn");
    const menu = rootEl.querySelector(".currency-ctl__menu");
    if (!btn || !menu) return;
    const cur = rootEl.dataset.currency || currency();
    menu.innerHTML = buildMenuItems(cur);
    menu.hidden = false;
    btn.setAttribute("aria-expanded", "true");
    const selected = menu.querySelector('[aria-selected="true"]');
    if (selected) selected.scrollIntoView({ block: "nearest" });
  }

  function buildMenuItems(selected) {
    const cur = validCurrency(selected) || currency();
    return CURRENCIES.map(([code, name]) => {
      const on = code === cur;
      const selectedAttr = on ? 'true' : 'false';
      const selectedClass = on ? ' class="is-selected"' : '';
      return (
        `<li role="option" tabindex="-1" data-value="${code}" aria-selected="${selectedAttr}"${selectedClass}>` +
        `<b>${code}</b><span>${name}</span></li>`
      );
    }).join("");
  }

  /**
   * Replace a native <select> (or empty mount) with a button + listbox.
   * Trigger accessible name is only the selected currency — options stay in the panel.
   */
  function mountCurrency(target, opts) {
    const host = typeof target === "string" ? document.querySelector(target) : target;
    if (!host) return null;

    // Already enhanced — attach/replace onChange and refresh label.
    const existing = host.dataset.currencyCtl === "1" ? host : host.closest && host.closest(".currency-ctl[data-currency-ctl='1']");
    if (existing) {
      if (typeof (opts && opts.onChange) === "function") existing._currencyOnChange = opts.onChange;
      if (existing._currencyCtl && typeof existing._currencyCtl.paint === "function") {
        existing._currencyCtl.paint();
      }
      return existing;
    }

    let mount = host;
    let initial = (opts && opts.currency) || currency();

    if (host.tagName === "SELECT") {
      initial = validCurrency(host.value) || initial;
      const wrap = document.createElement("div");
      wrap.className = "top__currency currency-ctl";
      wrap.id = host.id || "currency-ctl";
      if (host.parentElement) {
        host.parentElement.replaceChild(wrap, host);
      }
      mount = wrap;
    } else {
      mount.classList.add("currency-ctl");
      if (!mount.classList.contains("top__currency")) mount.classList.add("top__currency");
      mount.innerHTML = "";
    }
    if (typeof (opts && opts.onChange) === "function") mount._currencyOnChange = opts.onChange;

    const menuId = (mount.id || "currency-ctl") + "-menu";
    mount.dataset.currencyCtl = "1";
    mount.innerHTML =
      `<button type="button" class="currency-ctl__btn" aria-haspopup="listbox" aria-expanded="false" aria-controls="${menuId}">` +
      `<span class="currency-ctl__label"></span>${CHEVRON}</button>` +
      `<ul class="currency-ctl__menu" id="${menuId}" role="listbox" aria-label="Currencies" hidden></ul>`;

    paintTrigger(mount, initial);

    const btn = mount.querySelector(".currency-ctl__btn");
    const menu = mount.querySelector(".currency-ctl__menu");

    function pick(code, { close } = { close: true }) {
      const next = setCurrency(code, { lock: true });
      paintTrigger(mount, next.currency || code);
      if (close) {
        closeMenu(mount);
        btn.focus();
      } else {
        menu.innerHTML = buildMenuItems(next.currency || code);
      }
      if (typeof mount._currencyOnChange === "function") mount._currencyOnChange(next.currency || code, next);
    }

    btn.addEventListener("click", (e) => {
      e.preventDefault();
      e.stopPropagation();
      if (menu.hidden) openMenu(mount);
      else closeMenu(mount);
    });

