      if (!mount.contains(e.target)) closeMenu(mount);
    };
    document.addEventListener("pointerdown", onDoc);

    root.addEventListener(EVENT, () => {
      paintTrigger(mount, currency());
    });

    mount._currencyCtl = { pick, paint: () => paintTrigger(mount, currency()), close: () => closeMenu(mount) };
    return mount;
  }

  function enhanceCurrencyMounts() {
    document.querySelectorAll("select#home-currency, select[data-currency-select], [data-currency-control]").forEach((el) => {
      if (el.dataset.currencyCtl === "1" || el.closest(".currency-ctl[data-currency-ctl='1']")) return;
      mountCurrency(el);
    });
  }

  state = readStore();

  root.ItineroLocale = {
    STORE_KEY,
    EVENT,
    CURRENCIES,
    detect,
    requestPrecise,
    reset,
    get,
    currency,
    cityLabel,
    setCurrency,
    setHome,
    money,
    convertUsd,
    optionHtml,
    currencyLabel,
    mountCurrency,
    enhanceCurrencyMounts,
  };

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", enhanceCurrencyMounts);
  } else {
    enhanceCurrencyMounts();
  }
