/* Site theme — apply before paint. Preference: light | dark | system */
(function (root) {
  var KEY = "itinero_theme";
  var html = document.documentElement;

  function systemDark() {
    return !!(root.matchMedia && root.matchMedia("(prefers-color-scheme: dark)").matches);
  }

  function readPref() {
    try {
      var v = localStorage.getItem(KEY);
      if (v === "light" || v === "dark" || v === "system") return v;
    } catch (_) {}
    return "system";
  }

  function resolve(pref) {
    if (pref === "light" || pref === "dark") return pref;
    return systemDark() ? "dark" : "light";
  }

  function paint(theme) {
    html.setAttribute("data-theme", theme);
    html.style.colorScheme = theme;
    var meta = document.querySelector('meta[name="theme-color"]');
    if (meta) meta.setAttribute("content", theme === "dark" ? "#070d16" : "#001438");
  }

  function apply(pref) {
    paint(resolve(pref || readPref()));
  }

  apply(readPref());

  function iconSun() {
    return '<svg class="theme-toggle__sun" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="4"/><path d="M12 3.2v1.8M12 19v1.8M4.9 4.9l1.3 1.3M17.8 17.8l1.3 1.3M3.2 12h1.8M19 12h1.8M4.9 19.1l1.3-1.3M17.8 6.2l1.3-1.3"/></svg>';
  }

  function iconMoon() {
    return '<svg class="theme-toggle__moon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M16.4 13.2A6.4 6.4 0 0 1 10.8 5.4 6.6 6.6 0 1 0 16.4 13.2z"/></svg>';
  }

  function labelFor(theme) {
    return theme === "dark" ? "Switch to light mode" : "Switch to dark mode";
  }

  function eachToggle(fn) {
    document.querySelectorAll(".theme-toggle, [data-theme-toggle]").forEach(fn);
  }

  function syncButtons() {
    var theme = resolve(readPref());
    eachToggle(function (btn) {
      btn.setAttribute("aria-label", labelFor(theme));
      btn.setAttribute("title", labelFor(theme));
      btn.setAttribute("aria-pressed", theme === "dark" ? "true" : "false");
      var meta = btn.querySelector("[data-theme-meta]");
      if (meta) meta.textContent = theme === "dark" ? "Dark" : "Light";
      if (btn.hasAttribute("data-theme-toggle") && !btn.querySelector("[data-theme-meta]")) {
        btn.textContent = theme === "dark" ? "Use light mode" : "Use dark mode";
      }
    });
  }

  function setPref(pref) {
    try {
      localStorage.setItem(KEY, pref);
    } catch (_) {}
    apply(pref);
    syncButtons();
    document.dispatchEvent(
      new CustomEvent("itinero:theme", { detail: { pref: pref, theme: resolve(pref) } })
    );
  }

  function toggle() {
    var next = resolve(readPref()) === "dark" ? "light" : "dark";
    setPref(next);
    return next;
  }

  function bind(btn) {
    if (!btn || btn.dataset.themeBound === "1") return;
    btn.dataset.themeBound = "1";
    btn.addEventListener("click", function (e) {
      e.preventDefault();
      toggle();
    });
  }

  function buttonHtml() {
    return (
      '<button type="button" class="theme-toggle hdr-dd__btn" aria-label="Switch to dark mode">' +
      iconMoon() +
      iconSun() +
      "</button>"
    );
  }

  function mount(container, before) {
    if (!container || container.querySelector(".theme-toggle")) return container.querySelector(".theme-toggle");
    var wrap = document.createElement("div");
    wrap.className = "theme-toggle-wrap";
    wrap.innerHTML = buttonHtml();
    var btn = wrap.firstElementChild;
    if (before && before.parentNode === container) container.insertBefore(wrap, before);
    else container.appendChild(wrap);
    bind(btn);
    syncButtons();
    return btn;
  }

  function boot() {
    eachToggle(bind);
    var actions = document.querySelector(".header-actions");
    if (actions && !actions.querySelector(".theme-toggle")) {
      mount(actions, actions.querySelector(".btn-login, #top-signin"));
    }
    var tools = document.querySelector(".top__tools");
    if (tools && !tools.querySelector(".theme-toggle")) {
      mount(tools, tools.querySelector("#alerts-btn, #menu-btn, #top-signin, .top__signin"));
    }
    syncButtons();
  }

  if (root.matchMedia) {
    var mq = root.matchMedia("(prefers-color-scheme: dark)");
    var onChange = function () {
      if (readPref() === "system") apply("system");
    };
    if (mq.addEventListener) mq.addEventListener("change", onChange);
    else if (mq.addListener) mq.addListener(onChange);
  }

