    get: readPref,
    resolved: function () {
      return resolve(readPref());
    },
    set: setPref,
    toggle: toggle,
    mount: mount,
    bind: bind,
    sync: syncButtons,
    buttonHtml: buttonHtml,
  };

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", boot);
  else boot();
})(window);

