  /* Airport suggest */
  function localAirports(q) {
    var needle = String(q || "").trim().toLowerCase();
    var rows = AIRPORTS.map(function (a) {
      return { code: a[0], city: a[1], name: a[2], country: a[3] };
    });
    if (!needle) return rows.slice(0, 8);
    if (/^[a-z]{3}$/.test(needle)) {
      var exact = rows.filter(function (a) { return a.code.toLowerCase() === needle; });
      if (exact.length) return exact;
    }
    return rows
      .filter(function (a) {
        return (
          a.code.toLowerCase() === needle ||
          a.city.toLowerCase().indexOf(needle) === 0 ||
          a.name.toLowerCase().indexOf(needle) !== -1 ||
          a.country.toLowerCase().indexOf(needle) === 0
