            escapeHtml(a.city) + '</span><span class="dock-pop__meta">' +
            escapeHtml([a.name, a.country].filter(Boolean).join(" · ")) +
            '</span></span><span class="dock-pop__code">' + escapeHtml(a.code) + "</span></button></li>"
          );
        })
        .join("") +
      "</ul>";
    pop.querySelectorAll(".dock-pop__opt").forEach(function (btn) {
      btn.addEventListener("mousedown", function (ev) { ev.preventDefault(); });
      btn.addEventListener("click", function () {
        picked[which] = btn.getAttribute("data-code");
        input.value = btn.getAttribute("data-label");
        closePop();
