  }

  function renderAirports(which) {
    var input = which === "from" ? fromInput : toInput;
    var q = input.value.trim();
    // A label like "Mumbai (BOM)" means the airport is already chosen; show the full list again.
    var needle = picked[which] && q === q.replace(/\s*\(.*\)$/, "") + " (" + picked[which] + ")" ? "" : q;
    openPop("suggest", input);
    var local = localAirports(needle);
    paintAirports(local, which, input, needle);
