/* Ask Vero card: chips and form hand the question to Vero */
(function () {
  var form = document.getElementById("fl-vero-form");
  if (!form) return;
  var input = document.getElementById("fl-vero-input");
  var chipRow = document.querySelector(".fl-vero__chips");
  var sets = [
    [
      ["Under 4 hours", "Quiet long weekend, under 4 hours, mid budget"],
      ["Warm in December", "Somewhere warm in December, direct flights, from my home airport"],
      ["Business, direct", "Business class to Singapore next month, direct only"],
      ["Cheapest month", "Cheapest month to fly from London to Tokyo"],
    ],
    [
      ["Direct only", "Direct flights from my home airport, mid budget"],
      ["With a meal", "A flight that includes a meal, under 8 hours"],
      ["Weekend break", "Somewhere nearby for a long weekend"],
      ["Avoid red-eyes", "Daytime flights only, no red-eyes"],
    ],
    [
      ["Family trip", "Family-friendly destination, under 6 hours"],
      ["Warm now", "Somewhere warm this month, direct if possible"],
      ["Short hop", "Under 3 hours from my home airport"],
      ["Best month", "Cheapest month to fly to Europe"],
    ],
  ];
  var placeholders = [
    "Warm, direct, under 8 hours",
    "Without stops, with a meal…",
    "Family trip, under 6 hours…",
  ];
  function go(q) {
    q = String(q || "").trim();
    location.href = "/vero/?q=" + encodeURIComponent(q);
  }
  function paint(index) {
    if (!chipRow) return;
    chipRow.replaceChildren();
    sets[index].forEach(function (pair) {
      var b = document.createElement("button");
      b.type = "button";
      b.textContent = pair[0];
      b.setAttribute("data-invite", pair[1]);
      b.addEventListener("click", function () { go(pair[1]); });
      chipRow.appendChild(b);
    });
    if (input && !input.value) input.placeholder = placeholders[index];
  }
  form.addEventListener("submit", function (e) { e.preventDefault(); go(input.value); });
  paint(0);
  var i = 0;
  setInterval(function () {
    if (input && document.activeElement === input) return;
    i = (i + 1) % sets.length;
    paint(i);
  }, 7000);
})();

