(function (root) {
  const mem = Object.create(null);
  const inflight = Object.create(null);
  const FETCH_MS = 2500;
  const REFRESH_MS = 16000;

  function key(city, kind) {
    return String(city || "").trim().toLowerCase() + "|" + (kind || "card");
  }

  function get(city, kind) {
    const label = String(city || "").trim();
    const k = key(label, kind);
    if (!label) return Promise.resolve(null);
    if (mem[k]) return Promise.resolve(mem[k]);
    if (inflight[k]) return inflight[k];
    const q = new URLSearchParams({ city: label, kind: kind || "card" });
    const ctrl = typeof AbortController === "function" ? new AbortController() : null;
    const timer = ctrl ? setTimeout(() => ctrl.abort(), FETCH_MS) : 0;
    inflight[k] = fetch("/api/covers?" + q.toString(), {
      headers: { Accept: "application/json" },
      signal: ctrl ? ctrl.signal : undefined,
    })
      .then((res) => (res.ok ? res.json() : null))
      .then((data) => {
        if (data && data.url) mem[k] = data;
        return data;
      })
      .catch(() => null)
      .finally(() => {
        if (timer) clearTimeout(timer);
        delete inflight[k];
      });
    return inflight[k];
  }

  function setSrc(img, url) {
    if (!img || !url) return;
    if (img.dataset.coverUrl === url || img.currentSrc === url || img.src === url) {
      img.dataset.coverUrl = url;
      return;
    }
    const apply = () => {
      if (img.dataset.coverUrl === url) return;
      img.src = url;
      img.dataset.coverUrl = url;
    };
    const probe = new Image();
    probe.decoding = "async";
    probe.onload = apply;
    probe.onerror = () => {};
    probe.src = url;
    if (probe.complete && probe.naturalWidth) apply();
  }

  function apply(img, city, kind, fallback) {
    if (!img) return;
    const seed = fallback || img.getAttribute("src") || "";
    if (seed && !img.getAttribute("src")) img.src = seed;
    if (seed && !img.dataset.coverUrl) img.dataset.coverUrl = seed;
    get(city, kind).then((data) => {
      if (!data?.url) return;
      setSrc(img, data.url);
      if (!data.pending) return;
      [5000, REFRESH_MS].forEach((ms) => {
        setTimeout(() => {
          delete mem[key(city, kind)];
          get(city, kind).then((next) => {
            if (next?.url && next.url !== data.url) setSrc(img, next.url);
          });
        }, ms);
      });
    });
  }

  function hydrate(city, kind, fallback) {
    return get(city, kind).then((data) => (data && data.url) || fallback || "");
  }

  function applyAll(rootEl) {
    (rootEl || document).querySelectorAll("img[data-cover-city]").forEach((img) => {
      apply(
        img,
        img.getAttribute("data-cover-city"),
        img.getAttribute("data-cover-kind") || "card",
        img.getAttribute("src")
      );
    });
  }

  function boot() {
    applyAll(document);
  }

  if (document.readyState === "loading") {
    document.addEventListener("DOMContentLoaded", boot);
  } else {
    boot();
  }

  root.ItineroCovers = { get, apply, applyAll, hydrate };
