/**
 * Hotels page mode + Ask Vero desk iframe.
 * Next only runs src scripts, so mode cannot live in a head inline tag.
 */
(function () {
  var q = new URLSearchParams(location.search);
  var path = String(location.pathname || "").replace(/\/+$/, "") || "/";
  var dest = (q.get("destination") || q.get("city") || "").trim();
  var explore = path === "/hotels";
  if (explore && dest) {
    location.replace("/hotels/results" + location.search);
    return;
  }
  document.documentElement.dataset.hotelsMode = explore ? "explore" : "results";

  var embedded = q.get("embed") === "1" || window.self !== window.top;
  if (!embedded) return;
  document.documentElement.classList.add("hwl-embed");
  if (document.body) document.body.classList.add("hwl-embed");
  else document.addEventListener("DOMContentLoaded", function () {
    document.body && document.body.classList.add("hwl-embed");
  });
  if (q.get("embed") !== "1") {
    try {
      var u = new URL(location.href);
      u.searchParams.set("embed", "1");
      history.replaceState(null, "", u.pathname + u.search + u.hash);
    } catch (_) {}
  }
  document.addEventListener(
    "click",
    function (e) {
      var a = e.target && e.target.closest && e.target.closest("a[href]");
      if (!a) return;
      try {
        var next = new URL(a.getAttribute("href"), location.origin);
        if (next.origin !== location.origin) return;
        if (!/^\/hotels\/?/.test(next.pathname) && !/^\/hotel\//.test(next.pathname)) return;
        if (next.searchParams.get("embed") === "1") return;
        next.searchParams.set("embed", "1");
        a.setAttribute("href", next.pathname + next.search + next.hash);
      } catch (_) {}
    },
    true
  );
})();

