response.body:
/* Hotels landing below the hero — same Outfit / tokens as the rest of the site. */
.hx-page,
.hx-page button,
.hx-page input {
  font-family: var(--font-sans, var(--font));
}
.hx-band {
  padding: clamp(56px, 7vw, 96px) 0;
  background: var(--bg, #fff);
  color: var(--ink, #0f172a);
}
.hx-wrap {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}
.hx-kicker {
  margin: 0;
  font-size: var(--text-xs, 0.75rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #0f6b6b;
}
.hx-lead {
  max-width: 640px;
  margin-bottom: clamp(24px, 3.5vw, 40px);
}
.hx-lead h2 {
  margin: 6px 0 10px;
  font-size: clamp(1.75rem, 3vw, 2.375rem);
  line-height: 1.1;
  letter-spacing: var(--tracking-tight, -0.02em);
  font-weight: var(--weight-bold, 700);
  color: var(--ink, #0f172a);
}
.hx-lead p:not(.hx-kicker) {
  margin: 0;
  max-width: 52ch;
  color: var(--muted, #64748b);
  font-size: var(--text-lg, 1.0625rem);
  line-height: 1.55;
}

.hx-nights {
  display: grid;
  grid-template-columns: 1.35fr 1fr 1fr;
  grid-template-rows: minmax(230px, 1fr) minmax(230px, 1fr);
  gap: 14px;
  min-height: 520px;
}
.hx-stay {
  position: relative;
  display: block;
  overflow: hidden;
  border: 0;
  padding: 0;
  border-radius: 20px;
  color: #fff;
  text-align: left;
  text-decoration: none;
  background: var(--navy, #001438);
  isolation: isolate;
  cursor: pointer;
  font-family: inherit;
}
.hx-stay--lead {
  grid-row: 1 / span 2;
}
.hx-stay img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -3;
  filter: saturate(0.92) contrast(1.04) brightness(0.9);
  transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.hx-stay::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: -2;
  background: linear-gradient(180deg, rgba(15, 107, 107, 0.22), rgba(196, 92, 38, 0.12));
  mix-blend-mode: soft-light;
}
.hx-stay__shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  /* Dual scrim — homepage fork-band bar */
  background: linear-gradient(
    180deg,
    rgba(0, 8, 20, 0.28) 0%,
    rgba(0, 8, 20, 0.06) 22%,
    rgba(0, 6, 14, 0.52) 42%,
    rgba(0, 4, 10, 0.82) 62%,
    rgba(0, 2, 6, 0.94) 82%,
    rgba(0, 0, 0, 0.97) 100%
  );
}
.hx-stay__txt {
  position: absolute;
  left: 20px;
  right: 20px;
  bottom: 20px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.hx-stay__txt em {
  font-style: normal;
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: #8fd6c9;
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.45);
}
.hx-stay__txt strong {
  font-size: var(--text-2xl, 1.5rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: var(--tracking-tight, -0.015em);
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55);
}
.hx-stay__txt span {
  font-size: var(--text-sm, 0.8125rem);
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.92);
  text-shadow: 0 1px 12px rgba(0, 0, 0, 0.5);
}
/* Always-visible solid CTA — fork-band Explore stays pattern */
.hx-stay__go {
  position: absolute;
  top: 16px;
  right: 16px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 14px;
  border-radius: 999px;
  font-size: var(--text-xs, 0.75rem);
  font-weight: 750;
  background: #fff;
  color: var(--navy, #001438);
  opacity: 1;
  transform: none;
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.28);
  transition: background 0.2s, box-shadow 0.2s;
}
.hx-stay:hover img,
.hx-stay:focus-visible img {
  transform: scale(1.05);
}
.hx-stay:hover .hx-stay__go,
.hx-stay:focus-visible .hx-stay__go {
  background: #f8fafc;
  box-shadow: 0 10px 26px rgba(0, 0, 0, 0.32);
}
.hx-stay:focus-visible {
  outline: 3px solid #0f6b6b;
  outline-offset: 3px;
}

.hx-vero-band {
  padding-top: 0;
}
.hx-vero {
  position: relative;
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: clamp(24px, 4vw, 56px);
  align-items: center;
  padding: clamp(28px, 4vw, 52px);
  border-radius: 28px;
  border: 1.5px solid transparent;
  color: #fff;
  background:
    radial-gradient(900px 300px at 12% 0%, rgba(15, 107, 107, 0.22), transparent 60%),
    radial-gradient(700px 300px at 100% 100%, rgba(251, 146, 60, 0.16), transparent 60%),
    linear-gradient(160deg, #081530, #050d20) padding-box,
    linear-gradient(var(--ai-ring, 120deg, #5eead4, #fb9a4d, #fb923c)) border-box;
  box-shadow: 0 0 0 1px rgba(15, 107, 107, 0.18), 0 24px 60px rgba(8, 21, 48, 0.18);
}
.hx-vero__badge {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  margin: 0 0 16px;
  font-size: var(--text-xs, 0.75rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.7);
}
.hx-vero__badge span {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 22px;
  padding: 0 9px 0 7px;
  border-radius: 999px;
  background: #fff;
  color: #0f6b6b;
  font-weight: var(--weight-extrabold, 800);
}
.hx-vero h2 {
  margin: 0 0 12px;
  font-size: clamp(1.625rem, 2.8vw, 2.25rem);
  line-height: 1.12;
  letter-spacing: var(--tracking-tight, -0.02em);
  font-weight: var(--weight-bold, 700);
  color: #fff;
}
.hx-vero__copy p:not(.hx-vero__badge) {
  margin: 0;
  max-width: 40ch;
  color: rgba(255, 255, 255, 0.72);
  line-height: 1.55;
  font-size: var(--text-lg, 1.0625rem);
}
.hx-vero__form {
  display: flex;
  gap: 8px;
  align-items: center;
  min-height: 60px;
  padding: 7px 7px 7px 20px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  border: 1px solid rgba(255, 255, 255, 0.18);
}
.hx-vero__form:focus-within {
  border-color: #99f6e4;
  box-shadow: 0 0 0 4px rgba(15, 107, 107, 0.22);
}
.hx-vero__form input {
  flex: 1;
  min-width: 0;
  border: 0;
  outline: 0;
  background: transparent;
  color: #fff;
  font: inherit;
  font-size: var(--text-base, 1rem);
}
.hx-vero__form input::placeholder {
  color: rgba(255, 255, 255, 0.68);
}
.hx-vero__try {
  margin: 20px 0 10px 4px;
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.5);
}
.hx-vero__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.hx-vero__chips button {
  padding: 9px 15px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.88);
  font: inherit;
  font-size: var(--text-sm, 0.8125rem);
  font-weight: var(--weight-semibold, 600);
  cursor: pointer;
}
.hx-vero__chips button:hover {
  background: rgba(255, 255, 255, 0.12);
  border-color: #99f6e4;
}
.hx-vero__chips button:focus-visible,
.hx-vero__form .vero-cta:focus-visible {
  outline: 2px solid #99f6e4;
  outline-offset: 2px;
}

.hx-cross {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.hx-cross__card {
  position: relative;
  display: block;
  min-height: 220px;
  overflow: hidden;
  border-radius: 20px;
  color: #fff;
  text-decoration: none;
  isolation: isolate;
  background: var(--navy, #001438);
}
.hx-cross__card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
  filter: saturate(0.88) contrast(1.05) brightness(0.9);
  transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.hx-cross__card:hover img {
  transform: scale(1.05);
}
.hx-cross__card .hx-stay__txt strong {
  font-size: 1.5rem;
}
.hx-cross__card:focus-visible {
  outline: 3px solid #0f6b6b;
  outline-offset: 3px;
}

.hx-faq {
  border-top: 1px solid var(--line, #e2e8f0);
}
.hx-faq__in {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: clamp(24px, 5vw, 80px);
  align-items: start;
}
.hx-faq .hx-lead {
  margin-bottom: 0;
}
.hx-faq__list {
  border-top: 1px solid var(--line, #e2e8f0);
}
.hx-faq__item {
  border-bottom: 1px solid var(--line, #e2e8f0);
}
.hx-faq__item summary {
  list-style: none;
  cursor: pointer;
  padding: 20px 36px 20px 0;
  position: relative;
  font-weight: var(--weight-semibold, 600);
  font-size: var(--text-lg, 1.0625rem);
  color: var(--ink, #0f172a);
}
.hx-faq__item summary::-webkit-details-marker {
  display: none;
}
.hx-faq__item summary::after {
  content: "";
  position: absolute;
  right: 6px;
  top: 50%;
  width: 9px;
  height: 9px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-70%) rotate(45deg);
  transition: transform 0.2s;
}
.hx-faq__item[open] summary::after {
  transform: translateY(-30%) rotate(-135deg);
}
.hx-faq__item p {
  margin: 0 0 20px;
  padding-right: 36px;
  color: var(--muted, #64748b);
  line-height: 1.6;
}

@media (max-width: 960px) {
  .hx-nights,
  .hx-vero,
  .hx-cross,
  .hx-faq__in {
    grid-template-columns: 1fr;
  }
  .hx-nights {
    grid-template-rows: none;
    min-height: 0;
  }
  .hx-stay--lead {
    grid-row: auto;
    min-height: 320px;
  }
  .hx-stay {
    min-height: 220px;
  }
}
@media (max-width: 640px) {
  .hx-wrap {
    width: min(1180px, calc(100% - 32px));
  }
  .hx-stay__go {
    opacity: 1;
    transform: none;
  }
  .hx-vero {
    padding: 22px 16px 20px;
    border-radius: 22px;
  }
  .hx-vero__form {
    flex-direction: column;
    align-items: stretch;
    border-radius: 18px;
    padding: 8px;
    min-height: 0;
  }
  .hx-vero__form input,
  .hx-page .cell input,
  .hx-page .cell__face {
    font-size: 16px;
  }
  .hx-vero__form .vero-cta {
    width: 100%;
    justify-content: center;
  }
}
@media (prefers-reduced-motion: reduce) {
  .hx-stay img,
  .hx-cross__card img {
    transition: none;
  }
}

html[data-theme="dark"] .hx-band {
  background: var(--bg, #070d16);
}
html[data-theme="dark"] .hx-lead h2,
html[data-theme="dark"] .hx-faq__item summary {
  color: var(--ink, #e8eef6);
}
html[data-theme="dark"] .hx-lead p:not(.hx-kicker),
html[data-theme="dark"] .hx-faq__item p {
  color: var(--muted, #b6c4d6);
}
html[data-theme="dark"] .hx-faq,
html[data-theme="dark"] .hx-faq__list,
html[data-theme="dark"] .hx-faq__item {
  border-color: var(--line, #2a3b55);
}

