response.body:
/* Site theme — light tokens stay on :root; dark remaps html[data-theme="dark"] */

:root {
  --fill: #001438;
  --bg: #f4f7fb;
  --paper: #ffffff;
  --paper-2: #f8fafc;
  --accent: #f97211;
  --accent-hover: #e5670f;
  --accent-soft: #fff7f0;
  color-scheme: light;
}

html[data-theme="dark"] {
  color-scheme: dark;
  --brand: #d7e6f7;
  --brand-hover: #eef5ff;
  --brand-soft: #152238;
  --navy: #d7e6f7;
  --navy-mid: #8eabcc;
  --ink: #e8eef6;
  --muted: #9aa8bc;
  --line: #2a3b55;
  --wash: #070d16;
  --bg: #070d16;
  --card: #101a2a;
  --paper: #101a2a;
  --paper-2: #152033;
  --fill: #143056;
  --green-bg: #10291c;
  --danger-bg: #2b1418;
  /* Keep brand saffron — do not drift to #ff9a5c on desk surfaces */
  --accent: #f97211;
  --accent-hover: #e5670f;
  --accent-soft: #2a1a10;
  --shadow: 0 1px 2px rgba(0, 0, 0, 0.4);
  --ok: #3dd68c;
  --danger: #fb7185;
}

html[data-theme="dark"],
html[data-theme="dark"] body {
  background: var(--bg);
  color: var(--ink);
}

html[data-theme="dark"] ::selection {
  background: rgba(249, 114, 17, 0.35);
  color: #fff;
}

/* Toggle — one glyph at a time; .theme-toggle svg must not win over hide rules */
.theme-toggle-wrap { display: flex; align-items: center; }
.theme-toggle,
.header-actions .theme-toggle.hdr-dd__btn {
  display: inline-grid;
  place-items: center;
  width: 40px;
  min-width: 40px;
  height: 40px;
  padding: 0;
  border-radius: var(--radius-btn, 999px);
  cursor: pointer;
}
.theme-toggle svg {
  grid-area: 1 / 1;
  width: 20px;
  height: 20px;
}
.theme-toggle svg.theme-toggle__sun,
.drawer__ico svg.theme-toggle__sun {
  display: none;
}
html[data-theme="dark"] .theme-toggle svg.theme-toggle__sun,
html[data-theme="dark"] .drawer__ico svg.theme-toggle__sun {
  display: block;
}
html[data-theme="dark"] .theme-toggle svg.theme-toggle__moon,
html[data-theme="dark"] .drawer__ico svg.theme-toggle__moon {
  display: none;
}
.top__tools .theme-toggle-wrap { display: flex; align-items: center; }
.top__tools .theme-toggle {
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
}
.top__tools .theme-toggle:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.55);
}

/* Shared header currency control — button + listbox (no native <select> a11y dump) */
.top__tools {
  display: flex;
  align-items: center;
  gap: 10px;
  min-width: 0;
}
.top__currency.currency-ctl,
.currency-ctl {
  position: relative;
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto; /* never crush — clipping + chevron overlap came from flex-shrink */
  min-width: 0;
  max-width: min(12.5rem, 52vw);
}
.currency-ctl__btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  height: 40px;
  width: max-content;
  max-width: 100%;
  min-width: 4.5rem;
  padding: 0 12px 0 14px;
  border-radius: var(--radius-btn, 999px);
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font: 600 0.78rem/1 var(--font, "Outfit", system-ui, sans-serif);
  letter-spacing: 0.02em;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s;
}
.currency-ctl__btn:hover,
.currency-ctl__btn[aria-expanded="true"] {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.55);
}
.currency-ctl__btn:focus-visible {
  outline: 2px solid var(--accent, #f97211);
  outline-offset: 2px;
}
.currency-ctl__label {
  display: inline-flex;
  align-items: baseline;
  gap: 0;
  white-space: nowrap;
  /* ellipsis only when the rare long short-name still overflows max-width */
  min-width: 0;
  max-width: 9.5rem;
  overflow: hidden;
  text-overflow: ellipsis;
}
.currency-ctl__code {
  flex: 0 0 auto;
  font-variant-numeric: tabular-nums;
}
.currency-ctl__sep {
  flex: 0 0 auto;
  opacity: 0.72;
}
.currency-ctl__name {
  flex: 0 0 auto;
  font-weight: 500;
  opacity: 0.92;
}
.currency-ctl__chev {
  flex: 0 0 auto;
  width: 14px;
  height: 14px;
  opacity: 0.9;
}
.currency-ctl__menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  z-index: 60;
  width: min(280px, calc(100vw - 24px));
  max-height: min(340px, 60vh);
  overflow-y: auto;
  margin: 0;
  padding: 6px;
  list-style: none;
  background: #fff;
  color: #0f172a;
  border: 1px solid #e2e8f0;
  border-radius: 14px;
  box-shadow: 0 18px 40px rgba(0, 20, 56, 0.22);
}
.currency-ctl__menu[hidden] {
  display: none !important;
}
.currency-ctl__menu [role="option"] {
  display: grid;
  grid-template-columns: 3.2rem 1fr;
  align-items: center;
  gap: 8px;
  padding: 9px 10px;
  border-radius: 10px;
  font-size: 0.84rem;
  cursor: pointer;
  outline: none;
}
.currency-ctl__menu [role="option"] b {
  font-weight: 800;
  font-variant-numeric: tabular-nums;
  color: #001438;
}
.currency-ctl__menu [role="option"] span {
  color: #64748b;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  font-weight: 500;
}
.currency-ctl__menu [role="option"]:hover,
.currency-ctl__menu [role="option"]:focus,
.currency-ctl__menu [role="option"].is-selected {
  background: #f4f7fb;
}
.currency-ctl__menu [role="option"].is-selected b {
  color: var(--accent, #f97211);
}
.top.is-solid .currency-ctl__btn {
  background: rgba(255, 255, 255, 0.08);
}
html[data-theme="dark"] .currency-ctl__btn {
  border-color: rgba(215, 230, 247, 0.22);
  background-color: rgba(16, 26, 42, 0.65);
  color: #e8eef6;
}
html[data-theme="dark"] .currency-ctl__menu {
  background: #101a2a;
  color: #e8eef6;
  border-color: #2a3b55;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.45);
}
html[data-theme="dark"] .currency-ctl__menu [role="option"] b {
  color: #e8eef6;
}
html[data-theme="dark"] .currency-ctl__menu [role="option"] span {
  color: #9aa8bc;
}
html[data-theme="dark"] .currency-ctl__menu [role="option"]:hover,
html[data-theme="dark"] .currency-ctl__menu [role="option"]:focus,
html[data-theme="dark"] .currency-ctl__menu [role="option"].is-selected {
  background: #152033;
}

/* Tablet / phone header: code-only so the pill never fights icon buttons for space */
@media (max-width: 860px) {
  .top__currency.currency-ctl,
  .currency-ctl {
    max-width: 5.5rem;
  }
  .currency-ctl__label {
    max-width: none;
    overflow: visible;
    text-overflow: clip;
  }
  .currency-ctl__sep,
  .currency-ctl__name {
    display: none;
  }
  .currency-ctl__btn {
    min-width: 0;
    padding-inline: 12px 10px;
    font-size: 0.8rem;
  }
}
.drawer__ico .theme-toggle__sun,
.drawer__ico .theme-toggle__moon {
  width: 18px;
  height: 18px;
}

html[data-theme="dark"] .logo img,
html[data-theme="dark"] .site-header .logo img {
  filter: brightness(0) invert(1);
}

/* Hotel header + search */
html[data-theme="dark"] .site-header {
  background: rgba(7, 13, 22, 0.94);
  border-bottom-color: rgba(255, 255, 255, 0.08);
}
html[data-theme="dark"] .results-wrap,
html[data-theme="dark"] .list-sidebar,
html[data-theme="dark"] .filters-modal,
html[data-theme="dark"] .filters-sheet,
html[data-theme="dark"] aside,
html[data-theme="dark"] .results-toolbar,
html[data-theme="dark"] .detail-section,
html[data-theme="dark"] .search-bar {
  background: var(--paper-2);
  border-color: var(--line);
}
html[data-theme="dark"] .search-cell {
  background: var(--paper);
}
html[data-theme="dark"] .hdr-dd__btn,
html[data-theme="dark"] .btn-login,
html[data-theme="dark"] .btn-ghost,
html[data-theme="dark"] .hwl-select__btn,
html[data-theme="dark"] .search-bar,
html[data-theme="dark"] .search-cell,
html[data-theme="dark"] .search-cell input,
html[data-theme="dark"] .chip,
html[data-theme="dark"] .filters,
html[data-theme="dark"] .filters-card,
html[data-theme="dark"] .mini-map-card,
html[data-theme="dark"] .list-sidebar,
html[data-theme="dark"] .result-card,
html[data-theme="dark"] .highlight,
html[data-theme="dark"] .review-highlights,
html[data-theme="dark"] .know-card,
html[data-theme="dark"] .rate-card,
html[data-theme="dark"] .room-group,
html[data-theme="dark"] .write-review,
html[data-theme="dark"] .ask-ai-modal__panel,
html[data-theme="dark"] .lc-modal__panel,
html[data-theme="dark"] .hwl-select__menu,
html[data-theme="dark"] .hdr-dd__menu,
html[data-theme="dark"] .compare-sheet,
html[data-theme="dark"] .compare-tray,
html[data-theme="dark"] .date-strip,
html[data-theme="dark"] .date-strip__track,
html[data-theme="dark"] .date-chip,
html[data-theme="dark"] .flex-dates,
html[data-theme="dark"] .check .box,
html[data-theme="dark"] .rooms-search-strip,
html[data-theme="dark"] .gallery,
html[data-theme="dark"] .map-panel,
html[data-theme="dark"] .hold-note,
html[data-theme="dark"] .booking-hold-note {
  background: var(--paper);
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .btn-login,
html[data-theme="dark"] .btn-login:hover {
  color: var(--ink) !important;
  border-color: var(--line);
  background: var(--paper);
}
html[data-theme="dark"] .search-cell input,
html[data-theme="dark"] input,
html[data-theme="dark"] textarea,
html[data-theme="dark"] select {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--line);
  color-scheme: dark;
}
html[data-theme="dark"] input::placeholder,
html[data-theme="dark"] textarea::placeholder {
  color: #7c8ca3;
}
html[data-theme="dark"] .chip {
  background: var(--paper-2);
}
html[data-theme="dark"] .date-chip {
  background: var(--paper);
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .date-chip:hover { background: var(--paper-2); }
html[data-theme="dark"] .date-chip.is-on,
html[data-theme="dark"] .date-chip[aria-pressed="true"] {
  background: var(--paper-2);
}
html[data-theme="dark"] .mini-map-card .btn,
html[data-theme="dark"] .mini-map-card button {
  background: var(--paper);
  color: var(--ink);
  border-color: var(--line);
}
html[data-theme="dark"] .chip.is-on,
html[data-theme="dark"] .chip[aria-pressed="true"] {
  background: var(--brand-soft);
  border-color: #3d5574;
  color: var(--ink);
}
html[data-theme="dark"] .result-card,
html[data-theme="dark"] .highlight {
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .hl-ico {
  background: var(--paper-2);
  color: var(--ink);
}
html[data-theme="dark"] .muted,
html[data-theme="dark"] .reviews,
html[data-theme="dark"] #results-meta,
html[data-theme="dark"] .search-cell__label {
  color: var(--muted);
}

/* Site header keeps its dark bar in dark mode (--navy is remapped to a light tint there). */
html[data-theme="dark"] .top,
html[data-theme="dark"] .top.is-solid {
  background: #0a1830;
}
html[data-theme="dark"] body.xp-page:not(.xp-page--results) .top:not(.is-solid) {
  background: transparent;
}

/* Brand fills that used --navy / --brand as background */
html[data-theme="dark"] .hwl-guests-done,
html[data-theme="dark"] .chip-count,
html[data-theme="dark"] .filters-sheet-done__btn,
html[data-theme="dark"] .view-toggle button.active,
html[data-theme="dark"] .compare-add.is-on,
html[data-theme="dark"] .compare-ai__scope button.is-on,
html[data-theme="dark"] .tabs a.active,
html[data-theme="dark"] .ask-ai-modal__send.is-ready {
  background: var(--fill);
  color: #fff;
  border-color: var(--fill);
}

html[data-theme="dark"] .tabs {
  border-color: var(--line);
  background: var(--bg);
}
html[data-theme="dark"] .tabs a {
  color: var(--muted);
}
html[data-theme="dark"] .check .box {
  background: var(--paper-2);
  border-color: #3d5574;
}
html[data-theme="dark"] .rh-like {
  background: #10291c;
  color: #86efac;
}
html[data-theme="dark"] .rh-cat-bar { background: #243349; }
html[data-theme="dark"] .lc-modal__backdrop,
html[data-theme="dark"] .ask-ai-modal__backdrop,
html[data-theme="dark"] .filters-modal-backdrop {
