response.body:
/* Shared v2 chrome — header, footer, session, tokens */
:root {
  --navy: #001438;
  --navy-mid: #0b2244;
  --accent: #f97211;
  --accent-hover: #e5670f;
  --ink: #0f172a;
  --muted: #64748b;
  --line: #e2e8f0;
  --wash: #f4f7fb;
  --bg: #f4f7fb;
  --card: #fff;
  --accent-soft: #fff7f0;
  --ok: #067647;
  --danger: #b42318;
  /* One type stack — --font aliases --font-sans (site-typography / desks) */
  --font-sans: "Outfit", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font: var(--font-sans);
  --text-base: 0.9375rem;
  /* Chrome radii — pills for header CTAs; card/form stay softer */
  --radius: 12px;
  --radius-sm: 8px;
  --radius-btn: 999px;
  --radius-pill: 999px;
  --radius-card: 16px;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

*, *::before, *::after { box-sizing: border-box; }
html, body {
  margin: 0;
  min-height: 100%;
  max-width: 100%;
  overflow-x: clip;
  font-family: var(--font);
  color: var(--ink);
  background: var(--wash);
  -webkit-font-smoothing: antialiased;
}
body {
  min-height: 100svh;
  display: flex;
  flex-direction: column;
}
img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button, input, select, textarea { font-family: var(--font); }
[hidden] { display: none !important; }

/* Visually hidden until keyboard focus — never paint over the logo on mobile. */
.skip {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
  z-index: 100;
  background: var(--navy);
  color: #fff;
  font-weight: 700;
}
.skip:focus,
.skip:focus-visible {
  position: fixed;
  left: 12px;
  top: 12px;
  width: auto;
  height: auto;
  margin: 0;
  padding: 10px 14px;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
  border-radius: 10px;
  outline: 2px solid #fff;
  outline-offset: 2px;
}

.top {
  position: sticky;
  top: 0;
  z-index: 40;
  background: var(--navy);
  box-shadow: 0 10px 30px rgba(0, 20, 56, 0.18);
