.chrome-drawer__nav a:hover,
.chrome-drawer__nav button:hover { background: var(--wash); }
.chrome-drawer__signin {
  display: block;
  margin-top: 14px;
  text-align: center;
  background: var(--navy);
  color: #fff;
  border-radius: 12px;
  padding: 12px;
  font-weight: 800;
}

@media (max-width: 860px) {
  /* Hard-hide primary nav — never leave ghost links behind the logo. */
  .top__nav {
    display: none !important;
    visibility: hidden;
    pointer-events: none;
  }
  .top__account-label { display: none; }
  .top__help { display: none; }
  .top__inner {
    padding: 10px 12px;
    gap: 8px;
  }
  .top__menu { display: grid; }
  .top__tools { gap: 6px; }
  .top__tools .top__menu,
  .top__tools .theme-toggle {
    width: 36px;
    height: 36px;
    min-width: 36px;
  }
  .top__signin {
    padding: 7px 10px;
    font-size: var(--text-sm);
    max-width: 7.5rem;
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }
  .top__mark img { height: 22px; }
  .currency-ctl__name,
  .currency-ctl__sep { display: none; }
}

@media (prefers-reduced-motion: reduce) {
  * { animation: none !important; transition: none !important; }
}

/* With a desk docked on the right the header has less width: keep one tidy row instead of wrapping the nav. */
html[data-aero-desk="open"] .top__inner {
  gap: 16px;
  padding-left: clamp(14px, 2vw, 28px);
  padding-right: clamp(14px, 2vw, 28px);
}

html[data-aero-desk="open"] .top__nav {
  flex-wrap: nowrap;
  gap: 14px;
  white-space: nowrap;
}

html[data-aero-desk="open"] .top__tools {
  gap: 8px;
}

html[data-aero-desk="open"] .top__signin {
  padding: 7px 12px;
}

@media (max-width: 1240px) {
  html[data-aero-desk="open"] .currency-ctl__name,
  html[data-aero-desk="open"] .currency-ctl__sep {
    display: none;
  }
}

