      const v = JSON.parse(localStorage.getItem(key) || "[]");
      return Array.isArray(v) ? v : [];
    } catch (_) {
      return [];
    }
  }

  function dynamics() {
    const out = [];
    readArr("itinero.wl.trips.v1")
      .slice(0, 3)
      .forEach((t) => {
        out.push({
          id: "trip-" + (t.id || t.bookingId),
          group: "Continue",
          label:
            t.type === "flight"
              ? [t.origin, t.destination].filter(Boolean).join(" → ") || "Flight"
              : t.hotelName || "Stay",
          hint: "Open confirmation",
          href: "/account/#trips",
          keys: "trip booking " + (t.hotelName || "") + " " + (t.origin || ""),
        });
      });
    readArr("itinero.wl.watches.v1")
      .slice(0, 4)
      .forEach((w) => {
        out.push({
          id: "watch-" + w.id,
          group: "Watches",
          label: w.route || "Watch",
          hint: w.note || "Not a price lock",
          href: w.href || "/account/#alerts",
          keys: "watch " + (w.route || ""),
        });
      });
    readArr("itinero.wl.hotelViewed.v1")
      .slice(0, 3)
      .forEach((h) => {
        out.push({
          id: "view-" + h.id,
          group: "Continue",
          label: h.name || "Stay",
          hint: "Recently viewed",
          href: h.href || "/hotel/" + encodeURIComponent(h.id),
          keys: "viewed hotel " + (h.name || ""),
        });
      });
    readArr("itinero.wl.hotelRecents.v1")
      .slice(0, 3)
      .forEach((r, i) => {
        const q = new URLSearchParams({
          destination: r.destination || "",
          checkin: r.checkin || "",
          checkout: r.checkout || "",
        });
        out.push({
          id: "hrec-" + i,
          group: "Continue",
          label: r.destination || "Stay search",
          hint: [r.checkin, r.checkout].filter(Boolean).join(" → ") || "Hotels",
          href: "/hotels/results?" + q.toString(),
          keys: "hotel search " + (r.destination || ""),
        });
      });
    readArr("itinero.flights.recents.v1")
      .slice(0, 3)
      .forEach((r, i) => {
        const q = new URLSearchParams({
          from: r.from || "",
          to: r.to || "",
          depart: r.depart || "",
        });
        if (r.ret) q.set("return", r.ret);
        out.push({
          id: "frec-" + i,
          group: "Continue",
          label: [r.from, r.to].filter(Boolean).join(" → "),
          hint: r.depart || "Flights",
          href: "/flights/results/?" + q.toString(),
          keys: "flight " + (r.from || "") + " " + (r.to || ""),
        });
      });
    return out;
  }

  function allItems() {
    return STATIC.concat(dynamics());
  }

  function match(item, q) {
    if (!q) return true;
    const hay = [item.label, item.hint, item.keys, item.group].join(" ").toLowerCase();
    return q.split(/\s+/).every((part) => hay.includes(part));
  }

  function isMac() {
    return /Mac|iPhone|iPad/.test(navigator.platform || "");
  }

  function chordLabel() {
    return isMac() ? "⌘K" : "Ctrl K";
  }

  let box = null;
  let index = 0;
  let rows = [];

  function ensure() {
    if (box) return box;
    box = document.createElement("div");
    box.className = "cmdk";
    box.hidden = true;
    box.innerHTML = `
      <div class="cmdk__scrim" data-cmdk-close="1"></div>
      <div class="cmdk__panel" role="dialog" aria-modal="true" aria-label="Jump to">
        <div class="cmdk__search">
          <svg viewBox="0 0 24 24" width="18" height="18" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.5-3.5"/></svg>
          <input id="cmdk-q" type="search" placeholder="Jump to flights, stays, Vero, trips…" autocomplete="off" />
          <kbd>${chordLabel()}</kbd>
        </div>
        <div class="cmdk__list" id="cmdk-list" role="listbox"></div>
        <p class="cmdk__foot">Enter to open · Esc to close · live fares only</p>
      </div>`;
    document.body.appendChild(box);
    box.addEventListener("click", (e) => {
      if (e.target.closest("[data-cmdk-close]")) close();
      const go = e.target.closest("[data-cmdk-href]");
      if (go) {
        location.href = go.getAttribute("data-cmdk-href");
      }
    });
    $("#cmdk-q", box)?.addEventListener("input", () => paint());
    return box;
  }

  function paint() {
    ensure();
    const q = String($("#cmdk-q", box)?.value || "")
      .trim()
      .toLowerCase();
    rows = allItems().filter((item) => match(item, q));
    if (index >= rows.length) index = Math.max(0, rows.length - 1);
    const groups = [];
    rows.forEach((item, i) => {
      if (!groups.includes(item.group)) groups.push(item.group);
      item._i = i;
    });
    const list = $("#cmdk-list", box);
    if (!list) return;
    if (!rows.length) {
      list.innerHTML = `<p class="cmdk__empty">Nothing matches. Try “Paris”, “flights”, or “Vero”.</p>`;
      return;
    }
    list.innerHTML = groups
      .map((g) => {
        const items = rows.filter((r) => r.group === g);
        return (
          `<p class="cmdk__group">${g}</p>` +
          items
            .map((item) => {
              const esc = (v) =>
                String(v || "")
                  .replace(/&/g, "&amp;")
                  .replace(/</g, "&lt;")
                  .replace(/"/g, "&quot;");
              return `
          <a class="cmdk__row${item._i === index ? " is-on" : ""}" role="option" href="${esc(
                item.href
              )}" data-cmdk-href="${esc(item.href)}" data-i="${item._i}">
            <span>
              <b>${esc(item.label)}</b>
              ${item.hint ? `<small>${esc(item.hint)}</small>` : ""}
            </span>
          </a>`;
            })
            .join("")
        );
      })
      .join("");
    list.querySelector(".cmdk__row.is-on")?.scrollIntoView({ block: "nearest" });
    list.querySelectorAll("[data-cmdk-href]").forEach((a) => {
      a.addEventListener("click", (e) => {
        e.preventDefault();
        const href = a.getAttribute("data-cmdk-href");
        if (href) location.href = href;
      });
    });
  }

  function open() {
    ensure();
    box.hidden = false;
    document.body.classList.add("cmdk-open");
    index = 0;
    const input = $("#cmdk-q", box);
    if (input) input.value = "";
    paint();
    requestAnimationFrame(() => input?.focus());
  }

  function close() {
    if (!box) return;
    box.hidden = true;
    document.body.classList.remove("cmdk-open");
  }

  function toggle() {
    if (box && !box.hidden) close();
    else open();
  }

  function move(dir) {
    if (!rows.length) return;
    index = (index + dir + rows.length) % rows.length;
    paint();
  }

  function go() {
    const item = rows[index];
    if (item?.href) location.href = item.href;
  }

  function maybeHint() {
    if (/signin\.html/i.test(location.pathname)) return;
    try {
      if (sessionStorage.getItem("itinero.cmdk.hint.v1")) return;
      sessionStorage.setItem("itinero.cmdk.hint.v1", "1");
    } catch (_) {
      return;
    }
    const tip = document.createElement("div");
    tip.className = "cmdk-hint";
    tip.innerHTML = `Jump anywhere <kbd>${chordLabel()}</kbd>`;
    document.body.appendChild(tip);
    setTimeout(() => tip.remove(), 4200);
  }

  function injectButton() {
    if ($("#cmdk-btn") || document.body.classList.contains("vero-body")) return;
    const tools = $(".top__tools");
    if (!tools) return;
    const btn = document.createElement("button");
    btn.type = "button";
    btn.id = "cmdk-btn";
    btn.className = "cmdk-btn top__icon";
    const chord = chordLabel();
    btn.setAttribute("aria-label", "Jump to page, " + chord);
    btn.setAttribute("title", "Jump · " + chord);
    btn.innerHTML =
      '<svg viewBox="0 0 24 24" width="20" height="20" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="11" cy="11" r="7"/><path d="M20 20l-3.2-3.2"/></svg>';
    const signin = tools.querySelector(".top__signin, .top__account");
    tools.insertBefore(btn, signin || null);
    btn.addEventListener("click", open);
  }

  function wire() {
    injectButton();
    maybeHint();
    document.addEventListener("keydown", (e) => {
      const meta = e.metaKey || e.ctrlKey;
      if (meta && String(e.key).toLowerCase() === "k") {
        e.preventDefault();
        toggle();
        return;
      }
      if (!box || box.hidden) return;
      if (e.key === "Escape") {
        e.preventDefault();
        close();
      } else if (e.key === "ArrowDown") {
        e.preventDefault();
        move(1);
      } else if (e.key === "ArrowUp") {
        e.preventDefault();
        move(-1);
      } else if (e.key === "Enter") {
        e.preventDefault();
        go();
      }
    });
  }

  root.ItineroCommandPalette = { open, close, toggle };

  if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", wire);
  else wire();
})(window);

