.fl-dest-band {
  padding-bottom: clamp(48px, 6vw, 80px);
  max-width: 100%;
  overflow-x: clip;
  overflow-y: visible;
}
/* Scroll rail — fixed cards + snap; overflow stays inside the rail, never the document */
.fl-rail {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(200px, 220px);
  gap: 14px;
  box-sizing: border-box;
