response.body:
/* Standard AI surround — same aurora as Vero CTA.
   Use on any insight, summary, Ask AI, or generated copy so it reads as AI. */

:root {
  --ai-lilac: #f97211;
  --ai-pink: #fb9a4d;
  --ai-rose: #fdba74;
  --ai-saffron: #ffd9b3;
  --ai-ink: #9a3a06;
  --ai-muted: #c2500c;
  --ai-wash: #fffafc;
  --ai-ring: 125deg, #f97211 0%, #fb9a4d 38%, #fdba74 68%, #ffd9b3 100%;
}

.ai {
  position: relative;
  isolation: isolate;
  z-index: 0;
  background:
    linear-gradient(180deg, var(--ai-wash) 0%, #fff 58%) padding-box,
    linear-gradient(var(--ai-ring)) border-box;
  border: 1px solid transparent;
  box-shadow:
    0 0 0 1px rgba(249, 114, 17, 0.22),
    0 8px 22px rgba(249, 114, 17, 0.08),
    -4px 0 14px rgba(249, 114, 17, 0.08),
    4px 0 14px rgba(251, 146, 60, 0.06);
}

.ai--block {
  padding: 16px 16px 14px;
  border-radius: 16px;
}

.ai--inline {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 8px 14px 8px 10px;
  border-radius: 999px;
}

.ai__mark {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  height: 22px;
  padding: 0 8px 0 6px;
  border-radius: 999px;
  background: #fff;
  color: var(--ai-muted);
  font-size: var(--text-2xs);
  font-weight: 800;
  letter-spacing: var(--tracking-kicker, 0.06em);
  line-height: 1;
  text-transform: uppercase;
  vertical-align: middle;
  box-shadow:
    0 0 0 1px rgba(249, 114, 17, 0.42),
    0 2px 8px rgba(249, 114, 17, 0.12);
}

.ai__mark svg {
  width: 12px;
  height: 12px;
  display: block;
  color: #c2500c;
}

.ai__mark b {
  font-weight: 800;
}

.ai .section-head {
  margin: 0 0 12px;
  align-items: center;
}

.ai .section-head h2 {
  display: inline-flex;
  align-items: center;
  flex-wrap: wrap;
  gap: 8px;
}

/* Neutralize older local frames when they opt into .ai */
.review-highlights.ai,
.compare-ai.ai,
.vero-filter.ai,
.date-save.ai,
.ask-ai.ai,
.ask-ai__msg--ai.ai,
.ask-ai-modal__msg--ai.ai {
  background:
    linear-gradient(180deg, var(--ai-wash) 0%, #fff 58%) padding-box,
    linear-gradient(var(--ai-ring)) border-box;
  border: 1px solid transparent;
}

/* Nested highlight cards stay neutral — rainbow lives on the outer `.ai` only. */
.highlights.ai {
  padding: 0;
  border-radius: 0;
  background: transparent;
  border: 0;
  box-shadow: none;
}

.highlights.ai .highlight {
  box-shadow: none;
}

.highlights.ai .highlight::before {
  background: var(--navy, #001438);
}

.vero-filter.ai {
  box-shadow:
    0 0 0 1px rgba(249, 114, 17, 0.22),
    0 8px 22px rgba(249, 114, 17, 0.08);
}

.vero-filter__head .ai__mark {
  margin-left: auto;
  flex-shrink: 0;
}

.date-save.ai {
  color: var(--ai-ink);
}

.date-save.ai .date-save__icon {
  background: linear-gradient(135deg, #f97211 0%, #f97211 100%);
}

.date-save.ai .date-save__msg strong,
.date-save.ai .date-save__cta {
  color: var(--ai-ink);
}

.date-save.ai .date-save__cta:hover {
  color: #4c1d95;
}

.ask-ai__msg--ai.ai,
.ask-ai-modal__msg--ai.ai {
  border-radius: 14px;
  padding: 10px 12px;
}

.tabs .ai__mark {
  margin-left: 4px;
}

.tabs .ai__mark b {
  position: absolute;
  width: 1px;
  height: 1px;
  overflow: hidden;
  clip: rect(0 0 0 0);
}

.ask-ai__head .ai__mark,
.ask-ai-modal__head h2 .ai__mark {
  flex-shrink: 0;
}

.insight-suggest {
  margin: 0 0 16px;
}
.insight-suggest[hidden] { display: none !important; }
.insight-suggest__kicker {
  margin: 8px 0 10px;
  font-size: var(--text-xs, 0.75rem);
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--ai-muted, #c2500c);
}
.insight-suggest__list {
  list-style: none;
