body.cmdk-open { overflow: hidden; }
.cmdk { position: fixed; inset: 0; z-index: 80; }
.cmdk[hidden] { display: none !important; }
.cmdk__scrim {
  position: absolute;
  inset: 0;
  background: rgba(8, 16, 32, 0.46);
  backdrop-filter: blur(8px);
}
.cmdk__panel {
  position: relative;
  width: min(560px, calc(100vw - 28px));
  margin: 12vh auto 0;
  background: #fff;
  border: 1px solid #e2e8f0;
  border-radius: 18px;
  box-shadow: 0 30px 80px rgba(15, 23, 42, 0.22);
  overflow: hidden;
}
.cmdk__search {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 14px 16px;
  border-bottom: 1px solid #eef2f7;
  color: #64748b;
}
.cmdk__search input {
  flex: 1;
  border: 0;
  outline: 0;
  font: 600 1rem/1.3 Outfit, system-ui, sans-serif;
  color: #0f172a;
  background: transparent;
}
.cmdk__search kbd {
  border: 1px solid #e2e8f0;
  border-radius: 6px;
  padding: 3px 6px;
  font: 700 0.68rem/1 ui-monospace, SFMono-Regular, Menlo, monospace;
  color: #64748b;
}
.cmdk__list {
  max-height: min(52vh, 420px);
  overflow: auto;
  padding: 8px;
}
.cmdk__group {
  margin: 10px 8px 4px;
  font: 800 0.68rem/1 Outfit, system-ui, sans-serif;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}
.cmdk__row {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-radius: 12px;
  color: inherit;
  text-decoration: none;
}
.cmdk__row b { display: block; color: #001438; font-size: var(--text-base); }
.cmdk__row small { display: block; margin-top: 2px; color: #64748b; font-weight: 500; }
.cmdk__row.is-on,
.cmdk__row:hover { background: #fff7ed; }
.cmdk__empty {
  margin: 24px 12px;
  text-align: center;
  color: #64748b;
  font-weight: 500;
}
.cmdk__foot {
  margin: 0;
  padding: 10px 16px 12px;
  border-top: 1px solid #eef2f7;
  color: #94a3b8;
  font-size: var(--text-xs);
  font-weight: 600;
}
@media (max-width: 860px) {
  .top__tools .cmdk-btn { display: none; }
  .cmdk__panel { margin-top: 8vh; }
}
.cmdk-hint {
  position: fixed;
  right: 18px;
  bottom: 18px;
  z-index: 70;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 10px 14px;
  border-radius: 999px;
  background: #001438;
  color: #fff;
  font: 700 0.8rem/1 Outfit, system-ui, sans-serif;
  box-shadow: 0 12px 28px rgba(0, 20, 56, 0.22);
  animation: cmdk-hint-in 0.28s ease both;
}
.cmdk-hint kbd {
  padding: 3px 6px;
  border-radius: 6px;
  background: rgba(255, 255, 255, 0.14);
  font: 750 0.72rem/1 Outfit, system-ui, sans-serif;
}
@keyframes cmdk-hint-in {
  from { opacity: 0; transform: translateY(8px); }
  to { opacity: 1; transform: none; }
}

