response.body:
/* Experiences — same chrome, type scale, and hero dock as homepage. */

:root {
  --xp-max: 1180px;
  --xp-radius: 16px;
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

.xp-page,
.xp-standalone {
  background: var(--wash, #f4f7fb);
}

.xp-page main,
.xp-standalone main {
  flex: 1 0 auto;
}

.xp-page .top__tools .theme-toggle-wrap,
.xp-standalone .top__tools .theme-toggle-wrap {
  display: flex;
}
.xp-page .top__tools .theme-toggle,
.xp-standalone .top__tools .theme-toggle {
  display: inline-grid;
  place-items: center;
  width: 38px;
  min-width: 38px;
  height: 38px;
  padding: 0;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  cursor: pointer;
}
.xp-page .top__tools .theme-toggle:hover,
.xp-standalone .top__tools .theme-toggle:hover {
  background: rgba(255, 255, 255, 0.16);
  border-color: #fff;
}
.xp-page .top__tools .theme-toggle svg,
.xp-standalone .top__tools .theme-toggle svg {
  width: 18px;
  height: 18px;
}

.xp-page:not(.xp-page--results) .top,
.xp-standalone .top {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 50;
  background: transparent;
  box-shadow: none;
  transition: background 0.35s var(--ease), box-shadow 0.35s var(--ease);
}
.xp-page:not(.xp-page--results) .top.is-solid,
.xp-standalone .top.is-solid {
  background: rgba(0, 20, 56, 0.94);
  -webkit-backdrop-filter: blur(14px);
  backdrop-filter: blur(14px);
  box-shadow: 0 10px 30px rgba(0, 20, 56, 0.2);
}
.xp-standalone .top__inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  gap: 24px;
}
.xp-standalone .top__mark img {
  height: 24px;
  width: auto;
}
.xp-standalone .top__nav {
  display: none;
  gap: 18px;
  flex: 1;
}
.xp-standalone .top__nav a {
  color: rgba(255, 255, 255, 0.86);
  font-weight: var(--weight-semibold, 600);
  font-size: var(--text-base, 0.9375rem);
}
.xp-standalone .top__nav a[aria-current="page"],
.xp-standalone .top__nav a:hover {
  color: #fff;
}
.xp-standalone .top__tools {
  margin-left: auto;
  display: flex;
  align-items: center;
  gap: 10px;
}
.xp-standalone .top__signin {
  color: #fff;
  font-weight: var(--weight-bold, 700);
  font-size: var(--text-base, 0.9375rem);
}
@media (min-width: 860px) {
  .xp-standalone .top__nav { display: flex; }
}

.xp-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 44px;
  padding: 0 16px;
  border-radius: 999px;
  border: 1px solid transparent;
  font: inherit;
  font-size: var(--text-base, 0.9375rem);
  font-weight: var(--weight-bold, 700);
  cursor: pointer;
}
.xp-btn svg { flex: 0 0 auto; }
.xp-btn:disabled { opacity: 0.55; cursor: wait; }
.xp-btn--primary {
  background: var(--accent, #f97211);
  color: #fff;
}
.xp-btn--primary:hover { background: var(--accent-hover, #e5670f); }
.xp-btn--navy {
  background: var(--navy, #001438);
  color: #fff;
}

/* Hero — homepage stage: full viewport, line + dock centered */
.xp-hero {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  display: grid;
  align-items: start;
  justify-items: center;
  color: #fff;
  overflow: clip;
  background: #0a1628;
}
.xp-hero::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(ellipse 78% 58% at 50% 46%, rgba(0, 8, 22, 0.55), transparent 70%),
    linear-gradient(180deg, rgba(0, 12, 32, 0.58) 0%, rgba(0, 10, 24, 0.28) 42%, rgba(0, 8, 20, 0.46) 100%);
}
.xp-hero__media {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.xp-hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1.04);
}
.xp-hero__body {
  position: relative;
  z-index: 2;
  width: min(1040px, calc(100% - 40px));
  margin: 0 auto;
  padding: max(96px, calc(50vh - 108px)) 0 48px;
  text-align: center;
}
.xp-hero__kicker {
  margin: 0 0 10px;
  font-size: var(--text-xs, 0.75rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.82);
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.5);
}
.xp-hero h1.xp-hero__line,
.xp-hero__line {
  margin: 0 0 8px;
  min-height: 1.3em;
  font-family: var(--font, inherit);
  font-size: clamp(1.85rem, 4.8vw, 3.1rem);
  font-weight: var(--weight-bold, 700);
  letter-spacing: var(--tracking-tight, -0.03em);
  line-height: 1.12;
  color: #fff;
  text-shadow: 0 2px 18px rgba(0, 0, 0, 0.55), 0 12px 36px rgba(0, 0, 0, 0.42);
}
.xp-page--results .xp-hero h1.xp-hero__line,
.xp-page--results .xp-hero__line {
  font-size: clamp(var(--text-xl, 1.25rem), 2.6vw, var(--text-3xl, 1.75rem));
  font-weight: var(--weight-semibold, 600);
  line-height: var(--leading-tight, 1.2);
}
.xp-hero__media video,
.xp-hero__vid {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center 42%;
}
.xp-hero__vid {
  opacity: 0;
  transition: opacity 0.9s ease;
}
.xp-hero__vid.is-on { opacity: 1; }
@media (prefers-reduced-motion: reduce) {
  .xp-hero__vid { display: none; }
}

/* Glass search dock — same chrome as homepage hotels */
.dock {
  margin-top: 28px;
  text-align: left;
  color: #fff;
}
.dock__form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: stretch;
  padding: 6px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(0, 10, 28, 0.72);
  backdrop-filter: blur(22px) saturate(1.2);
  -webkit-backdrop-filter: blur(22px) saturate(1.2);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.12) inset,
    0 14px 40px rgba(0, 0, 0, 0.35);
}
.dock__fields {
  display: grid;
  grid-template-columns: 1.35fr 1fr 1fr 1.1fr;
  gap: 0;
  min-width: 0;
}
.cell {
  display: grid;
  gap: 2px;
  padding: 9px 14px;
  background: transparent;
  border-right: 1px solid rgba(255, 255, 255, 0.18);
  cursor: text;
  min-width: 0;
  transition: background 0.15s;
  border-radius: 999px;
}
.cell:hover,
.cell:focus-within { background: rgba(255, 255, 255, 0.1); }
.cell:last-child { border-right: 0; }
.cell span {
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.72);
}
.cell input {
  border: 0;
  outline: none;
  background: transparent;
  font-family: inherit;
  font-weight: 700;
  font-size: var(--text-base, 0.9375rem);
  color: #fff;
  width: 100%;
  padding: 0;
  line-height: 1.25;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
}
.cell input::placeholder {
  text-transform: none;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
}
.cell__face {
  border: 0;
  outline: none;
  background: transparent;
  font-family: inherit;
  font-weight: 700;
  font-size: var(--text-base, 0.9375rem);
  color: #fff;
  width: 100%;
  padding: 0;
  margin: 0;
  text-align: left;
  cursor: pointer;
  line-height: 1.25;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
}
.cell__face:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.35);
  outline-offset: 2px;
  border-radius: 4px;
}
.dock__go {
  border: 0;
  border-radius: 999px;
  background: var(--accent, #f97211);
  color: #fff;
  font-family: inherit;
  font-weight: 700;
  font-size: var(--text-base, 0.9375rem);
  padding: 0 22px;
  cursor: pointer;
  min-width: 128px;
  height: 100%;
  min-height: 44px;
  transition: background 0.15s, transform 0.15s;
}
.dock__go:hover { background: var(--accent-hover, #e5670f); }
.dock__go:active { transform: scale(0.98); }
.dock__go:disabled { opacity: 0.55; cursor: wait; }
.xp-status {
  min-height: 1.2rem;
  margin: 12px 2px 0;
  font-size: var(--text-sm, 0.8125rem);
  font-weight: 600;
  color: rgba(255, 255, 255, 0.82);
  text-align: left;
  text-shadow: 0 1px 8px rgba(0, 0, 0, 0.45);
}
.xp-status.is-error { color: #fecaca; }
.xp-status.is-ok { color: #bbf7d0; }

.dock-pop {
  position: fixed;
  z-index: 80;
  min-width: min(300px, calc(100vw - 32px));
  max-width: min(360px, calc(100vw - 24px));
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(6, 14, 28, 0.94);
  backdrop-filter: blur(24px) saturate(1.15);
  -webkit-backdrop-filter: blur(24px) saturate(1.15);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  text-align: left;
  color: #fff;
}
.dock-pop[hidden] { display: none !important; }
.dock-pop--cal {
  min-width: min(320px, calc(100vw - 24px));
  max-width: min(340px, calc(100vw - 24px));
}
.dock-pop__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px 8px;
}
.dock-pop__title {
  margin: 0;
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.42);
}
.dock-pop__cal { padding: 14px 12px 12px; }
.dock-pop__cal-top {
  display: grid;
  gap: 4px;
  padding: 0 4px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 12px;
}
.dock-pop__picked {
  margin: 0;
  font-size: var(--text-lg, 1.0625rem);
  font-weight: 700;
  color: #fff;
}
.dock-pop__quick {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 2px 12px;
}
.dock-pop__chip {
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.88);
  font: inherit;
  font-size: var(--text-xs, 0.75rem);
  font-weight: 600;
  padding: 7px 11px;
  border-radius: 999px;
  cursor: pointer;
}
.dock-pop__chip:hover { background: rgba(255, 255, 255, 0.1); }
.dock-pop__chip.is-on {
  background: rgba(249, 114, 17, 0.18);
  border-color: rgba(249, 114, 17, 0.5);
  color: #fff;
}
.dock-pop__head--cal { padding: 0 2px 10px; }
.dock-pop__navbtn {
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 1.125rem;
  cursor: pointer;
  display: grid;
  place-items: center;
}
.dock-pop__navbtn:disabled { opacity: 0.28; cursor: not-allowed; }
.dock-pop__month {
  margin: 0;
  flex: 1;
  text-align: center;
  font-weight: 700;
}
.dock-pop__week,
.dock-pop__grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
  padding: 0 2px;
}
.dock-pop__week span {
  text-align: center;
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: 700;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.38);
  padding: 6px 0;
}
.dock-pop__day-spacer { min-height: 40px; }
.dock-pop__day {
  min-height: 40px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: rgba(255, 255, 255, 0.9);
  font: inherit;
  font-weight: 600;
  cursor: pointer;
}
.dock-pop__day:hover:not(:disabled) { background: rgba(255, 255, 255, 0.12); }
.dock-pop__day.is-today:not(.is-on) { box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.35); }
.dock-pop__day.is-on { background: var(--accent, #f97211); color: #fff; font-weight: 800; }
.dock-pop__day:disabled { opacity: 0.22; cursor: not-allowed; }
.dock-pop__list { list-style: none; margin: 0; padding: 4px 0; max-height: min(300px, 48vh); overflow-y: auto; }
.dock-pop__opt {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
