@media (max-width: 980px) {
  .xp-page--results .xp-board { grid-template-columns: 1fr; }
  .xp-page--results .xp-filters-open {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
    border: 1px solid var(--line, #e2e8f0);
    background: #fff;
    border-radius: 8px;
    padding: 7px 11px;
    font: inherit;
    font-weight: 700;
    color: var(--navy, #001438);
    cursor: pointer;
  }
  .xp-page--results .xp-filters-count {
    display: inline-grid;
    place-items: center;
    min-width: 18px;
    height: 18px;
    padding: 0 5px;
    border-radius: 999px;
    background: var(--navy, #001438);
    color: #fff;
    font-size: 0.6875rem;
    font-weight: 800;
