  }
  .xp-page--results.xp-filters-open .xp-filters-scrim { display: block; }
  .xp-page--results .xp-filters {
    position: fixed;
    z-index: 70;
    inset: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    height: auto;
    max-height: none;
    background: transparent;
    border: 0;
    border-radius: 0;
    padding: 0;
    box-shadow: none;
    overflow: hidden;
    transform: translateY(110%);
    transition: transform 0.25s var(--ease, ease);
    pointer-events: none;
  }
  .xp-page--results.xp-filters-open .xp-filters {
    transform: none;
    pointer-events: auto;
  }
  .xp-page--results .xp-filters__sheet {
    display: flex;
    flex-direction: column;
    width: 100%;
    max-height: min(88dvh, 720px);
    overflow: auto;
    background: #fff;
    border-radius: 20px 20px 0 0;
    padding: 16px 16px 28px;
    box-shadow: 0 -16px 40px rgba(0, 14, 36, 0.18);
  }
  .xp-page--results .xp-filters__close,
  .xp-page--results .xp-filters-done {
    display: inline-flex;
    align-items: center;
    justify-content: center;
  }
  .xp-page--results .xp-filters__close {
    width: 32px;
    height: 32px;
    margin-left: 4px;
    border: 0;
    border-radius: 999px;
    background: #f1f5f9;
    color: var(--navy, #001438);
    font-size: 1.25rem;
    line-height: 1;
    cursor: pointer;
  }
  .xp-page--results .xp-filters-done {
    width: 100%;
    margin-top: 8px;
    border: 0;
    border-radius: 12px;
    background: var(--navy, #001438);
    color: #fff;
    font: inherit;
    font-weight: 800;
    padding: 12px 16px;
    cursor: pointer;
  }
}
@media (max-width: 820px) {
  .xp-page--results .xp-mast {
    top: 52px;
  }
  .xp-page--results .xp-filters { top: 0; }
  .xp-page--results .dock__fields {
    background: #f8fafc;
  }
  .xp-page--results .cell {
    border-right-color: var(--line, #e2e8f0);
