html[data-theme="dark"] .xp-page--results .xp-filters,
html[data-theme="dark"] .xp-page--results .xp-filters-open,
html[data-theme="dark"] .xp-page--results .xp-filters__sheet {
  background: var(--card, #0f172a);
  border-color: var(--line, #1e293b);
  color: var(--ink, #e2e8f0);
}
html[data-theme="dark"] .xp-page--results .xp-filters__head h2,
html[data-theme="dark"] .xp-page--results .xp-fcheck,
html[data-theme="dark"] .xp-page--results .xp-filters-open {
  color: var(--navy, #e2e8f0);
}
html[data-theme="dark"] .xp-page--results .xp-vero-filter {
  background: linear-gradient(180deg, #1c1917 0%, var(--card, #0f172a) 55%);
