@media (prefers-reduced-motion: reduce) {
  .xp-dest img { transition: none; }
  .xp-skel { animation: none; }
}

/* Landing parity with hotels/flights — wash results, FAQ, cross-sell, honesty */
body.xp-page--results {
  background: var(--wash, #f4f7fb);
  color: var(--ink, #0f172a);
}
.xp-price__na {
  font-weight: 700;
  color: var(--muted, #64748b);
  font-size: var(--text-sm, 0.8125rem);
}
.xp-card__cancel {
  color: var(--ok, #0f766e);
  font-weight: 600;
}
.xp-card__meta {
  flex-wrap: nowrap; /* keep one line so card heights stay equal */
  gap: 6px 10px;
  max-height: 1.25em;
}
.xp-card__body p {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
html[data-theme="dark"] .xp-card__cancel {
  color: #5eead4;
}
html[data-theme="dark"] .xp-price__na {
  color: #94a3b8;
}
@media (max-width: 720px) {
  .xp-card__foot {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
  .xp-card__cta {
    align-self: flex-end;
  }
}
.xp-inventory-note {
  width: min(100%, var(--xp-max));
  margin: 0 auto 8px;
  padding: 14px 18px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--accent, #f97211) 35%, var(--line, #e2e8f0));
  background: color-mix(in srgb, var(--accent, #f97211) 8%, var(--card, #fff));
  color: var(--ink, #0f172a);
  font-size: var(--text-sm, 0.8125rem);
  line-height: 1.5;
}
.xp-empty--inline {
  grid-column: 1 / -1;
  padding: 28px 20px;
  text-align: center;
  border: 1px dashed var(--line, #e2e8f0);
  border-radius: 18px;
  background: var(--card, #fff);
}
.xp-empty--inline p {
  margin: 0 0 12px;
  color: var(--muted, #64748b);
}
.xp-band {
  padding: clamp(56px, 7vw, 96px) 0;
  background: var(--bg, #fff);
  color: var(--ink, #0f172a);
}
.xp-wrap {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}
.xp-band__lead {
  max-width: 640px;
  margin-bottom: clamp(24px, 3.5vw, 40px);
}
.xp-band__lead h2 {
  margin: 6px 0 0;
  font-size: clamp(1.75rem, 3vw, 2.375rem);
  line-height: 1.1;
  letter-spacing: var(--tracking-tight, -0.02em);
  font-weight: var(--weight-bold, 700);
  color: var(--ink, #0f172a);
}
.xp-cross {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.xp-cross__card {
  position: relative;
  display: block;
  min-height: 220px;
  overflow: hidden;
  border-radius: 20px;
  color: #fff;
  text-decoration: none;
  isolation: isolate;
  background: var(--navy, #001438);
}
.xp-cross__card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
  filter: saturate(0.88) contrast(1.05) brightness(0.9);
  transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.xp-cross__card:hover img { transform: scale(1.05); }
.xp-cross__shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(
    180deg,
    rgba(0, 8, 20, 0.28) 0%,
    rgba(0, 8, 20, 0.06) 22%,
    rgba(0, 6, 14, 0.52) 42%,
    rgba(0, 4, 10, 0.82) 62%,
    rgba(0, 2, 6, 0.94) 82%,
    rgba(0, 0, 0, 0.97) 100%
  );
}
.xp-cross__txt {
  position: absolute;
  left: 20px;
  right: 20px;
  bottom: 48px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.xp-cross__txt strong {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.xp-cross__txt span {
  font-size: var(--text-sm, 0.8125rem);
  color: rgba(255, 255, 255, 0.82);
  max-width: 36ch;
}
.xp-cross__go {
  position: absolute;
  left: 20px;
  bottom: 18px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-sm, 0.8125rem);
  font-weight: 700;
  color: #99f6e4;
}
.xp-cross__card:focus-visible {
  outline: 3px solid #0f6b6b;
  outline-offset: 3px;
}
.xp-faq {
  border-top: 1px solid var(--line, #e2e8f0);
}
.xp-faq__in {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: clamp(24px, 5vw, 80px);
  align-items: start;
}
.xp-faq .xp-band__lead { margin-bottom: 0; }
.xp-faq__list { border-top: 1px solid var(--line, #e2e8f0); }
.xp-faq__item { border-bottom: 1px solid var(--line, #e2e8f0); }
.xp-faq__item summary {
  list-style: none;
  cursor: pointer;
  padding: 20px 36px 20px 0;
  position: relative;
  font-weight: var(--weight-semibold, 600);
  font-size: var(--text-lg, 1.0625rem);
  color: var(--ink, #0f172a);
}
.xp-faq__item summary::-webkit-details-marker { display: none; }
.xp-faq__item summary::after {
  content: "";
  position: absolute;
  right: 6px;
  top: 50%;
  width: 9px;
  height: 9px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-70%) rotate(45deg);
  transition: transform 0.2s;
}
.xp-faq__item[open] summary::after {
  transform: translateY(-30%) rotate(-135deg);
}
.xp-faq__item p {
  margin: 0 0 20px;
  padding-right: 36px;
  color: var(--muted, #64748b);
  line-height: 1.6;
}
.xp-detail__panel {
  border-radius: 20px 20px 0 0;
  box-shadow: 0 -16px 48px rgba(0, 14, 36, 0.18);
}
.xp-page--results .xp-detail__panel {
  max-width: min(720px, 100%);
}
@media (max-width: 820px) {
  .xp-cross { grid-template-columns: 1fr; }
  .xp-faq__in { grid-template-columns: 1fr; }
  .xp-wrap { width: min(1180px, calc(100% - 28px)); }
  .xp-cross__card { min-height: 200px; }
}
html[data-theme="dark"] body.xp-page--results {
  background: var(--wash, #0b1220);
}
html[data-theme="dark"] .xp-band {
