.xp-results { padding-top: 36px; }
.xp-toolbar {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
  margin: 0 0 16px;
}
.xp-chip {
  border: 1px solid var(--line, #e2e8f0);
