}
.xp-check__go { width: 100%; justify-content: center; }
.xp-check__form h4,
.xp-option h4 { margin-top: 8px; }
.xp-check__grid {
  display: grid;
  gap: 10px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  margin: 0 0 14px;
}
.xp-field {
  display: grid;
  gap: 4px;
  font-size: var(--text-sm, 0.8125rem);
}
.xp-field span {
  font-weight: var(--weight-bold, 700);
  letter-spacing: var(--tracking-kicker, 0.06em);
