}
.xp-check__done { padding-top: 8px; }
.xp-cancel { margin-top: 12px; }
.xp-addons { display: grid; gap: 8px; }
.xp-addon {
  display: flex;
  gap: 10px;
  align-items: flex-start;
  padding: 10px 12px;
  border-radius: 14px;
  border: 1px solid var(--line, #e2e8f0);
