    display: inline-flex;
    align-items: center;
    gap: 6px;
    flex-shrink: 0;
    border: 1px solid var(--line, #e2e8f0);
    background: #fff;
    border-radius: 8px;
    padding: 7px 11px;
    font: inherit;
    font-weight: 700;
    color: var(--navy, #001438);
