    font-size: 0.6875rem;
    font-weight: 800;
    line-height: 1;
  }
  .xp-page--results .xp-filters-scrim {
    display: none;
    position: fixed;
    inset: 0;
    z-index: 69;
    background: rgba(0, 20, 56, 0.35);
  }
  .xp-page--results.xp-filters-open .xp-filters-scrim { display: block; }
  .xp-page--results .xp-filters {
    position: fixed;
    z-index: 70;
    inset: 0;
    display: flex;
    flex-direction: column;
    justify-content: flex-end;
    height: auto;
    max-height: none;
    background: transparent;
    border: 0;
    border-radius: 0;
    padding: 0;
    box-shadow: none;
    overflow: hidden;
    transform: translateY(110%);
    transition: transform 0.25s var(--ease, ease);
