    font-size: 1.25rem;
    line-height: 1;
    cursor: pointer;
  }
  .xp-page--results .xp-filters-done {
    width: 100%;
    margin-top: 8px;
    border: 0;
    border-radius: 12px;
    background: var(--navy, #001438);
    color: #fff;
    font: inherit;
    font-weight: 800;
    padding: 12px 16px;
    cursor: pointer;
  }
