  gap: 6px 10px;
  max-height: 1.25em;
}
.xp-card__body p {
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}
html[data-theme="dark"] .xp-card__cancel {
