}
html[data-theme="dark"] .xp-price__na {
  color: #94a3b8;
}
@media (max-width: 720px) {
  .xp-card__foot {
    align-items: flex-start;
    flex-direction: column;
    gap: 8px;
  }
  .xp-card__cta {
    align-self: flex-end;
  }
