.xp-inventory-note {
  width: min(100%, var(--xp-max));
  margin: 0 auto 8px;
  padding: 14px 18px;
  border-radius: 14px;
  border: 1px solid color-mix(in srgb, var(--accent, #f97211) 35%, var(--line, #e2e8f0));
  background: color-mix(in srgb, var(--accent, #f97211) 8%, var(--card, #fff));
  color: var(--ink, #0f172a);
  font-size: var(--text-sm, 0.8125rem);
  line-height: 1.5;
}
.xp-empty--inline {
  grid-column: 1 / -1;
  padding: 28px 20px;
  text-align: center;
  border: 1px dashed var(--line, #e2e8f0);
  border-radius: 18px;
  background: var(--card, #fff);
}
.xp-empty--inline p {
  margin: 0 0 12px;
  color: var(--muted, #64748b);
}
.xp-band {
  padding: clamp(56px, 7vw, 96px) 0;
  background: var(--bg, #fff);
  color: var(--ink, #0f172a);
}
.xp-wrap {
  width: min(1180px, calc(100% - 48px));
  margin: 0 auto;
}
.xp-band__lead {
  max-width: 640px;
  margin-bottom: clamp(24px, 3.5vw, 40px);
}
.xp-band__lead h2 {
  margin: 6px 0 0;
  font-size: clamp(1.75rem, 3vw, 2.375rem);
  line-height: 1.1;
  letter-spacing: var(--tracking-tight, -0.02em);
  font-weight: var(--weight-bold, 700);
  color: var(--ink, #0f172a);
}
.xp-cross {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 14px;
}
.xp-cross__card {
  position: relative;
  display: block;
  min-height: 220px;
  overflow: hidden;
  border-radius: 20px;
  color: #fff;
  text-decoration: none;
  isolation: isolate;
  background: var(--navy, #001438);
}
.xp-cross__card img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  z-index: -2;
  filter: saturate(0.88) contrast(1.05) brightness(0.9);
  transition: transform 0.7s cubic-bezier(0.2, 0.7, 0.2, 1);
}
.xp-cross__card:hover img { transform: scale(1.05); }
.xp-cross__shade {
  position: absolute;
  inset: 0;
  z-index: -1;
  background: linear-gradient(
    180deg,
    rgba(0, 8, 20, 0.28) 0%,
    rgba(0, 8, 20, 0.06) 22%,
    rgba(0, 6, 14, 0.52) 42%,
    rgba(0, 4, 10, 0.82) 62%,
    rgba(0, 2, 6, 0.94) 82%,
    rgba(0, 0, 0, 0.97) 100%
  );
}
.xp-cross__txt {
  position: absolute;
  left: 20px;
  right: 20px;
  bottom: 48px;
  display: flex;
  flex-direction: column;
  gap: 4px;
}
.xp-cross__txt strong {
  font-size: 1.5rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.xp-cross__txt span {
  font-size: var(--text-sm, 0.8125rem);
  color: rgba(255, 255, 255, 0.82);
  max-width: 36ch;
}
.xp-cross__go {
  position: absolute;
  left: 20px;
  bottom: 18px;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  font-size: var(--text-sm, 0.8125rem);
  font-weight: 700;
  color: #99f6e4;
}
.xp-cross__card:focus-visible {
  outline: 3px solid #0f6b6b;
  outline-offset: 3px;
}
.xp-faq {
  border-top: 1px solid var(--line, #e2e8f0);
}
.xp-faq__in {
  display: grid;
  grid-template-columns: 1fr 1.5fr;
  gap: clamp(24px, 5vw, 80px);
  align-items: start;
}
.xp-faq .xp-band__lead { margin-bottom: 0; }
.xp-faq__list { border-top: 1px solid var(--line, #e2e8f0); }
.xp-faq__item { border-bottom: 1px solid var(--line, #e2e8f0); }
.xp-faq__item summary {
  list-style: none;
  cursor: pointer;
  padding: 20px 36px 20px 0;
  position: relative;
  font-weight: var(--weight-semibold, 600);
  font-size: var(--text-lg, 1.0625rem);
  color: var(--ink, #0f172a);
}
.xp-faq__item summary::-webkit-details-marker { display: none; }
.xp-faq__item summary::after {
  content: "";
  position: absolute;
  right: 6px;
  top: 50%;
  width: 9px;
  height: 9px;
  border-right: 2px solid currentColor;
  border-bottom: 2px solid currentColor;
  transform: translateY(-70%) rotate(45deg);
  transition: transform 0.2s;
}
.xp-faq__item[open] summary::after {
  transform: translateY(-30%) rotate(-135deg);
}
.xp-faq__item p {
  margin: 0 0 20px;
  padding-right: 36px;
  color: var(--muted, #64748b);
  line-height: 1.6;
}
.xp-detail__panel {
  border-radius: 20px 20px 0 0;
  box-shadow: 0 -16px 48px rgba(0, 14, 36, 0.18);
}
.xp-page--results .xp-detail__panel {
  max-width: min(720px, 100%);
}
@media (max-width: 820px) {
  .xp-cross { grid-template-columns: 1fr; }
  .xp-faq__in { grid-template-columns: 1fr; }
  .xp-wrap { width: min(1180px, calc(100% - 28px)); }
  .xp-cross__card { min-height: 200px; }
}
html[data-theme="dark"] body.xp-page--results {
  background: var(--wash, #0b1220);
}
html[data-theme="dark"] .xp-band {
  background: var(--bg, #0b1220);
}
html[data-theme="dark"] .xp-inventory-note {
  background: color-mix(in srgb, var(--accent, #f97211) 14%, #0f172a);
  border-color: #44403c;
  color: var(--ink, #e2e8f0);
}
html[data-theme="dark"] .xp-empty--inline {
  background: var(--card, #0f172a);
  border-color: #334155;
}
html[data-theme="dark"] .xp-faq {
  border-top-color: var(--line, #1e293b);
}
html[data-theme="dark"] .xp-faq__list,
html[data-theme="dark"] .xp-faq__item {
  border-color: var(--line, #1e293b);
}
html[data-theme="dark"] .xp-faq__item summary {
  color: var(--ink, #e2e8f0);
}
html[data-theme="dark"] .xp-band__lead h2 {
  color: var(--ink, #e2e8f0);
}
@media (prefers-reduced-motion: reduce) {
  .xp-cross__card img { transition: none; }
  .xp-faq__item summary::after { transition: none; }
}

/* Full-page experience detail (/experience/{id}) — hotels parity */
a.xp-card {
  text-decoration: none;
  color: inherit;
  display: block;
}
.xp-page--detail .xp-detail-page {
  max-width: 1120px;
  margin: 0 auto;
  padding: 88px 20px 64px;
}
.xp-page--detail .xp-detail-page__nav {
  margin-bottom: 16px;
}
.xp-page--detail .xp-back-link {
  color: var(--muted, #64748b);
  text-decoration: none;
  font-weight: 600;
  font-size: 0.95rem;
}
.xp-page--detail .xp-back-link:hover {
  color: var(--ink, #0f172a);
}
.xp-page--detail .xp-detail-page__loading {
  margin: 24px 0;
  color: var(--muted, #64748b);
}
.xp-page--detail .xp-detail-page__error,
.xp-page--detail .empty-line--error {
  margin: 24px 0;
  padding: 20px 22px;
  border: 1px solid color-mix(in srgb, #dc2626 28%, #e2e8f0);
  background: color-mix(in srgb, #dc2626 8%, #fff);
  border-radius: 14px;
  color: var(--ink, #0f172a);
  line-height: 1.45;
}
.xp-page--detail .xp-detail-page__body {
  background: transparent;
  border-radius: 0;
  overflow: visible;
  border: 0;
}
.xp-page--detail .xp-detail__body {
  padding: 8px 4px 36px;
}
.xp-page--detail .xp-gallery {
  border-radius: 18px;
  overflow: hidden;
  border: 1px solid var(--line, #e2e8f0);
}
.xp-page--detail #xp-detail-title {
  margin: 8px 0 12px;
  font-size: clamp(1.6rem, 2.4vw, 2.15rem);
  line-height: 1.15;
}
.xp-page--detail .xp-detail__close {
  display: none !important;
}
body[data-detail-loading="1"] .xp-detail-page__body:empty + .xp-detail-page__loading,
body[data-detail-loading="1"] .xp-detail-page__loading {
  display: block;
}
html[data-theme="dark"] .xp-page--detail .xp-detail-page__body {
  background: var(--card, #0f172a);
  border-color: var(--line, #1e293b);
}
html[data-theme="dark"] .xp-page--detail .xp-detail-page__error,
html[data-theme="dark"] .xp-page--detail .empty-line--error {
  background: color-mix(in srgb, #dc2626 16%, #0f172a);
  border-color: #7f1d1d;
  color: var(--ink, #e2e8f0);
}

/* Experience detail — organized A→Z layout (main story + sticky reserve rail) */
.xp-detail__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(280px, 340px);
  gap: 28px 36px;
  align-items: start;
}
.xp-detail__main {
  min-width: 0;
  display: grid;
  gap: 26px;
}
.xp-detail__main > #xp-detail-title { margin-bottom: -12px; }
.xp-sec,
.xp-itin,
.xp-provider,
.xp-log,
.xp-reviews {
  padding-top: 4px;
}
.xp-detail__aside {
  min-width: 0;
}
.xp-detail__badges {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.xp-badge {
  display: inline-flex;
  align-items: center;
  min-height: 26px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(249, 114, 17, 0.12);
  color: #c2410c;
  font-size: 0.72rem;
  font-weight: 750;
  letter-spacing: 0.04em;
  text-transform: capitalize;
}
.xp-detail__body #xp-detail-title {
  margin: 0;
  letter-spacing: -0.03em;
}
.xp-detail__meta {
  margin-top: -8px;
}
.xp-facts {
  margin: 0;
}
.xp-sec h3,
.xp-itin h3,
.xp-log > h3,
.xp-reviews > h3 {
  margin: 0 0 12px;
  font-size: 1.05rem;
  font-weight: 750;
  letter-spacing: -0.02em;
  color: var(--navy, #001438);
}
.xp-sec + .xp-sec,
.xp-sec + .xp-itin,
.xp-itin + .xp-sec,
.xp-sec + .xp-log,
.xp-log + .xp-sec {
  margin-top: 0;
}
.xp-detail__lead {
  margin: 0;
  max-width: 62ch;
  color: var(--ink, #0f172a);
  font-size: 1rem;
  line-height: 1.6;
}
.xp-detail__full {
  margin: 12px 0 0;
  max-width: 62ch;
  color: var(--ink, #0f172a);
  font-size: 0.95rem;
  line-height: 1.6;
  white-space: pre-line;
}
.xp-more {
  margin-top: 10px;
}
.xp-more summary {
  cursor: pointer;
  color: var(--navy, #001438);
  font-size: 0.88rem;
  font-weight: 700;
  list-style: none;
}
.xp-more summary::-webkit-details-marker { display: none; }
.xp-more summary::after {
  content: " →";
  color: var(--accent, #f97211);
}
.xp-pills--quiet {
  margin: 0;
}
.xp-pills--quiet .xp-pill {
  background: var(--paper-2, #f8fafc);
  border-color: var(--line, #e2e8f0);
  color: var(--muted, #64748b);
  font-weight: 600;
}
.xp-pill-more {
  display: inline-flex;
  flex-wrap: wrap;
  gap: 8px;
  align-items: center;
}
.xp-pill-more summary {
  cursor: pointer;
  list-style: none;
  min-height: 28px;
  padding: 0 10px;
  border-radius: 999px;
  border: 1px dashed var(--line, #e2e8f0);
  color: var(--muted, #64748b);
  font-size: 0.75rem;
  font-weight: 700;
  display: inline-flex;
  align-items: center;
}
.xp-pill-more summary::-webkit-details-marker { display: none; }
.xp-pill-more[open] summary { display: none; }
.xp-bookrail {
  position: sticky;
  top: 88px;
  display: grid;
  gap: 0;
  padding: 0;
  border-radius: 20px;
  border: 1px solid var(--line, #e2e8f0);
  background: #fff;
  box-shadow: 0 16px 40px rgba(0, 20, 56, 0.08);
  overflow: hidden;
}
.xp-bookrail__hero {
  padding: 18px 18px 14px;
  border-bottom: 1px solid var(--line, #e2e8f0);
  background: linear-gradient(180deg, #fff 0%, var(--paper-2, #f8fafc) 100%);
}
.xp-bookrail__price {
  margin: 0;
  display: grid;
  gap: 2px;
}
.xp-bookrail__price span,
.xp-bookrail__price em {
  font-size: 0.72rem;
  font-weight: 650;
  color: var(--muted, #64748b);
  font-style: normal;
}
.xp-bookrail__price strong {
  font-size: 1.55rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--navy, #001438);
  line-height: 1.1;
}
.xp-bookrail__meta,
.xp-bookrail__cancel {
  margin: 0;
  font-size: 0.82rem;
  font-weight: 550;
  color: var(--muted, #64748b);
  line-height: 1.4;
}
.xp-bookrail .xp-check {
  margin: 0;
  padding: 16px 18px 18px;
  border: 0;
  border-radius: 0;
  background: transparent;
  box-shadow: none;
}
.xp-check__head--rail {
  margin-bottom: 14px;
  padding-right: 0;
}
.xp-check__head--rail .xp-check__lede {
  margin-top: 4px;
  font-size: var(--text-xs, 0.75rem);
}
.xp-bookrail .xp-detail__actions {
  margin: 0;
  padding: 12px 18px 16px;
  border-top: 1px solid var(--line, #e2e8f0);
  background: var(--paper-2, #f8fafc);
}
.xp-detail__actions--rail {
  justify-content: stretch;
}
.xp-detail__actions--rail .xp-btn {
  width: 100%;
  justify-content: center;
}
.xp-field--wide {
  grid-column: 1 / -1;
}
.xp-field textarea {
  min-height: 72px;
  border: 1px solid var(--line, #e2e8f0);
  border-radius: 12px;
  padding: 10px 12px;
  background: var(--card, #fff);
  color: var(--ink, #0f172a);
  font: inherit;
  resize: vertical;
}
.xp-btn--ghost {
  background: transparent;
  border: 1px solid var(--line, #e2e8f0);
  color: var(--navy, #001438);
}
.xp-voucher {
  display: grid;
  gap: 14px;
  padding: 4px 0 0;
}
.xp-voucher__head h4 {
  margin: 4px 0 0;
  font-size: 1.15rem;
  color: var(--navy, #001438);
}
.xp-voucher__kicker {
  margin: 0;
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent, #f97211);
}
.xp-voucher__note {
  margin: 6px 0 0;
  font-size: var(--text-xs, 0.75rem);
  color: var(--muted, #64748b);
}
.xp-voucher__grid {
  margin: 0;
  display: grid;
  gap: 10px 16px;
  grid-template-columns: repeat(2, minmax(0, 1fr));
}
.xp-voucher__grid div {
  margin: 0;
}
.xp-voucher__grid dt {
  margin: 0 0 2px;
  font-size: var(--text-2xs, 0.6875rem);
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: var(--muted, #64748b);
}
.xp-voucher__grid dd {
  margin: 0;
  font-size: var(--text-sm, 0.8125rem);
  color: var(--ink, #0f172a);
  line-height: 1.35;
}
.xp-voucher__wide {
  grid-column: 1 / -1;
}
.xp-voucher__cta,
.xp-voucher__tools {
  margin: 0;
}
@media (max-width: 640px) {
  .xp-voucher__grid {
    grid-template-columns: 1fr;
  }
}
.xp-reviews__loading { margin: 0; color: var(--muted, #64748b); }

@media (max-width: 960px) {
  .xp-detail__layout {
    grid-template-columns: 1fr;
  }
  .xp-bookrail {
    position: static;
  }
  .xp-detail__aside {
    order: -1;
  }
}

html[data-theme="dark"] .xp-badge {
  background: rgba(249, 114, 17, 0.18);
  color: #fdba74;
}
html[data-theme="dark"] .xp-bookrail {
  background: #101a2a;
  border-color: var(--line, #2a3b55);
  box-shadow: 0 12px 32px rgba(0, 0, 0, 0.28);
}
html[data-theme="dark"] .xp-bookrail__hero,
html[data-theme="dark"] .xp-bookrail .xp-detail__actions {
  background: #0c1422;
}
html[data-theme="dark"] .xp-field textarea {
  background: var(--card);
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .xp-bookrail__price strong,
html[data-theme="dark"] .xp-sec h3,
html[data-theme="dark"] .xp-itin h3,
html[data-theme="dark"] .xp-log > h3,
html[data-theme="dark"] .xp-reviews > h3 {
  color: var(--ink, #e8eef6);
}
html[data-theme="dark"] .xp-pills--quiet .xp-pill {
  background: #152033;
  border-color: var(--line, #2a3b55);
  color: var(--muted, #9aa8bc);
}
html[data-theme="dark"] .xp-detail__lead,
html[data-theme="dark"] .xp-detail__full {
  color: var(--ink, #e8eef6);
}

