response.body:
/* Homepage footer — shared so flights / other surfaces stay identical. */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}
.footer {
  color: #e8edf4;
  background: #001439;
  position: relative;
  margin-top: auto;
}
.footer::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  width: min(160px, 28%);
  height: 2px;
  transform: translateX(-50%);
  border-radius: 99px;
  background: var(--accent, #f97211);
  opacity: 0.9;
}
.footer__inner {
  max-width: 1440px;
  margin: 0 auto;
  padding: 56px 24px 26px;
  padding-bottom: max(26px, env(safe-area-inset-bottom));
}
.footer__main {
  display: grid;
  grid-template-columns: minmax(200px, 1.1fr) minmax(0, 1.4fr) minmax(250px, 0.95fr);
  gap: 36px 40px;
  align-items: start;
  padding-bottom: 36px;
  border-bottom: 1px solid rgba(232, 237, 244, 0.09);
}
.footer__brand {
  display: grid;
  gap: 12px;
  justify-items: start;
}
.footer__logoLink {
  display: inline-flex;
  text-decoration: none;
  margin-bottom: 2px;
}
.footer__logoImg {
  object-fit: contain;
  width: auto;
  max-width: 200px;
  height: 36px;
  transform: scaleX(1.22);
  transform-origin: left center;
}
.footer__tagline {
  margin: 0;
  max-width: 12ch;
  font-size: clamp(var(--text-2xl), 2.2vw, var(--text-3xl));
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1.08;
  color: #fff;
}
.footer__tagline em {
  color: var(--accent, #f97211);
  font-style: normal;
  font-weight: 800;
}
.footer__promise {
  margin: 2px 0 0;
  max-width: 30ch;
  font-size: var(--text-sm);
  font-weight: 500;
  line-height: 1.5;
  color: rgba(232, 237, 244, 0.52);
}
.footer__links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px 24px;
  padding-top: 4px;
}
.footer .footer__col {
  display: grid;
  gap: 8px;
  align-content: start;
  margin-left: 0;
}
.footer .footer__col .footer__col-link[aria-current="page"],
.footer .footer__col .footer__col-link:hover { color: #fff; }
.footer__col-title {
  margin: 0 0 4px;
  font-size: var(--text-2xs);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(232, 237, 244, 0.38);
}
.footer__col-link {
  color: rgba(255, 255, 255, 0.78);
  font-size: var(--text-base);
  font-weight: 600;
  line-height: 1.35;
  text-decoration: none;
  transition: color 0.15s;
  width: fit-content;
}
.footer__col-link:hover { color: #fff; }
.footer__aside {
  display: grid;
  gap: 20px;
  align-content: start;
  padding-top: 4px;
}
.footer__subscribe {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}
.footer__subscribeLabel {
  margin: 0;
  color: rgba(232, 237, 244, 0.38);
  font-size: var(--text-2xs);
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.footer__subscribeRow {
  display: flex;
  gap: 0;
  border: 1px solid rgba(232, 237, 244, 0.16);
  border-radius: 12px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.04);
  transition: border-color 0.15s;
}
.footer__subscribeRow:focus-within {
  border-color: rgba(249, 114, 17, 0.5);
}
.footer__subscribeRow input {
  flex: 1;
  min-width: 0;
  color: #fff;
  font: inherit;
  font-size: var(--text-base);
  font-weight: 500;
  background: transparent;
  border: 0;
  padding: 12px 14px;
  outline: none;
}
