/**
 * Vero CTA — calm Nuitee-style AI signal
 * Soft aurora glow + sparkles. Comfortable, not neon.
 */

.vero-cta {
  position: relative;
  z-index: 0;
  isolation: isolate;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 10px;
  min-height: 44px;
  padding: 0 16px 0 10px;
  border: 0;
  border-radius: 14px;
  background: #fff;
  color: #0f172a;
  font-family: inherit;
  font-size: 0.9rem;
  font-weight: 650;
  letter-spacing: -0.015em;
  line-height: 1.15;
  text-decoration: none;
  cursor: pointer;
  /* Soft multi-hue glow (Nuitee smart cards) — no spinning disco ring */
  box-shadow:
    0 0 0 1px rgba(249, 114, 17, 0.35),
    0 0 0 1px rgba(249, 114, 17, 0.12) inset,
    0 6px 20px rgba(249, 114, 17, 0.1),
    0 2px 10px rgba(249, 114, 17, 0.08),
    -4px 0 16px rgba(249, 114, 17, 0.12),
    4px 0 16px rgba(251, 146, 60, 0.1);
  transition:
    transform 0.18s cubic-bezier(0.22, 1, 0.36, 1),
    box-shadow 0.2s ease;
}

.vero-cta::before {
  content: "";
  position: absolute;
  inset: 0;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    125deg,
    #f97211 0%,
    #fb9a4d 35%,
    #fdba74 62%,
    #ffd9b3 100%
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  opacity: 0.85;
}

.vero-cta:hover {
  transform: translateY(-1px);
  box-shadow:
    0 0 0 1px rgba(249, 114, 17, 0.45),
    0 10px 26px rgba(249, 114, 17, 0.14),
    0 4px 14px rgba(249, 114, 17, 0.1),
    -6px 0 20px rgba(249, 114, 17, 0.14),
    6px 0 20px rgba(251, 146, 60, 0.12);
}

.vero-cta:focus-visible {
  outline: 2px solid #f97211;
  outline-offset: 3px;
}

.vero-cta:active {
  transform: translateY(0);
}

.vero-cta__face-wrap {
  position: relative;
  z-index: 1;
  width: 30px;
  height: 30px;
  flex-shrink: 0;
}

.vero-cta__face {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  object-fit: cover;
  display: block;
  background: #f1f5f9;
}

.vero-cta__spark {
  position: absolute;
  top: -3px;
  right: -5px;
  width: 13px;
  height: 13px;
  color: #f97211;
  pointer-events: none;
}

.vero-cta__spark svg {
  display: block;
  width: 13px;
  height: 13px;
}

.vero-cta__live,
.vero-cta__go {
  display: none;
}

.vero-cta__label {
  position: relative;
  z-index: 1;
  white-space: nowrap;
}

.vero-cta__text {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-width: 0;
  text-align: left;
  flex: 1;
}

.vero-cta__text strong {
  font-size: 0.95rem;
  font-weight: 650;
  letter-spacing: -0.02em;
  line-height: 1.2;
  color: #0f172a;
}

.vero-cta__text small {
  font-size: 0.75rem;
  font-weight: 450;
  letter-spacing: -0.01em;
  color: #64748b;
  line-height: 1.3;
}

.vero-cta--featured {
  width: 100%;
  justify-content: flex-start;
  min-height: 58px;
  padding: 12px 16px 12px 12px;
  border-radius: 16px;
  gap: 12px;
}

.vero-cta--featured .vero-cta__face-wrap {
  width: 38px;
  height: 38px;
}

.vero-cta--featured .vero-cta__face {
  width: 38px;
  height: 38px;
}

.vero-cta--featured .vero-cta__spark {
  width: 15px;
  height: 15px;
  top: -4px;
  right: -6px;
}

.vero-cta--featured .vero-cta__spark svg {
  width: 15px;
  height: 15px;
}

.vero-cta--compact {
  min-height: 40px;
  padding: 0 14px 0 8px;
  font-size: 0.86rem;
  gap: 8px;
  border-radius: 999px;
}

.vero-cta--compact .vero-cta__face-wrap {
  width: 24px;
  height: 24px;
}

.vero-cta--compact .vero-cta__face {
  width: 24px;
  height: 24px;
}

.vero-cta--compact .vero-cta__spark {
  width: 12px;
  height: 12px;
  top: -2px;
  right: -4px;
}

.vero-cta--compact .vero-cta__spark svg {
  width: 12px;
  height: 12px;
}

.vero-cta--form {
  flex-shrink: 0;
  min-width: 7.25rem;
}

/* Dark theme: the card follows the site surface tokens instead of staying a white slab. */
html[data-theme="dark"] .vero-cta {
  background: var(--paper-2, #152033);
  color: var(--ink, #e8eef6);
}

html[data-theme="dark"] .vero-cta__text strong {
  color: var(--ink, #e8eef6);
}

html[data-theme="dark"] .vero-cta__text small {
  color: var(--muted, #9aa8bc);
}

html[data-theme="dark"] .vero-cta__face {
  background: var(--card, #101a2a);
}

