/**
 * Itinero shared loading / skeleton — navy ink wash shimmer.
 * Link after theme.css on product shells; hotel WL reuses .skel-line / .skel-block.
 */
:root {
  --itin-skel-base: #e8edf3;
  --itin-skel-highlight: #f4f7fb;
  --itin-skel-radius: 8px;
}

html[data-theme="dark"] {
  --itin-skel-base: #132238;
  --itin-skel-highlight: #1c3048;
}

@keyframes itin-skel-shimmer {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

.itin-skel-shimmer {
  background: linear-gradient(
    90deg,
    var(--itin-skel-base) 0%,
    var(--itin-skel-highlight) 45%,
    var(--itin-skel-base) 90%
  );
  background-size: 200% 100%;
  animation: itin-skel-shimmer 1.15s ease-in-out infinite;
  border-radius: var(--itin-skel-radius);
}

/* Screen-reader-only status (no visible "Loading…" dump) */
.itin-sr-only {
  position: absolute !important;
  width: 1px !important;
  height: 1px !important;
  padding: 0 !important;
  margin: -1px !important;
  overflow: hidden !important;
  clip: rect(0, 0, 0, 0) !important;
  white-space: nowrap !important;
  border: 0 !important;
}

/* Experience / product detail first paint */
.itin-detail-skel {
  display: grid;
  gap: 24px;
  pointer-events: none;
  user-select: none;
}

.itin-detail-skel__gallery {
  display: grid;
  grid-template-columns: 1.6fr 1fr;
  gap: 8px;
  min-height: 280px;
  border-radius: 18px;
  overflow: hidden;
}

.itin-detail-skel__gallery-main {
  min-height: 280px;
  border-radius: 18px 0 0 18px;
}

.itin-detail-skel__gallery-side {
  display: grid;
  grid-template-rows: repeat(2, 1fr);
  gap: 8px;
}

.itin-detail-skel__gallery-side span {
  min-height: 0;
  border-radius: 8px;
}

.itin-detail-skel__layout {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 320px);
  gap: 28px 36px;
  align-items: start;
}

.itin-detail-skel__main {
  display: grid;
  gap: 14px;
}

.itin-detail-skel__rail {
  display: grid;
  gap: 12px;
  padding: 20px;
  border-radius: 16px;
  border: 1px solid var(--line, #e2e8f0);
  background: var(--card, #fff);
}

.itin-detail-skel__line {
  height: 12px;
  border-radius: 8px;
}

.itin-detail-skel__line--title {
  height: 28px;
  width: min(520px, 86%);
}

.itin-detail-skel__line--md {
  width: 72%;
}

.itin-detail-skel__line--sm {
  width: 48%;
}

.itin-detail-skel__line--btn {
  height: 44px;
  width: 100%;
  margin-top: 8px;
  border-radius: 12px;
}

/* Align xp results cards with shared shimmer */
.xp-skel {
  background: linear-gradient(
    90deg,
    var(--itin-skel-base) 25%,
    var(--itin-skel-highlight) 50%,
    var(--itin-skel-base) 75%
  );
  background-size: 200% 100%;
  animation: itin-skel-shimmer 1.15s ease-in-out infinite;
}

.hcard--skeleton {
  background: linear-gradient(
    90deg,
    var(--itin-skel-base) 0%,
    var(--itin-skel-highlight) 45%,
    var(--itin-skel-base) 90%
  );
  background-size: 200% 100%;
  animation: itin-skel-shimmer 1.15s ease-in-out infinite;
}

/* Hotel detail: skeleton visible under nav splash; hide plain status line */
body[data-detail-loading="1"] #detail-loading-status {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* Booking: skeleton grid only — no spinner row */
body[data-booking-loading="1"] .booking-skeleton .booking-skel-label {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

body[data-booking-loading="1"] .booking-skeleton .booking-skel-spinner {
  display: none !important;
}

/* Flights checkout skeleton (global classes on legacy checkout shell) */
.itin-checkout-skel {
  max-width: 960px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: grid;
  gap: 20px;
  pointer-events: none;
}

.itin-checkout-skel__hero .itin-skel-shimmer {
  height: 22px;
  width: 55%;
  margin-bottom: 10px;
}

.itin-checkout-skel__grid {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(260px, 320px);
  gap: 24px;
}

.itin-checkout-skel__card {
  padding: 20px;
  border-radius: 16px;
  border: 1px solid var(--line, #e2e8f0);
  background: var(--card, #fff);
  display: grid;
  gap: 12px;
}

@media (max-width: 820px) {
  .itin-detail-skel__gallery {
    grid-template-columns: 1fr;
  }
  .itin-detail-skel__gallery-main {
    border-radius: 18px;
    min-height: 200px;
  }
  .itin-detail-skel__gallery-side {
    display: none;
  }
  .itin-detail-skel__layout,
  .itin-checkout-skel__grid {
    grid-template-columns: 1fr;
  }
}

@media (prefers-reduced-motion: reduce) {
  .itin-skel-shimmer,
  .xp-skel,
  .hcard--skeleton {
    animation: none !important;
  }
}

