/* Itinero calendar: identical to the flight checkout date picker. */
.ic-float {
  --ic-ink: #0f172a;
  --ic-muted: #64748b;
  --ic-line: #e2e8f0;
  --ic-bg: #f6f7fb;
  --ic-card: #fff;
  --ic-brand: #f26a1b;
  --ic-brand-ink: #c2500c;
  --ic-brand-soft: #fff4ec;
}
html[data-theme="dark"] .ic-float {
  --ic-ink: #e6edf7;
  --ic-muted: #93a4bd;
  --ic-line: #2a3b55;
  --ic-bg: #070d16;
  --ic-card: #101a2a;
  --ic-brand-ink: #ff9a5c;
  --ic-brand-soft: #2a1a10;
}
/* Search-bar popovers share the search bar's dark navy surface. */
.dock-pop--cal,
.ic-float--bar {
  --ic-ink: #fff;
  --ic-muted: rgba(255, 255, 255, 0.55);
  --ic-line: rgba(255, 255, 255, 0.14);
  --ic-bg: rgba(255, 255, 255, 0.08);
  --ic-card: rgba(6, 14, 28, 0.94);
  --ic-brand: #f26a1b;
  --ic-brand-ink: #ff9a5c;
  --ic-brand-soft: rgba(255, 255, 255, 0.1);
}
.ic-float--bar {
  backdrop-filter: blur(24px) saturate(1.15);
  -webkit-backdrop-filter: blur(24px) saturate(1.15);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
}

.ic-float {
  position: fixed;
  z-index: 2147483000;
  width: 296px;
  max-width: calc(100vw - 16px);
  padding: 12px;
  border: 1px solid var(--ic-line);
  border-radius: 14px;
  background: var(--ic-card);
  box-shadow: 0 16px 40px rgba(15, 23, 42, 0.16);
  box-sizing: border-box;
}

/* Existing search-bar popovers keep their placement; only the look changes. */
.dock-pop--cal {
  width: 296px !important;
  min-width: 0;
  max-width: calc(100vw - 16px);
  padding: 12px;
  border: 1px solid var(--ic-line);
  border-radius: 14px;
  background: var(--ic-card);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
  box-sizing: border-box;
}

.ic {
  color: var(--ic-ink);
  font: inherit;
  text-align: left;
}
.ic button { font: inherit; }

.ic__head {
  display: grid;
  grid-template-columns: 32px minmax(0, 1fr) 76px 32px;
  gap: 6px;
  margin-bottom: 10px;
}
.ic__head button {
  min-width: 0;
  padding: 0 6px;
  height: 32px;
  border: 1px solid var(--ic-line);
  border-radius: 8px;
  background: var(--ic-card);
  color: var(--ic-ink);
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
}
.ic__head .ic__title { background: var(--ic-bg); }
.ic__head button:disabled { opacity: 0.35; cursor: not-allowed; }
.ic__head button:not(:disabled):hover { background: var(--ic-bg); }

.ic__grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
}
.ic__wd {
  padding: 4px 0;
  text-align: center;
  font-size: 11px;
  font-weight: 700;
  color: var(--ic-muted);
  text-transform: uppercase;
}
.ic__day {
  height: 34px;
  padding: 0;
  border: 0;
  border-radius: 8px;
  background: transparent;
  color: var(--ic-ink);
  font-size: 13px;
  font-weight: 400;
  cursor: pointer;
}
.ic__day:not(:disabled):hover { background: var(--ic-brand-soft); }
.ic__day:disabled { color: var(--ic-muted); opacity: 0.35; cursor: not-allowed; }
.ic__today { box-shadow: inset 0 0 0 1px var(--ic-line); font-weight: 700; }
.ic .ic__sel,
.ic .ic__sel:not(:disabled):hover { background: var(--ic-brand); color: #fff; font-weight: 700; }

.ic__pick {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 6px;
  min-height: 204px;
  align-content: start;
}
.ic__pick button {
  height: 44px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: var(--ic-ink);
  font-size: 13.5px;
  cursor: pointer;
}
.ic__pick button:not(:disabled):hover { background: var(--ic-brand-soft); }
.ic__pick button:disabled { opacity: 0.35; cursor: not-allowed; }

.ic__pager { display: flex; justify-content: space-between; margin-top: 8px; }
.ic__pager button,
.ic__foot button {
  border: 0;
  background: none;
  color: var(--ic-brand-ink);
  font-size: 13px;
  font-weight: 700;
  cursor: pointer;
}
.ic__pager button:disabled { opacity: 0.35; cursor: not-allowed; }
.ic__foot {
  display: flex;
  justify-content: flex-end;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid var(--ic-line);
}

