/* Homepage prototype v2: search-first, cinematic (local only) */
:root {
  --navy: #001438;
  --navy-mid: #0b2244;
  --accent: #f97211; /* logo saffron — CTAs only */
  --accent-hover: #e5670f;
  --ink: #0f172a;
  --muted: #64748b;
  --line: #e2e8f0;
  --wash: #f4f7fb;
  --select: rgba(0, 20, 56, 0.06);
  --font-sans: "Outfit", system-ui, -apple-system, "Segoe UI", sans-serif;
  --font: var(--font-sans);
  --ease: cubic-bezier(0.22, 1, 0.36, 1);
}

*,
*::before,
*::after { box-sizing: border-box; }
html {
  scroll-behavior: smooth;
  background: var(--wash);
}
html,
body {
  margin: 0;
  font-family: var(--font);
  color: var(--ink);
  background: var(--wash);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  overflow-x: clip;
}
img { display: block; max-width: 100%; }
a { color: inherit; text-decoration: none; }
button, input, select, textarea,
h1, h2, h3, h4, h5, h6,
p, span, small, strong, em, b, label, li {
  font-family: var(--font);
}
[hidden] { display: none !important; }

.skip {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
  z-index: 100;
  background: var(--navy);
  color: #fff;
  font-weight: 700;
}
.skip:focus,
.skip:focus-visible {
  position: fixed;
  left: 12px;
  top: 12px;
  width: auto;
  height: auto;
  margin: 0;
  padding: 10px 14px;
  overflow: visible;
  clip: auto;
  clip-path: none;
  white-space: normal;
  border-radius: 10px;
  outline: 2px solid #fff;
  outline-offset: 2px;
}

/* Top bar */
.top {
  position: fixed;
  inset: 0 0 auto 0;
  z-index: 50;
  transition: background 0.35s var(--ease), box-shadow 0.35s var(--ease);
}
.top.is-solid {
  background: rgba(0, 20, 56, 0.94);
  backdrop-filter: blur(14px);
  box-shadow: 0 10px 30px rgba(0, 20, 56, 0.2);
}
.top__inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 16px 24px;
  display: flex;
  align-items: center;
  gap: 32px;
}
.top__mark {
  display: inline-flex;
  align-items: center;
  flex-shrink: 0;
}
.top__mark img {
  height: 28px;
  width: auto;
  transform: scaleX(1.22);
  transform-origin: left center;
}
.top__nav {
  display: flex;
  gap: 18px;
  flex: 1;
  flex-wrap: wrap;
}
.top__nav a {
  color: rgba(255, 255, 255, 0.88);
  font-weight: 600;
  font-size: 0.9rem;
  white-space: nowrap;
}
.top__nav a:hover { color: #fff; }
.top__tools {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-left: auto;
  flex-shrink: 0;
  min-width: 0;
}
.top__icon {
  position: relative;
  width: 40px;
  height: 40px;
  min-width: 40px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  cursor: pointer;
  padding: 0;
  flex: 0 0 auto;
  transition: background 0.15s, border-color 0.15s;
}
.top__icon:hover,
.top__icon[aria-expanded="true"] {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.55);
}
.top__icon:focus-visible {
  outline: 2px solid var(--navy);
  outline-offset: 2px;
}
.top__dot {
  display: none; /* only show when live unread alerts exist */
  position: absolute;
  top: 9px;
  right: 10px;
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #fff;
  box-shadow: 0 0 0 2px rgba(0, 20, 56, 0.55);
}
.top__icon.has-alerts .top__dot {
  display: block;
}
.top__signin {
  color: #fff;
  font-weight: 700;
  font-size: 0.9rem;
  border: 1px solid rgba(255, 255, 255, 0.35);
  padding: 8px 16px;
  border-radius: 999px;
}
.top__signin:hover { background: rgba(255, 255, 255, 0.1); border-color: #fff; }
.top__account {
  position: relative;
}
.top__account-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  border: 1px solid rgba(255, 255, 255, 0.35);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  padding: 5px 12px 5px 5px;
  border-radius: 999px;
  cursor: pointer;
  font-family: var(--font);
  font-size: 0.88rem;
  font-weight: 700;
  transition: background 0.15s, border-color 0.15s;
}
.top__account-btn:hover,
.top__account-btn[aria-expanded="true"] {
  background: rgba(255, 255, 255, 0.12);
  border-color: #fff;
}
.top__avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: var(--accent);
  color: #fff;
  font-size: 0.78rem;
  font-weight: 800;
}
.top__account-menu {
  position: absolute;
  top: calc(100% + 8px);
  right: 0;
  width: 220px;
  background: #fff;
  color: var(--navy);
  border-radius: 14px;
  box-shadow: 0 18px 40px rgba(0, 20, 56, 0.2);
  border: 1px solid #e5ebf3;
  padding: 10px;
  z-index: 60;
}
.top__account-email {
  margin: 0 0 8px;
  padding: 6px 8px 10px;
  border-bottom: 1px solid #eef2f7;
  font-size: 0.8rem;
  font-weight: 600;
  color: var(--muted);
  word-break: break-all;
}
.top__account-menu a,
.top__account-menu button {
  display: block;
  width: 100%;
  text-align: left;
  border: 0;
  background: transparent;
  color: var(--navy);
  font-family: var(--font);
  font-size: 0.9rem;
  font-weight: 600;
  padding: 10px 8px;
  border-radius: 10px;
  cursor: pointer;
}
.top__account-menu a:hover,
.top__account-menu button:hover {
  background: #f4f7fb;
}

/* Notifications sheet + site menu drawer */
.sheet {
  position: fixed;
  inset: 0;
  z-index: 80;
  display: grid;
  place-items: start end;
  padding: 72px 20px 20px;
  background: rgba(0, 12, 28, 0.28);
}
.sheet[hidden] { display: none !important; }
.sheet__card {
  width: min(360px, calc(100vw - 40px));
  background: #fff;
  color: var(--navy);
  border-radius: 18px;
  box-shadow: 0 24px 60px rgba(0, 20, 56, 0.22);
  padding: 16px 16px 14px;
  animation: sheet-in 0.22s var(--ease);
}
@keyframes sheet-in {
  from { opacity: 0; transform: translateY(-8px); }
  to { opacity: 1; transform: none; }
}
.sheet__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  margin-bottom: 10px;
}
.sheet__head h2 {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.sheet__close {
  width: 34px;
  height: 34px;
  border: 0;
  border-radius: 50%;
  background: #eef2f7;
  color: var(--navy);
  font-size: 1.35rem;
  line-height: 1;
  cursor: pointer;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0;
}
.sheet__close svg { display: block; }
.sheet__close:hover { background: #e2e8f0; }
.sheet__list {
  list-style: none;
  margin: 0;
  padding: 0;
  display: grid;
  gap: 8px;
}
.sheet__list li {
  display: grid;
  gap: 2px;
  padding: 0;
  border-radius: 12px;
  background: #f6f8fb;
}
.sheet__list a {
  display: grid;
  gap: 2px;
  padding: 12px;
  border-radius: 12px;
  color: inherit;
  text-decoration: none;
}
.sheet__list a:hover {
  background: #eef2f7;
}
.sheet__list strong {
  font-size: 0.88rem;
  font-weight: 800;
}
.sheet__list span {
  font-size: 0.82rem;
  font-weight: 500;
  color: var(--muted);
  line-height: 1.4;
}
.sheet__empty {
  padding: 14px 12px;
  border-radius: 12px;
