  background: rgba(255, 255, 255, 0.06);
}
html[data-theme="dark"] .sheet__empty-title,
html.dark .sheet__empty-title,
body.theme-dark .sheet__empty-title {
  color: #f4f7fb;
}
.sheet__link {
  display: inline-flex;
  margin-top: 12px;
  font-size: 0.86rem;
  font-weight: 800;
  color: var(--navy);
}

.drawer {
  position: fixed;
  inset: 0;
  z-index: 90;
}
.drawer[hidden] { display: none !important; }
.drawer__scrim {
  position: absolute;
  inset: 0;
  border: 0;
  background: rgba(15, 23, 42, 0.35);
  cursor: pointer;
  backdrop-filter: blur(3px);
}
.drawer__panel {
  position: absolute;
  top: 0;
  right: 0;
  bottom: 0;
  width: min(360px, 94vw);
  background: #fbfcfd;
  color: #0f172a;
