  box-shadow: -20px 0 48px rgba(15, 23, 42, 0.12);
  display: flex;
  flex-direction: column;
  gap: 18px;
  animation: drawer-in 0.28s var(--ease);
  overflow-y: auto;
}
@keyframes drawer-in {
  from { transform: translateX(14px); opacity: 0.75; }
  to { transform: none; opacity: 1; }
}
.drawer__head {
  display: flex;
  align-items: center;
