}
.drawer__quick-b {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 40px;
  padding: 0 14px;
  background: transparent;
  color: #334155;
  border: 0;
  border-radius: 10px;
  font-size: 0.88rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
}
.drawer__quick-b:hover {
  color: #0f172a;
  background: rgba(15, 23, 42, 0.04);
}
.drawer__nav {
  display: flex;
  flex-direction: column;
  gap: 20px;
  flex: 1;
}
/* Flat sections — no stacked grey cards */
.drawer__group {
  display: flex;
  flex-direction: column;
  gap: 2px;
  padding: 0;
  background: transparent;
  border: 0;
}
.drawer__label {
  margin: 0 4px 6px;
  font-size: 0.68rem;
  font-weight: 600;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: #94a3b8;
}
.drawer__nav a,
.drawer__linkbtn {
  display: flex;
  align-items: center;
  gap: 12px;
  width: 100%;
  border: 0;
  background: transparent;
  padding: 10px 8px;
  border-radius: 12px;
  font-family: var(--font);
  font-size: 0.95rem;
  font-weight: 550;
  letter-spacing: -0.015em;
  color: #0f172a;
  text-align: left;
