}
.drawer__foot p {
  margin: 0;
  text-align: center;
  font-size: 0.74rem;
  font-weight: 450;
  color: #94a3b8;
  line-height: 1.4;
}
.drawer__signin {
  display: inline-flex;
  justify-content: center;
  align-items: center;
  width: 100%;
  border: 0;
  border-radius: 12px;
  background: #001438;
  color: #fff;
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.92rem;
  cursor: pointer;
