  border: 1px solid #d7deea;
}
.drawer__signin--ghost:hover {
  background: #f8fafc;
  border-color: #b8c4d6;
}
body.is-locked { overflow: hidden; }

/* Stage — photo fills the entire first viewport, edge to edge */
.stage {
  position: relative;
  min-height: 100vh;
  min-height: 100svh;
  min-height: 100dvh;
  display: grid;
  align-items: start;
  justify-items: center;
  color: #fff;
  overflow: clip;
  background: #0a1628; /* only shows while image loads */
}
.stage::before {
  /* Legibility veil only — no white wash, photo stays full-bleed */
  content: "";
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background:
    radial-gradient(ellipse 70% 55% at 50% 48%, rgba(0, 12, 32, 0.38), transparent 68%),
    linear-gradient(
      180deg,
      rgba(0, 18, 48, 0.5) 0%,
      rgba(0, 14, 36, 0.22) 42%,
      rgba(0, 12, 32, 0.28) 100%
    );
}
.stage::after { display: none; }
.stage__bg {
  position: absolute;
  inset: 0;
  z-index: 0;
}
.stage__bg img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  transform: scale(1.04);
  transition: opacity 0.9s var(--ease), transform 12s linear;
}
.stage.is-ready .stage__bg img {
  transform: scale(1.1);
}
.stage__shade {
  display: none;
}
.stage__body {
  position: relative;
  z-index: 2;
  width: min(920px, calc(100% - 40px));
  margin: 0 auto;
  /* Lands the search bar near mid-hero (old centered look) without mode jumps */
  padding: max(96px, calc(50vh - 108px)) 0 48px;
  text-align: center;
}
.stage__place {
  margin: 0 0 6px;
  font-family: var(--font);
  font-size: 0.78rem;
  font-weight: 600;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.88);
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.45);
  opacity: 0;
  transform: translateY(12px);
  animation: rise 0.85s var(--ease) 0.05s forwards;
}
.stage__line {
  margin: 0 0 8px;
  min-height: 1.3em;
  font-family: var(--font);
  font-size: clamp(1.25rem, 2.6vw, 1.65rem);
  font-weight: 600;
  letter-spacing: -0.02em;
  color: #fff;
  text-shadow: 0 2px 14px rgba(0, 0, 0, 0.55), 0 10px 32px rgba(0, 0, 0, 0.4);
  opacity: 0;
  transform: translateY(16px);
  animation: rise 0.85s var(--ease) 0.15s forwards;
}
/* Headings share the site face */
.shelf__head h2,
.vhop__title,
.invite__intro h2,
.drawer__brand h2,
.recent h2,
.trust,
.flight-spot__city,
.flight-ticket__codes {
  font-family: var(--font);
}
@keyframes rise {
  to { opacity: 1; transform: none; }
}

/* Search dock: light glass strip (not a heavy panel) */
.dock {
  margin-top: 28px;
  text-align: left;
  color: #fff;
  background: transparent;
  border: 0;
  border-radius: 0;
  padding: 0;
  box-shadow: none;
  backdrop-filter: none;
  -webkit-backdrop-filter: none;
  opacity: 0;
  transform: translateY(16px);
  animation: dock-in 0.85s var(--ease) 0.35s forwards;
}
@keyframes dock-in {
  to { opacity: 1; transform: none; }
}
.dock__toolbar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px 20px;
  flex-wrap: wrap;
  padding: 0 2px 12px;
}
.dock__modes {
  display: inline-flex;
  gap: 2px;
}
.dock__mode {
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.82);
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.86rem;
  padding: 7px 14px;
  border-radius: 999px;
  cursor: pointer;
  text-shadow: 0 1px 10px rgba(0, 0, 0, 0.55);
  transition: color 0.15s, background 0.15s;
}
.dock__mode:hover { color: #fff; background: rgba(0, 0, 0, 0.22); }
.dock__mode.is-on {
  background: rgba(0, 0, 0, 0.42);
  color: #fff;
  text-shadow: none;
}
.dock__mode--ai {
  position: relative;
  margin-left: 4px;
  padding-left: 16px;
}
.dock__mode--ai::before {
  content: "";
  position: absolute;
  left: 4px;
  top: 18%;
  bottom: 18%;
  width: 1px;
  background: rgba(255, 255, 255, 0.28);
}
.dock__mode__label {
  display: inline-block;
}
.dock__mode--ai:not(.is-on) .dock__mode__label {
  background: linear-gradient(125deg, #ffe8d4 0%, #fdba74 38%, #fb9a4d 72%, #f97211 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
  text-shadow: none;
}
.dock__mode--ai:not(.is-on)::after {
  content: "";
  position: absolute;
  left: 16px;
  right: 12px;
  bottom: 5px;
  height: 2px;
  border-radius: 2px;
  background: linear-gradient(90deg, #f97211, #fb9a4d, #fdba74, #ffd9b3);
  opacity: 0.72;
  pointer-events: none;
}
.dock__mode--ai.is-on {
  box-shadow:
    0 0 0 1px rgba(249, 114, 17, 0.38),
    inset 0 0 0 1px rgba(255, 220, 190, 0.12);
}
.dock__mode--ai.is-on .dock__mode__label {
  background: linear-gradient(125deg, #fff4eb 0%, #fdba74 45%, #fb9a4d 100%);
  -webkit-background-clip: text;
  background-clip: text;
  color: transparent;
}
.dock__trip {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 3px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(0, 8, 22, 0.45);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
}
.dock__trip[hidden] { display: none !important; }
.dock__trip-btn {
  border: 0;
  background: transparent;
  color: rgba(255, 255, 255, 0.72);
  font-family: var(--font);
  font-weight: 600;
  font-size: 0.78rem;
  padding: 6px 12px;
  border-radius: 999px;
  cursor: pointer;
  white-space: nowrap;
  transition: color 0.15s, background 0.15s;
}
.dock__trip-btn:hover { color: #fff; }
.dock__trip-btn.is-on {
  background: rgba(255, 255, 255, 0.14);
  color: #fff;
  font-weight: 700;
  box-shadow: 0 1px 0 rgba(255, 255, 255, 0.08) inset;
}
.dock__form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: stretch;
  padding: 6px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.28);
  background: rgba(0, 10, 28, 0.72);
  backdrop-filter: blur(22px) saturate(1.2);
  -webkit-backdrop-filter: blur(22px) saturate(1.2);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.12) inset,
    0 14px 40px rgba(0, 0, 0, 0.35);
}
.dock.is-multi .dock__form {
  border-radius: 22px;
  grid-template-columns: 1fr;
  gap: 0;
}
.dock.is-multi .dock__go {
  margin: 0 6px 6px;
  min-height: 46px;
  border-radius: 14px;
}
.dock__fields {
  display: grid;
  grid-template-columns: 1fr 1fr 1.05fr 1.25fr;
  gap: 0;
  min-width: 0;
  border: 0;
  border-radius: 0;
  background: transparent;
  overflow: visible;
}
.dock__fields[data-trip="round"] {
  grid-template-columns: 0.95fr 0.95fr 1fr 1fr 1.15fr;
}
.dock__fields[data-trip="multi"] {
  grid-template-columns: 1fr 1fr 1.1fr 1.2fr;
}
.cell--return[hidden] { display: none !important; }
.dock__multi {
  padding: 0 6px 6px;
}
.dock__multi[hidden] { display: none !important; }
.dock__multi-label {
  margin: 0;
  padding: 8px 12px 4px;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
}
.dock__fields--multi {
  grid-template-columns: 1fr 1fr 1.2fr;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.08);
}
.dock__fields--multi .cell:last-child { border-right: 0; }
.cell {
  display: grid;
  gap: 2px;
  padding: 9px 14px;
  background: transparent;
  border-right: 1px solid rgba(255, 255, 255, 0.18);
  cursor: text;
  min-width: 0;
  transition: background 0.15s;
  border-radius: 999px;
}
.cell:hover,
.cell:focus-within {
  background: rgba(255, 255, 255, 0.1);
}
.cell:last-child { border-right: 0; }
.cell span {
  font-family: var(--font);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.72);
}
.cell input {
  border: 0;
  outline: none;
  background: transparent;
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.95rem;
  color: #fff;
  width: 100%;
  padding: 0;
  text-transform: uppercase;
  color-scheme: dark;
  line-height: 1.25;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
}
.cell input::placeholder {
  text-transform: none;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.5);
}
.cell input[type="date"]::-webkit-calendar-picker-indicator {
  filter: invert(1);
  opacity: 0.55;
  cursor: pointer;
}
.cell--suggest input { text-transform: uppercase; }
.cell--suggest input[data-suggest="city"] { text-transform: none; }
.cell__face {
  border: 0;
  outline: none;
  background: transparent;
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.95rem;
  color: #fff;
  width: 100%;
  padding: 0;
  margin: 0;
  text-align: left;
  cursor: pointer;
  line-height: 1.25;
  text-shadow: 0 1px 2px rgba(0, 0, 0, 0.25);
}
.cell__face:focus-visible {
  outline: 2px solid rgba(255, 255, 255, 0.35);
  outline-offset: 2px;
  border-radius: 4px;
}
.cell--wide { grid-column: span 1; }
.cell--full { grid-column: 1 / -1; border-right: 0; }
.cell--full input { text-transform: none; }

/* Glass pickers: suggest / calendar / travellers */
.dock-pop {
  position: fixed;
  z-index: 80;
  min-width: min(300px, calc(100vw - 32px));
  max-width: min(360px, calc(100vw - 24px));
  border-radius: 14px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background: rgba(6, 14, 28, 0.94);
  backdrop-filter: blur(24px) saturate(1.15);
  -webkit-backdrop-filter: blur(24px) saturate(1.15);
  box-shadow: 0 18px 48px rgba(0, 0, 0, 0.45);
  overflow: hidden;
  animation: dock-pop-in 0.18s var(--ease) both;
  text-align: left;
}
.dock-pop[hidden] { display: none !important; }
.dock-pop--cal {
  min-width: min(320px, calc(100vw - 24px));
  max-width: min(340px, calc(100vw - 24px));
}
@keyframes dock-pop-in {
  from { opacity: 0; transform: translateY(6px); }
  to { opacity: 1; transform: none; }
}
.dock-pop__head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
  padding: 12px 14px 8px;
}
.dock-pop__title {
  margin: 0;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.42);
}
.dock-pop__cal {
  padding: 14px 12px 12px;
}
.dock-pop__cal-top {
  display: grid;
  gap: 4px;
  padding: 0 4px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
  margin-bottom: 12px;
}
.dock-pop__picked {
  margin: 0;
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #fff;
  line-height: 1.25;
}
.dock-pop__quick {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  padding: 0 2px 12px;
}
.dock-pop__chip {
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.88);
  font-family: var(--font);
  font-size: 0.74rem;
  font-weight: 600;
  padding: 7px 11px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.dock-pop__chip:hover {
  background: rgba(255, 255, 255, 0.1);
  border-color: rgba(255, 255, 255, 0.28);
}
.dock-pop__chip.is-on {
  background: rgba(249, 114, 17, 0.18);
  border-color: rgba(249, 114, 17, 0.5);
  color: #fff;
}
.dock-pop__head--cal {
  padding: 0 2px 10px;
  justify-content: space-between;
}
.dock-pop__navbtn {
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 10px;
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-size: 1.2rem;
  line-height: 1;
  cursor: pointer;
  display: grid;
  place-items: center;
  transition: background 0.15s;
  flex-shrink: 0;
}
.dock-pop__navbtn:hover:not(:disabled) { background: rgba(255, 255, 255, 0.16); }
.dock-pop__navbtn:disabled {
  opacity: 0.28;
  cursor: not-allowed;
}
.dock-pop__month {
  margin: 0;
  font-size: 0.95rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  color: #fff;
  text-align: center;
  flex: 1;
}
.dock-pop__week {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 2px;
  padding: 0 2px 4px;
}
.dock-pop__week span {
  text-align: center;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.38);
  padding: 6px 0;
}
.dock-pop__grid {
  display: grid;
  grid-template-columns: repeat(7, 1fr);
  gap: 3px;
  padding: 0 2px;
}
.dock-pop__day-spacer { min-height: 40px; }
.dock-pop__day {
  min-height: 40px;
  border: 0;
  border-radius: 10px;
  background: transparent;
  color: rgba(255, 255, 255, 0.9);
  font-family: var(--font);
  font-size: 0.88rem;
  font-weight: 600;
  cursor: pointer;
  transition: background 0.12s, color 0.12s;
}
.dock-pop__day:hover:not(:disabled) { background: rgba(255, 255, 255, 0.12); }
.dock-pop__day.is-today:not(.is-on) {
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.35);
  font-weight: 700;
}
.dock-pop__day.is-on {
  background: var(--accent);
  color: #fff;
  font-weight: 800;
}
.dock-pop__day:disabled {
  opacity: 0.22;
  cursor: not-allowed;
}
.dock-pop__list {
  list-style: none;
  margin: 0;
  padding: 4px 0;
  max-height: min(300px, 48vh);
  overflow-y: auto;
}
.dock-pop__list li + li .dock-pop__opt {
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}
.dock-pop__opt {
  width: 100%;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 14px;
  text-align: left;
  border: 0;
  border-radius: 0;
  background: transparent;
  color: #fff;
  font-family: var(--font);
  padding: 11px 16px;
  cursor: pointer;
  transition: background 0.12s;
  position: relative;
}
.dock-pop__opt:hover,
.dock-pop__opt.is-active {
  background: rgba(255, 255, 255, 0.06);
}
.dock-pop__opt.is-active::before {
  content: "";
  position: absolute;
  left: 0;
  top: 8px;
  bottom: 8px;
  width: 2px;
  border-radius: 99px;
  background: var(--accent);
}
.dock-pop__copy {
  display: grid;
  gap: 2px;
  min-width: 0;
}
.dock-pop__city {
  font-size: 0.9rem;
  font-weight: 600;
  letter-spacing: -0.01em;
  line-height: 1.25;
}
.dock-pop__meta {
  font-size: 0.72rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.42);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.dock-pop__code {
  flex-shrink: 0;
  font-size: 0.78rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  color: rgba(255, 255, 255, 0.55);
  font-variant-numeric: tabular-nums;
}
.dock-pop__opt:hover .dock-pop__code,
.dock-pop__opt.is-active .dock-pop__code {
  color: rgba(255, 255, 255, 0.85);
}
.dock-pop__empty {
  margin: 0;
  padding: 22px 16px;
  text-align: center;
  font-size: 0.84rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.45);
}
.dock-pop__pax {
  padding: 8px 14px 14px;
  display: grid;
  gap: 12px;
}
.dock-pop__row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}
.dock-pop__row-label {
  display: grid;
  gap: 2px;
}
.dock-pop__row-label strong {
  font-size: 0.9rem;
  font-weight: 700;
  color: #fff;
}
.dock-pop__row-label span {
  font-size: 0.74rem;
  font-weight: 500;
  color: rgba(255, 255, 255, 0.48);
}
.dock-pop__step {
  display: inline-flex;
  align-items: center;
  gap: 10px;
}
.dock-pop__step button {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background: rgba(255, 255, 255, 0.06);
  color: #fff;
  font-size: 1.1rem;
  font-weight: 600;
  cursor: pointer;
  line-height: 1;
  transition: background 0.12s, border-color 0.12s;
}
.dock-pop__step button:hover:not(:disabled) {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.4);
}
.dock-pop__step button:disabled { opacity: 0.3; cursor: not-allowed; }
.dock-pop__step b {
  min-width: 1.2ch;
  text-align: center;
  font-size: 0.95rem;
  font-weight: 800;
  color: #fff;
}
.dock-pop__cabins {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.dock-pop__cabins button {
  border: 1px solid rgba(255, 255, 255, 0.16);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(255, 255, 255, 0.85);
  font-family: var(--font);
  font-size: 0.78rem;
  font-weight: 700;
  padding: 8px 12px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.12s, border-color 0.12s, color 0.12s;
}
.dock-pop__cabins button.is-on {
  background: rgba(249, 114, 17, 0.2);
  border-color: rgba(249, 114, 17, 0.55);
  color: #fff;
}
.dock-pop__done {
  width: 100%;
  border: 0;
  border-radius: 12px;
  background: var(--accent);
  color: #fff;
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.9rem;
  padding: 12px;
  cursor: pointer;
  transition: background 0.15s;
}
.dock-pop__done:hover { background: var(--accent-hover); }
.dock__go {
  border: 0;
  border-radius: 999px;
  background: var(--accent);
  color: #fff;
  font-family: var(--font);
  font-weight: 700;
  font-size: 0.9rem;
  padding: 0 22px;
  cursor: pointer;
  min-width: 128px;
  height: 100%;
  min-height: 44px;
  box-shadow: none;
  transition: background 0.15s, transform 0.15s;
}
.dock__go:hover { background: var(--accent-hover); }
.dock__go:active { transform: scale(0.98); }

/* Ask Vero: compact chat panel (fits hero without clipping composer) */
.dock.is-chat .dock__form { display: none; }
.dock.is-chat .dock__toolbar { padding-bottom: 8px; justify-content: center; }
.dock.is-chat .dock__trip { display: none !important; }
.dock.is-chat {
  width: min(400px, 100%);
  margin-left: auto;
  margin-right: auto;
}
.vero-chat {
  text-align: left;
  border-radius: 20px;
  border: 1px solid rgba(255, 255, 255, 0.22);
  background:
    linear-gradient(165deg, rgba(255, 255, 255, 0.14) 0%, transparent 32%),
    rgba(0, 12, 32, 0.82);
  backdrop-filter: blur(28px) saturate(1.25);
  -webkit-backdrop-filter: blur(28px) saturate(1.25);
  box-shadow:
    0 1px 0 rgba(255, 255, 255, 0.16) inset,
    0 18px 40px rgba(0, 0, 0, 0.4);
  overflow: hidden;
  animation: chat-in 0.5s var(--ease) both;
  display: flex;
  flex-direction: column;
  max-height: min(420px, calc(100vh - 220px));
  max-height: min(420px, calc(100dvh - 220px));
}
.vero-chat[hidden] { display: none !important; }
@keyframes chat-in {
  from { opacity: 0; transform: translateY(16px) scale(0.97); }
  to { opacity: 1; transform: none; }
}
.vero-chat__head {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 12px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(0, 0, 0, 0.18);
  flex-shrink: 0;
}
.vero-chat__avatar {
  position: relative;
  width: 34px;
  height: 34px;
  border-radius: 50%;
  padding: 2px;
  background: linear-gradient(135deg, rgba(255, 255, 255, 0.55), rgba(255, 255, 255, 0.18));
  flex-shrink: 0;
}
.vero-chat__avatar img {
  width: 100%;
  height: 100%;
  border-radius: 50%;
  object-fit: cover;
  background: #0a2548;
}
.vero-chat__who { min-width: 0; }
.vero-chat__who strong {
  display: block;
  font-size: 0.92rem;
  font-weight: 800;
  color: #fff;
  letter-spacing: -0.02em;
}
.vero-chat__live {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  margin-top: 1px;
  font-size: 0.7rem;
  font-weight: 600;
  color: rgba(167, 243, 208, 0.95);
}
.vero-chat__live::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #4ade80;
  animation: live-dot 1.8s var(--ease) infinite;
}
@keyframes live-dot {
  0%, 100% { box-shadow: 0 0 0 0 rgba(74, 222, 128, 0.45); }
  50% { box-shadow: 0 0 0 6px rgba(74, 222, 128, 0); }
}
.vero-chat__thread {
  position: relative;
  flex: 1 1 auto;
  min-height: 0;
  height: auto;
  max-height: min(148px, 20vh);
  overflow-y: auto;
  padding: 10px 12px 8px;
  display: flex;
  flex-direction: column;
  gap: 8px;
  scroll-behavior: smooth;
  -webkit-overflow-scrolling: touch;
  background:
    radial-gradient(ellipse 90% 55% at 15% 0%, rgba(140, 175, 220, 0.1), transparent 55%),
    rgba(0, 8, 24, 0.2);
}
.vero-chat__thread::before {
  content: "";
  position: sticky;
  top: 0;
  display: block;
  height: 8px;
  margin: -10px -12px 0;
  background: linear-gradient(180deg, rgba(0, 14, 36, 0.55), transparent);
  pointer-events: none;
  z-index: 1;
}
.vero-chat__intro {
  display: grid;
  justify-items: center;
  gap: 6px;
  text-align: center;
  padding: 6px 8px 2px;
  animation: vc-pop 0.5s var(--ease) both;
}
.vero-chat__intro.is-gone { display: none; }
.vero-chat__intro img {
  display: none; /* head already shows Vero; keep panel compact */
}
.vero-chat__intro p {
  margin: 0;
  max-width: 32ch;
  font-size: 0.84rem;
  font-weight: 600;
  line-height: 1.35;
  color: rgba(255, 255, 255, 0.88);
}
.vc-msg {
  display: flex;
  gap: 8px;
  align-items: flex-end;
  max-width: 88%;
  animation: vc-pop 0.4s var(--ease) both;
}
@keyframes vc-pop {
  from { opacity: 0; transform: translateY(10px) scale(0.98); }
  to { opacity: 1; transform: none; }
}
.vc-msg--vero { align-self: flex-start; }
.vc-msg--you {
  align-self: flex-end;
  flex-direction: row-reverse;
}
.vc-msg__face {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  flex-shrink: 0;
  box-shadow: 0 2px 8px rgba(0, 0, 0, 0.2);
}
.vc-msg__col { display: grid; gap: 6px; min-width: 0; }
.vc-msg__bubble {
  padding: 11px 14px;
  border-radius: 18px;
  font-size: 0.9rem;
  font-weight: 500;
  line-height: 1.45;
  color: #fff;
  word-wrap: break-word;
}
.vc-msg--vero .vc-msg__bubble {
  background: rgba(255, 255, 255, 0.12);
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-bottom-left-radius: 6px;
}
.vc-msg--you .vc-msg__bubble {
  background: rgba(255, 255, 255, 0.92);
  color: var(--navy);
  border-bottom-right-radius: 6px;
  font-weight: 600;
  box-shadow: 0 6px 18px rgba(0, 0, 0, 0.18);
}
.vc-msg__actions {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
}
.vc-msg__actions a,
.vc-msg__actions button {
  display: inline-flex;
  align-items: center;
  border: 0;
  border-radius: 999px;
  padding: 8px 12px;
  font-family: var(--font);
  font-size: 0.78rem;
  font-weight: 700;
  cursor: pointer;
  text-decoration: none;
  transition: transform 0.15s, filter 0.15s;
}
.vc-msg__actions a:active,
.vc-msg__actions button:active { transform: scale(0.97); }
.vc-act--primary {
  background: #fff;
  color: var(--navy);
}
.vc-act--primary:hover { filter: brightness(0.96); }
.vc-act--ghost {
  background: rgba(255, 255, 255, 0.1);
  color: #fff;
  border: 1px solid rgba(255, 255, 255, 0.2) !important;
}
.vc-msg--typing .vc-msg__bubble {
  display: inline-flex;
  gap: 5px;
  align-items: center;
  min-width: 56px;
  padding: 14px 16px;
}
.vc-msg--typing i {
  width: 6px;
  height: 6px;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.75);
  animation: vc-dot 1s ease infinite;
}
.vc-msg--typing i:nth-child(2) { animation-delay: 0.15s; }
.vc-msg--typing i:nth-child(3) { animation-delay: 0.3s; }
@keyframes vc-dot {
  0%, 80%, 100% { opacity: 0.35; transform: translateY(0); }
  40% { opacity: 1; transform: translateY(-3px); }
}
.vero-chat__suggest {
  padding: 0 12px 8px;
  flex-shrink: 0;
  transition: opacity 0.3s, max-height 0.35s var(--ease);
}
.vero-chat__suggest.is-dim { opacity: 0.55; }
.vero-chat__suggest.is-gone {
  display: none;
}
.vero-chat__suggest-label {
  margin: 0 0 6px;
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.45);
}
.vero-chat__chips {
  display: flex;
  flex-wrap: nowrap;
  gap: 6px;
  overflow-x: auto;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.vero-chat__chips::-webkit-scrollbar { display: none; }
.vero-chat__chips button {
  flex: 0 0 auto;
  border: 1px solid rgba(255, 255, 255, 0.2);
  background: rgba(255, 255, 255, 0.07);
  color: rgba(255, 255, 255, 0.92);
  font-family: var(--font);
  font-size: 0.74rem;
  font-weight: 600;
  padding: 6px 10px;
  border-radius: 999px;
  cursor: pointer;
  transition: background 0.15s, border-color 0.15s, transform 0.15s;
}
.vero-chat__chips button:hover {
  background: rgba(255, 255, 255, 0.14);
  border-color: rgba(255, 255, 255, 0.4);
  transform: translateY(-1px);
}
.vero-chat__composer {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 8px 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.1);
  background: rgba(0, 0, 0, 0.28);
  flex-shrink: 0;
}
.vero-chat__composer input {
  flex: 1;
  min-width: 0;
  border: 1px solid rgba(255, 255, 255, 0.14);
  background: rgba(255, 255, 255, 0.08);
  color: #fff;
  font-family: var(--font);
  font-weight: 600;
  font-size: 0.86rem;
  padding: 10px 14px;
  border-radius: 999px;
  outline: none;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.vero-chat__composer input::placeholder {
  color: rgba(255, 255, 255, 0.38);
  font-weight: 500;
}
.vero-chat__composer input:focus {
  border-color: rgba(255, 255, 255, 0.45);
  background: rgba(255, 255, 255, 0.11);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.08);
}
.vero-chat__send {
  width: 40px;
  height: 40px;
  border: 0;
  border-radius: 50%;
  background: var(--accent);
  color: #fff;
  cursor: pointer;
  display: grid;
  place-items: center;
  flex-shrink: 0;
  transition: background 0.15s, transform 0.15s, opacity 0.15s;
}
.vero-chat__send:hover:not(:disabled) { background: var(--accent-hover); }
.vero-chat__send:active:not(:disabled) { transform: scale(0.96); }
.vero-chat__send:disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

.sr-only {
  position: absolute;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0, 0, 0, 0);
  white-space: nowrap; border: 0;
}

/* Scroll reveals */
.fx,
.fx-scale,
.place {
  opacity: 0;
  transform: translateY(28px);
  transition:
    opacity 0.85s var(--ease),
    transform 0.85s var(--ease);
  transition-delay: calc(var(--d, 0) * 0.1s);
}
.fx-scale {
  transform: scale(1.04);
}
.fx.is-in,
.place.is-in {
  opacity: 1;
  transform: none;
}
.fx-scale.is-in {
  opacity: 1;
  transform: scale(1);
}



/* Below fold: trust, recent, shelves, Vero */

.trust {
  background: transparent;
  border-bottom: 0;
}
.trust__row {
  list-style: none;
  margin: 0 auto;
  padding: 16px 24px;
  max-width: 1120px;
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px 20px;
}
.trust__row li { display: grid; gap: 2px; min-width: 0; }
.trust__row strong {
  font-size: 0.86rem;
  font-weight: 800;
  color: var(--navy);
}
.trust__row span {
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--muted);
  line-height: 1.3;
}

.recent {
  background: var(--wash);
  padding: 36px 0 20px;
  border-bottom: 1px solid rgba(0, 20, 56, 0.05);
}
.recent[hidden] { display: none !important; }
.recent__shelf { margin-bottom: 0; }
.recent__head {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 16px;
}
.recent__intro { min-width: 0; }
.recent__eyebrow {
  margin: 0 0 4px;
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #7b8ba3;
}
.recent__head h2 {
  margin: 0;
  font-size: clamp(1.28rem, 2.1vw, 1.5rem);
  font-weight: 750;
  letter-spacing: -0.03em;
  color: var(--navy);
}
.recent__clear {
  border: 1px solid rgba(0, 20, 56, 0.1);
  background: transparent;
  color: #64748b;
  font-family: var(--font);
  font-size: 0.78rem;
  font-weight: 600;
  padding: 8px 12px;
  border-radius: 999px;
  cursor: pointer;
  flex-shrink: 0;
  transition: color 0.15s, border-color 0.15s, background 0.15s;
}
.recent__clear:hover {
  color: var(--navy);
  border-color: rgba(0, 20, 56, 0.2);
  background: #fff;
}
.recent__track {
  position: relative;
  padding: 0 44px;
}
.recent__row {
  display: flex;
  flex-wrap: nowrap;
  gap: 14px;
  overflow-x: auto;
  padding: 6px 2px 14px;
  scroll-snap-type: x mandatory;
  scrollbar-width: none;
  -webkit-overflow-scrolling: touch;
}
.recent__row::-webkit-scrollbar { display: none; }
.recent__nav {
  position: absolute;
  top: 50%;
  z-index: 3;
  width: 36px;
  height: 36px;
  margin-top: -24px;
  border: 1px solid rgba(0, 20, 56, 0.1);
  border-radius: 50%;
  background: #fff;
  color: var(--navy);
  display: grid;
  place-items: center;
  cursor: pointer;
  box-shadow: 0 6px 18px rgba(0, 20, 56, 0.08);
  transition: background 0.15s, border-color 0.15s, transform 0.15s;
}
.recent__nav:hover {
  border-color: rgba(0, 20, 56, 0.22);
  transform: scale(1.04);
}
.recent__nav[hidden] { display: none !important; }
.recent__nav--prev { left: 0; }
.recent__nav--next { right: 0; }
.recent__track::before,
.recent__track::after {
  content: none;
}
.recent__card {
  flex: 0 0 auto;
  scroll-snap-align: start;
  display: grid;
  grid-template-rows: auto 1fr;
  gap: 0;
  width: min(220px, 70vw);
  padding: 0;
  border: 1px solid rgba(0, 20, 56, 0.08);
  border-radius: 18px;
  background: #fff;
  color: var(--navy);
  font-family: var(--font);
  text-align: left;
  cursor: pointer;
  overflow: hidden;
  box-shadow: 0 1px 2px rgba(15, 23, 42, 0.03);
  transition: border-color 0.16s, box-shadow 0.2s, transform 0.2s;
}
.recent__card:hover {
  border-color: rgba(0, 20, 56, 0.14);
  box-shadow: 0 14px 32px rgba(0, 20, 56, 0.1);
  transform: translateY(-2px);
}
.recent__card:active {
  transform: translateY(0);
  box-shadow: 0 4px 12px rgba(0, 20, 56, 0.07);
}
.recent__card:focus-visible {
  outline: 2px solid var(--navy);
  outline-offset: 2px;
}
.recent__media {
  position: relative;
  width: 100%;
  aspect-ratio: 16 / 10;
  border-radius: 0;
  overflow: hidden;
  flex-shrink: 0;
  background: linear-gradient(145deg, #0b2244, #001438);
}
.recent__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.4s ease;
}
.recent__card:hover .recent__media img {
  transform: scale(1.04);
}
.recent__media-fallback {
  width: 100%;
  height: 100%;
  display: grid;
  place-items: center;
  background: linear-gradient(145deg, #0b2244, #001438);
  color: rgba(255, 255, 255, 0.72);
}
.recent__media-fallback svg {
  width: 28px;
  height: 28px;
}
.recent__badge { display: none; }
.recent__body {
  display: grid;
  gap: 4px;
  min-width: 0;
  padding: 12px 14px 14px;
}
.recent__kind {
  font-size: 0.65rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: #7b8ba3;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.recent__body strong {
  font-size: 1rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.recent__meta {
  font-size: 0.78rem;
  font-weight: 500;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.recent__go { display: none; }



.browse {
  background: var(--wash);
  padding: 48px 0 72px;
  position: relative;
}
.shelf {
  max-width: 1120px;
  margin: 0 auto 44px;
  padding: 0 24px;
}
.shelf:last-child { margin-bottom: 8px; }
.shelf__head {
  margin-bottom: 18px;
}
.shelf__head h2 {
  margin: 0;
  font-size: clamp(1.35rem, 2.2vw, 1.55rem);
  font-weight: 800;
  letter-spacing: -0.03em;
  color: var(--navy);
}
.shelf__head p {
  margin: 6px 0 0;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--muted);
  line-height: 1.4;
}

/* Shared horizontal rails */
.rail {
  display: grid;
  grid-auto-flow: column;
  grid-auto-columns: minmax(240px, 260px);
  gap: 14px;
  align-items: start; /* don't stretch hcards — stretched 1fr body left a dead dark slab */
  overflow-x: auto;
  padding: 6px 2px 16px;
  scroll-snap-type: x mandatory;
  scroll-padding-inline: 2px;
  scrollbar-width: thin;
  scrollbar-color: #c8d2e0 transparent;
  -webkit-overflow-scrolling: touch;
}
.rail::-webkit-scrollbar { height: 6px; }
.rail::-webkit-scrollbar-thumb {
  background: #c8d2e0;
  border-radius: 99px;
}
.rail > :first-child { scroll-snap-align: start; }
.rail__empty {
  grid-column: 1 / -1;
  margin: 0;
  padding: 18px 16px;
  border-radius: 14px;
  border: 1px dashed #c5d0de;
  background: #f6f8fb;
  color: var(--muted);
  font-size: 0.9rem;
  font-weight: 560;
  line-height: 1.45;
  max-width: 520px;
}
html[data-theme="dark"] .rail__empty,
html.dark .rail__empty {
  border-color: rgba(255, 255, 255, 0.18);
  background: rgba(255, 255, 255, 0.05);
  color: rgba(244, 247, 251, 0.72);
}

/* Routes worth flying — editorial lead + lanes, no invent fares */
.shelf--routes {
  max-width: 1120px;
  margin: 0 auto 48px;
  padding: 0 24px;
  background: transparent;
}
.shelf--routes .shelf__head {
  margin-bottom: 18px;
  padding: 0;
}
.shelf--routes .shelf__head h2 { color: var(--navy); }
.shelf--routes .shelf__head p { color: var(--muted); max-width: 48ch; }

.routes--editorial {
  display: grid;
  grid-template-columns: 1.35fr 1fr;
  gap: 16px;
  align-items: stretch;
}
.routes__stage { min-width: 0; }
.routes__lanes {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 0;
}

.route-lead {
  position: relative;
  display: block;
  border-radius: 22px;
  overflow: hidden;
  min-height: 340px;
  color: #fff;
  isolation: isolate;
  box-shadow: 0 18px 40px rgba(0, 12, 28, 0.14);
  transition: transform 0.25s var(--ease), box-shadow 0.25s var(--ease);
}
.route-lead:hover {
  transform: translateY(-2px);
  box-shadow: 0 24px 48px rgba(0, 12, 28, 0.18);
}
.route-lead:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 3px;
}
.route-lead__media {
  position: absolute;
  inset: 0;
  z-index: 0;
  background: var(--navy);
}
.route-lead__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.7s var(--ease);
}
.route-lead:hover .route-lead__media img { transform: scale(1.04); }
.route-lead__veil {
  position: absolute;
  inset: 0;
  z-index: 1;
  background:
    linear-gradient(180deg, rgba(0, 10, 24, 0.15) 0%, rgba(0, 10, 24, 0.72) 100%),
    linear-gradient(90deg, rgba(0, 16, 40, 0.45) 0%, transparent 55%);
}
.route-lead__copy {
  position: relative;
  z-index: 2;
  display: flex;
  flex-direction: column;
  justify-content: flex-end;
  gap: 8px;
  min-height: 340px;
  padding: 28px 26px;
}
.route-lead__pair {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.72);
}
.route-lead__city {
  font-size: clamp(1.8rem, 3.2vw, 2.4rem);
  font-weight: 750;
  letter-spacing: -0.035em;
  line-height: 1.05;
}
.route-lead__blurb {
  max-width: 28ch;
  font-size: 1rem;
  line-height: 1.45;
  color: rgba(255, 255, 255, 0.82);
}
.route-lead__go {
  margin-top: 10px;
  align-self: flex-start;
  font-size: 0.86rem;
  font-weight: 650;
  letter-spacing: -0.01em;
  color: #fff;
  border-bottom: 1px solid rgba(255, 255, 255, 0.55);
  padding-bottom: 2px;
  transition: border-color 0.15s, color 0.15s;
}
.route-lead:hover .route-lead__go {
  color: #fdba74;
  border-bottom-color: rgba(253, 186, 116, 0.7);
}

.route-lane {
  display: grid;
  grid-template-columns: 96px 1fr auto;
  align-items: center;
  gap: 14px;
  padding: 10px;
  border-radius: 16px;
  background: #fff;
  border: 1px solid rgba(0, 20, 56, 0.08);
  color: var(--navy);
  min-height: 96px;
  transition: border-color 0.16s, box-shadow 0.2s, transform 0.2s;
}
.route-lane:hover {
  border-color: rgba(0, 20, 56, 0.14);
  box-shadow: 0 10px 28px rgba(0, 20, 56, 0.08);
  transform: translateY(-1px);
}
.route-lane:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.route-lane__media {
  width: 96px;
  height: 76px;
  border-radius: 12px;
  overflow: hidden;
  background: var(--navy-mid);
}
.route-lane__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition: transform 0.45s var(--ease);
}
.route-lane:hover .route-lane__media img { transform: scale(1.05); }
.route-lane__body {
  display: grid;
  gap: 3px;
  min-width: 0;
}
.route-lane__pair {
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--muted);
}
.route-lane__city {
  font-size: 1.05rem;
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.15;
}
.route-lane__blurb {
  font-size: 0.84rem;
  line-height: 1.35;
  color: var(--muted);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.route-lane__go {
  width: 34px;
  height: 34px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--navy);
  background: #f1f5f9;
  flex-shrink: 0;
  transition: background 0.15s, color 0.15s;
}
.route-lane:hover .route-lane__go {
  background: var(--navy);
  color: #fff;
}

/* Legacy route-card kept for safety if old markup appears */
.route-card {
  display: flex;
  flex-direction: column;
  border-radius: 14px;
  overflow: hidden;
  background: #fff;
  border: 1px solid var(--line);
  color: var(--ink);
}

/* .hcard__cta-soft — defined with hotel card block below */

/* Currency pill styles live in /shared/theme.css (.currency-ctl) — shared chrome */
.top__currency {
  display: inline-flex;
  align-items: center;
  flex: 0 0 auto;
}

/* Legacy flight deal shells kept inert if empty */
.shelf--flights {
  max-width: 1120px;
  margin: 0 auto 40px;
  padding: 0 24px;
  background: transparent;
}
.flights {
  display: flex;
  flex-direction: column;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
}

.deal-stage {
  position: relative;
  width: 100%;
  height: clamp(200px, 24vw, 260px);
  min-height: 200px;
}

.flight-spot {
  position: absolute;
  inset: 0;
  border: 0;
  padding: 0;
  border-radius: 12px;
  overflow: hidden;
  cursor: pointer;
  text-align: left;
  font-family: var(--font);
  color: #fff;
  background: #0b2244;
  box-shadow: 0 10px 28px rgba(0, 20, 56, 0.1);
  transition: opacity 0.28s ease, box-shadow 0.25s ease;
}
.flight-spot.is-leave { opacity: 0; }
.flight-spot.is-enter { opacity: 0; }
.flight-spot:hover { box-shadow: 0 14px 32px rgba(0, 20, 56, 0.14); }
.flight-spot:focus-visible {
