.invite__work {
  position: relative;
  z-index: 1;
  background: #fff;
  padding: 30px 28px 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
  min-width: 0;
}
.invite__ask-label {
  margin: 0;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: #94a3b8;
}
.invite__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}
.invite__chips button {
  border: 1px solid #e8eef5;
  background: #f8fafc;
  color: #0f172a;
  border-radius: 999px;
  padding: 10px 14px;
  font-family: var(--font);
  font-size: 0.86rem;
  font-weight: 500;
