.invite__form {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 8px;
  align-items: stretch;
  padding: 9px;
  border: 1px solid #e8eef5;
  border-radius: 18px;
  background: #f8fafc;
  transition: border-color 0.15s, box-shadow 0.15s, background 0.15s;
}
.invite__form:focus-within {
  border-color: rgba(249, 114, 17, 0.45);
  box-shadow:
    0 0 0 3px rgba(249, 114, 17, 0.12),
    0 10px 28px rgba(0, 20, 56, 0.06);
  background: #fff;
}
.invite__form input {
  border: 0;
  background: transparent;
  padding: 13px 14px;
  font-family: var(--font);
  font-size: 1.02rem;
  font-weight: 400;
  color: #0f172a;
  min-width: 0;
  outline: none;
}
.invite__form input::placeholder { color: #94a3b8; }
.invite__form .vero-cta {
  align-self: stretch;
  min-height: 50px;
  border-radius: 12px;
}
.invite__more {
  margin: 2px 0 0;
  font-size: 0.86rem;
  font-weight: 500;
  color: #94a3b8;
}
.invite__more a {
  color: #0f172a;
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: color 0.15s, border-color 0.15s;
}
.invite__more a:hover {
  color: var(--accent);
  border-bottom-color: rgba(249, 114, 17, 0.4);
}
.invite__more span {
  margin: 0 6px;
  color: #cbd5e1;
}

@keyframes invite-spark {
  0%, 100% { opacity: 0.65; transform: scale(0.92); }
  50% { opacity: 1; transform: scale(1.06); }
}
@keyframes invite-pulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.18); }
  50% { box-shadow: 0 0 0 5px rgba(52, 211, 153, 0.28); }
}
@media (prefers-reduced-motion: reduce) {
  .invite__eyebrow-spark,
  .invite__face-spark,
  .invite__live::before {
    animation: none;
  }
}

/* Brand footer — final polish */
.footer {
  color: #e8edf4;
  background: #001439;
  position: relative;
}
.footer::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  width: min(160px, 28%);
  height: 2px;
  transform: translateX(-50%);
  border-radius: 99px;
  background: var(--accent);
  opacity: 0.9;
}
.footer__inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 56px 24px 26px;
  padding-bottom: max(26px, env(safe-area-inset-bottom));
}
.footer__main {
  display: grid;
  grid-template-columns: minmax(200px, 1.1fr) minmax(0, 1.4fr) minmax(250px, 0.95fr);
  gap: 36px 40px;
  align-items: start;
  padding-bottom: 36px;
  border-bottom: 1px solid rgba(232, 237, 244, 0.09);
}
.footer__brand {
  display: grid;
  gap: 12px;
  justify-items: start;
}
.footer__logoLink {
  display: inline-flex;
  text-decoration: none;
  margin-bottom: 2px;
}
.footer__logoImg {
  object-fit: contain;
  width: auto;
  max-width: 200px;
  height: 36px;
  transform: scaleX(1.22);
  transform-origin: left center;
}
.footer__tagline {
  margin: 0;
  max-width: 12ch;
  font-size: clamp(1.5rem, 2.2vw, 1.8rem);
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1.08;
  color: #fff;
}
.footer__tagline em {
  color: var(--accent);
  font-style: normal;
  font-weight: 800;
}
.footer__promise {
  margin: 2px 0 0;
  max-width: 30ch;
  font-size: 0.86rem;
  font-weight: 500;
  line-height: 1.5;
  color: rgba(232, 237, 244, 0.52);
}
.footer__links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px 24px;
  padding-top: 4px;
}
.footer__col {
  display: grid;
  gap: 8px;
  align-content: start;
}
.footer__col-title {
  margin: 0 0 4px;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(232, 237, 244, 0.38);
}
.footer__col-link {
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.35;
  text-decoration: none;
  transition: color 0.15s;
  width: fit-content;
}
.footer__col-link:hover { color: #fff; }

.footer__aside {
  display: grid;
  gap: 20px;
  align-content: start;
  padding-top: 4px;
}
.footer__subscribe {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}
.footer__subscribeLabel {
  margin: 0;
  color: rgba(232, 237, 244, 0.38);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.footer__subscribeRow {
  display: flex;
  gap: 0;
  border: 1px solid rgba(232, 237, 244, 0.16);
  border-radius: 12px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.04);
  transition: border-color 0.15s;
}
.footer__subscribeRow:focus-within {
  border-color: rgba(249, 114, 17, 0.5);
}
.footer__subscribeRow input {
  flex: 1;
  min-width: 0;
  color: #fff;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 500;
  background: transparent;
  border: 0;
  padding: 12px 14px;
  outline: none;
}
.footer__subscribeRow input::placeholder { color: rgba(232, 237, 244, 0.38); }
.footer__subscribeRow button {
  flex-shrink: 0;
  color: #fff;
  cursor: pointer;
  background: var(--accent);
  border: 0;
  padding: 12px 18px;
  font: inherit;
  font-size: 0.88rem;
  font-weight: 700;
  transition: background 0.15s;
}
.footer__subscribeRow button:hover { background: var(--accent-hover); }
.footer__subscribeRow button:disabled {
  opacity: 0.7;
  cursor: wait;
}
.footer__subscribeStatus {
  color: rgba(255, 255, 255, 0.72);
  margin: 0;
  font-size: 0.8rem;
}
.footer__ig {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
  text-decoration: none;
  color: #fff;
  width: fit-content;
  transition: color 0.15s;
}
.footer__ig:hover { color: var(--accent); }
.footer__ig:hover .footer__ig-icon { background: rgba(249, 114, 17, 0.22); }
.footer__ig-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: rgba(249, 114, 17, 0.12);
  color: var(--accent);
  flex-shrink: 0;
  transition: background 0.15s;
}
.footer__ig-text {
  display: grid;
  gap: 1px;
  min-width: 0;
}
.footer__ig-label {
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(232, 237, 244, 0.4);
}
.footer__ig-handle {
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.footer__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-top: 18px;
}
.footer__copy,
.footer__bar-note {
  margin: 0;
  color: rgba(255, 255, 255, 0.36);
  font-size: 0.76rem;
  font-weight: 500;
}

@media (max-width: 980px) {
  .top__nav a:nth-child(n + 4) { display: none; }
}

@media (max-width: 900px) {
  .trust__row { grid-template-columns: 1fr 1fr; }
  .invite { padding: 44px 18px 40px; }
  .browse { padding: 40px 0 56px; }
  .invite--after-hero {
    margin-top: 0;
    padding: 56px 18px 40px;
    background:
      radial-gradient(720px 360px at 8% 0%, rgba(196, 181, 253, 0.14), transparent 58%),
      radial-gradient(640px 320px at 96% 10%, rgba(253, 186, 116, 0.1), transparent 52%),
      var(--wash);
  }
  .invite__intro { text-align: left; margin-bottom: 18px; }
  .invite__intro h2 { margin-inline: 0; max-width: none; }
  .invite__lead { margin-inline: 0; }
  .invite__shell { grid-template-columns: 1fr; border-radius: 22px; }
  .invite__brand { padding: 22px 20px; min-height: 0; gap: 18px; }
  .invite__face { width: 64px; height: 64px; }
  .invite__work { padding: 20px 18px; }
  .invite__form { grid-template-columns: 1fr; }
  .invite__form .vero-cta { width: 100%; min-height: 48px; }
  .invite__bubbles { gap: 10px; }
  .shelf--flights,
  .shelf--routes { padding: 0 18px; margin-bottom: 36px; }
  .routes--editorial {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .route-lead,
  .route-lead__copy { min-height: 280px; }
  .route-lane {
    grid-template-columns: 84px 1fr auto;
    min-height: 88px;
  }
  .route-lane__media {
    width: 84px;
    height: 68px;
  }
  .top__tools { gap: 8px; }
  .deal-stage { height: 200px; min-height: 200px; }
  .flight-spot__content { padding: 14px 16px 16px; }
  .flight-spot__city { font-size: 1.45rem; }
  .flight-spot__blurb { font-size: 0.8rem; }
  .flight-spot__foot { gap: 12px; }
  .flight-spot__cta { padding: 8px 12px; font-size: 0.7rem; }
  .flight-stack__list {
    display: flex;
    gap: 8px;
    overflow-x: auto;
    scroll-snap-type: x mandatory;
    -webkit-overflow-scrolling: touch;
    padding: 2px 2px 6px;
    margin: 0 -2px;
    scrollbar-width: none;
  }
  .flight-stack__list::-webkit-scrollbar { display: none; }
  .flight-ticket {
    flex: 0 0 min(148px, 42vw);
    scroll-snap-align: start;
  }
  /* Keep rail inside shelf padding so the first card is never clipped */
  .rail {
    grid-auto-columns: minmax(210px, calc(100vw - 64px));
    margin: 0;
    padding: 6px 4px 16px;
    scroll-padding-inline: 4px;
  }
  .hcard:hover {
    transform: none;
    box-shadow: none;
  }
  .vhop { margin: 4px auto 48px; padding: 0 18px; }
  .vhop__tickets { grid-template-columns: 1fr; }
  .shelf { padding: 0 18px; margin-bottom: 36px; }
  .browse { padding: 36px 0 48px; }
}

@media (max-width: 731px) {
  .vhop {
    margin: 4px auto 48px;
    padding: 0 18px;
  }
  .vhop__ticket {
    grid-template-columns: minmax(0, 1fr) 88px;
  }
  .vhop__ticket:hover,
  .vhop__ticket:nth-child(2):hover {
    transform: none;
  }
  .vhop__ticket-main { padding: 16px 16px 18px; }
  .vhop__code { font-size: 1.45rem; }
}

@media (max-width: 820px) {
  .top__inner {
    padding: 12px 16px;
    padding-top: max(12px, env(safe-area-inset-top));
    gap: 12px;
  }
  .top__mark img { height: 26px; }
  .top__nav { display: none; }
  .top__signin { display: none; }
  .top__account-label { display: none; }
  .top__account-btn { padding-right: 5px; }
  .top__icon {
    width: 40px;
    height: 40px;
  }
  .sheet { place-items: start center; padding-top: 64px; }
  .trust__row { grid-template-columns: 1fr; gap: 12px; }

  .stage {
    min-height: 100svh;
    min-height: 100dvh;
    align-items: start;
  }
  .stage__body {
    width: min(100% - 28px, 920px);
    margin-top: 0;
    padding: max(88px, calc(42vh - 90px), calc(64px + env(safe-area-inset-top))) 0 max(20px, env(safe-area-inset-bottom));
  }
  .stage__line {
    font-size: clamp(1.15rem, 5.2vw, 1.4rem);
    margin-bottom: 14px;
    min-height: 1.25em;
  }
  .dock { margin-top: 18px; }
  .dock__toolbar {
    flex-direction: column;
    align-items: stretch;
    gap: 10px;
    padding-bottom: 10px;
  }
  .dock__modes {
    width: 100%;
    justify-content: flex-start;
    gap: 4px;
    overflow-x: auto;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
  }
  .dock__modes::-webkit-scrollbar { display: none; }
  .dock__mode {
    flex: 0 0 auto;
    font-size: 0.82rem;
    padding: 8px 12px;
  }
  .dock__trip {
    width: 100%;
    justify-content: stretch;
  }
  .dock__trip-btn {
    flex: 1;
    text-align: center;
    padding: 8px 8px;
    font-size: 0.74rem;
  }
  .dock__form {
    grid-template-columns: 1fr;
    border-radius: 18px;
    padding: 8px;
    gap: 8px;
  }
  .dock__fields,
  .dock__fields[data-trip="round"],
  .dock__fields[data-trip="multi"],
  .dock__fields--multi {
    grid-template-columns: 1fr 1fr;
    gap: 0;
    border-radius: 14px;
    overflow: hidden;
    background: rgba(255, 255, 255, 0.04);
  }
  .cell {
    border-radius: 0;
    padding: 11px 12px;
    border-right: 1px solid rgba(255, 255, 255, 0.14);
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  }
  .cell:nth-child(2n) { border-right: 0; }
  .cell:nth-last-child(-n + 2) { border-bottom: 0; }
  .dock__fields[data-trip="round"] .cell--pax,
  .dock__fields[data-trip="round"] .cell--return {
    border-bottom: 0;
  }
  .cell--wide { grid-column: 1 / -1; border-right: 0; }
  .cell input,
  .cell__face { font-size: 0.92rem; }
  .dock__go {
    width: 100%;
    min-height: 48px;
    padding: 14px;
    border-radius: 14px;
  }
  .dock.is-chat {
    width: 100%;
  }
  .dock.is-chat .dock__toolbar { justify-content: flex-start; }
  .vero-chat {
    border-radius: 18px;
    max-height: min(380px, calc(100dvh - 200px));
  }
  .vero-chat__thread { max-height: min(120px, 16vh); }
  .vero-chat__intro p { font-size: 0.8rem; }
  .vero-chat__suggest { padding: 0 10px 8px; }
  .vero-chat__chips button { min-height: 32px; }
  .vero-chat__composer { padding: 8px 10px 10px; }

  .invite--after-hero .invite__intro h2 {
    font-size: clamp(1.45rem, 6.5vw, 1.9rem);
    color: #0f172a;
  }
  .invite--after-hero .invite__lead {
    font-size: 0.95rem;
  }
  .invite__more {
    flex-wrap: wrap;
    gap: 6px 10px;
  }
  .invite__chips {
    flex-wrap: nowrap;
    overflow-x: auto;
    scrollbar-width: none;
    -webkit-overflow-scrolling: touch;
    margin: 0 -4px;
    padding: 0 4px 4px;
  }
  .invite__chips::-webkit-scrollbar { display: none; }
  .invite__chips button { flex: 0 0 auto; }

  .recent {
    padding: 28px 0 18px;
  }
  .recent__head {
    align-items: flex-start;
  }
  .recent__nav { display: none !important; }
  .recent__track { padding: 0; }
  .recent__card {
    width: min(200px, 68vw);
  }

  .footer__inner {
    padding: 48px 18px max(28px, env(safe-area-inset-bottom));
  }
  .footer__main {
    grid-template-columns: 1fr;
    gap: 32px;
    padding-bottom: 32px;
  }
  .footer__links {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px 12px;
  }
  .footer__logoImg {
    height: 34px;
    max-width: 170px;
  }
  .footer__tagline {
    max-width: 16ch;
    font-size: 1.45rem;
  }
  .footer__bar-note { display: none; }
}

@media (max-width: 480px) {
  .stage__body {
    width: min(100% - 20px, 920px);
    padding-bottom: max(22px, env(safe-area-inset-bottom));
  }
  .stage__line { font-size: 1.12rem; }
  .dock__fields { grid-template-columns: 1fr; }
  .cell {
    border-right: 0 !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  }
  .cell:last-child { border-bottom: 0; }
  .deal-stage { height: 176px; min-height: 176px; }
  .flight-spot__blurb {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .flight-ticket { flex-basis: min(140px, 46vw); }
  .invite__brand { padding: 18px 16px; }
  .invite__work { padding: 18px 16px; }
  .shelf__head h2 { font-size: 1.28rem; }
}

/* Dark mode — remap homepage tokens when shared theme sets html[data-theme="dark"] */
html[data-theme="dark"] {
  color-scheme: dark;
  --ink: #e8eef6;
  --muted: #9aa8bc;
  --line: #2a3b55;
  --wash: #070d16;
  --select: rgba(215, 230, 247, 0.08);
  --navy: #d7e6f7;
  --navy-mid: #8eabcc;
}
html[data-theme="dark"],
html[data-theme="dark"] body {
  background: var(--wash);
  color: var(--ink);
}
html[data-theme="dark"] .invite,
html[data-theme="dark"] .browse,
html[data-theme="dark"] .recent,
html[data-theme="dark"] .footer {
  background: var(--wash);
  color: var(--ink);
}
html[data-theme="dark"] .shelf__head h2,
html[data-theme="dark"] .invite__intro h2,
html[data-theme="dark"] .recent__intro h2 {
  color: var(--ink);
}
html[data-theme="dark"] .shelf__head p,
html[data-theme="dark"] .invite__lead,
html[data-theme="dark"] .recent__eyebrow {
  color: var(--muted);
}
html[data-theme="dark"] .hcard,
html[data-theme="dark"] .route-card,
html[data-theme="dark"] .route-lane,
html[data-theme="dark"] .flight-ticket,
html[data-theme="dark"] .recent__card,
html[data-theme="dark"] .invite__shell {
  background: #101a2a;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .vhop__title { color: var(--ink); }
html[data-theme="dark"] .vhop__kicker,
html[data-theme="dark"] .vhop__sub { color: var(--muted); }
html[data-theme="dark"] .vhop__ask {
  background: #101a2a;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .vhop__ask:hover {
  background: #152033;
  border-color: rgba(249, 114, 17, 0.4);
}
html[data-theme="dark"] .vhop__ticket {
  --ticket-ink: #e8eef6;
  --ticket-paper: #101a2a;
  --ticket-line: rgba(232, 238, 246, 0.12);
  box-shadow:
    0 0 0 1px rgba(232, 238, 246, 0.1),
    0 16px 36px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .vhop__ticket-stub {
  background: #070d16;
}
html[data-theme="dark"] .vhop__hint { color: var(--muted); }
html[data-theme="dark"] .vhop__arrow { color: rgba(232, 238, 246, 0.4); }
html[data-theme="dark"] .route-card__city,
html[data-theme="dark"] .route-lane__city,
html[data-theme="dark"] .hcard__cta-soft {
  color: var(--ink);
}
html[data-theme="dark"] .route-card__cta,
html[data-theme="dark"] .route-lane__go {
  background: #1c3358;
  color: #fff;
}
html[data-theme="dark"] .hcard__where,
html[data-theme="dark"] .hcard__price small,
html[data-theme="dark"] .hcard__night,
html[data-theme="dark"] .route-card__blurb,
html[data-theme="dark"] .route-card__pair,
html[data-theme="dark"] .route-lane__blurb,
html[data-theme="dark"] .route-lane__pair,
html[data-theme="dark"] .flight-ticket__meta,
html[data-theme="dark"] .recent__meta,
html[data-theme="dark"] .recent__kind {
  color: var(--muted);
}
html[data-theme="dark"] .hcard__foot {
  border-top-color: var(--line);
}
html[data-theme="dark"] .invite__work {
  background: #101a2a;
}
html[data-theme="dark"] .invite__chips button,
html[data-theme="dark"] .invite__form {
  background: #0b1422;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .invite__form input {
  color: var(--ink);
}
html[data-theme="dark"] .invite__ask-label,
html[data-theme="dark"] .invite__more {
  color: var(--muted);
}
html[data-theme="dark"] .invite__more a {
  color: var(--ink);
}
html[data-theme="dark"] .recent__clear {
  border-color: rgba(215, 230, 247, 0.18);
  color: var(--muted);
}
html[data-theme="dark"] .recent__nav {
  background: #101a2a;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .stage::before {
  background:
    radial-gradient(ellipse 70% 55% at 50% 48%, rgba(0, 8, 20, 0.5), transparent 68%),
    linear-gradient(
      180deg,
      rgba(0, 10, 24, 0.62) 0%,
      rgba(0, 8, 20, 0.28) 42%,
      rgba(7, 13, 22, 0.55) 100%
    );
}
html[data-theme="dark"] .top.is-solid {
  background: rgba(7, 13, 22, 0.94);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .drawer__panel,
html[data-theme="dark"] .sheet__card {
  background: #101a2a;
  color: var(--ink);
}
/* Drawer, dark: every light-only colour above gets a token so nothing renders dark-on-dark. */
html[data-theme="dark"] .drawer__panel {
  box-shadow: -20px 0 48px rgba(0, 0, 0, 0.45);
}
/* Logo day/night swap lives next to .drawer__brand img (higher specificity). */
html[data-theme="dark"] .drawer__label,
html[data-theme="dark"] .drawer__foot p {
  color: var(--muted);
}
