  font-size: 0.74rem;
  font-weight: 750;
  padding: 9px 14px;
  box-shadow: 0 4px 14px rgba(0, 12, 28, 0.12);
}

.flight-stack {
  margin-top: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
}
.flight-stack__list {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 8px;
}
.flight-ticket {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 1px;
  width: 100%;
  min-width: 0;
  border: 1px solid rgba(0, 20, 56, 0.1);
  border-radius: 10px;
  background: #fff;
  padding: 10px 12px 11px;
  cursor: pointer;
  text-align: left;
  font-family: var(--font);
  color: var(--navy);
  transition:
    background 0.18s ease,
    border-color 0.18s ease,
    box-shadow 0.18s ease;
}
.flight-ticket:hover {
  border-color: rgba(249, 114, 17, 0.35);
  background: #fffaf6;
}
.flight-ticket:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
}
.flight-ticket.is-on {
  background: #fff7f0;
  border-color: rgba(249, 114, 17, 0.45);
  box-shadow: 0 0 0 1px rgba(249, 114, 17, 0.18);
}
.flight-ticket__codes {
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  line-height: 1.2;
  color: #8a97ab;
}
.flight-ticket.is-on .flight-ticket__codes { color: #7a8699; }
.flight-ticket__city {
  font-size: 0.86rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.15;
  color: var(--navy);
}
.flight-ticket__meta {
  font-size: 0.62rem;
  font-weight: 500;
  color: var(--muted);
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  max-width: 100%;
}
.flight-ticket__price {
  margin-top: 6px;
  font-size: 0.92rem;
  font-weight: 800;
  letter-spacing: -0.02em;
  line-height: 1.1;
  color: var(--navy);
}
.flight-ticket.is-on .flight-ticket__price { color: var(--accent); }
.flight-ticket__cta {
  margin-top: 1px;
  font-size: 0.6rem;
  font-weight: 750;
  letter-spacing: 0.03em;
  text-transform: uppercase;
  color: #8a97ab;
}
.flight-ticket:hover .flight-ticket__cta,
.flight-ticket.is-on .flight-ticket__cta {
  color: var(--accent);
}

@media (prefers-reduced-motion: reduce) {
  .flight-spot,
  .flight-spot.is-leave,
  .flight-spot.is-enter,
  .flight-spot__img img,
  .flight-ticket { transition: none; opacity: 1; }
}

/* Weekend hop tickets — rail stubs issued by Vero (not a desk panel / OR duel) */
.vhop {
  max-width: 1120px;
  margin: 4px auto 56px;
  padding: 0 24px;
  opacity: 0;
  transform: translateY(10px);
  transition: opacity 0.5s var(--ease), transform 0.5s var(--ease);
}
.vhop.is-in {
  opacity: 1;
  transform: translateY(0);
}
.vhop__issue {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  gap: 14px 16px;
  align-items: center;
  margin-bottom: 18px;
}
.vhop__stamp {
  width: 44px;
  height: 44px;
  border-radius: 50%;
  object-fit: cover;
  background: #0b1730;
  box-shadow:
    0 0 0 2px #fff,
    0 0 0 3px rgba(249, 114, 17, 0.55);
}
.vhop__issue-copy { min-width: 0; }
.vhop__kicker {
  margin: 0;
  font-size: 0.68rem;
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: var(--muted);
}
.vhop__title {
  margin: 4px 0 0;
  font-size: clamp(1.4rem, 2.5vw, 1.85rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1.1;
  color: var(--navy);
}
.vhop__sub {
  margin: 6px 0 0;
  font-size: 0.92rem;
  font-weight: 500;
  line-height: 1.45;
  color: var(--muted);
  max-width: 48ch;
}
.vhop__footer {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: center;
  gap: 10px 14px;
  margin: 18px 0 0;
  font-size: 0.9rem;
  font-weight: 500;
  color: var(--muted);
}
.vhop__ask {
  min-height: 40px;
  padding: 0 16px;
  border: 1px solid rgba(0, 20, 56, 0.14);
  border-radius: 999px;
  background: #fff;
  color: var(--navy);
  font-family: var(--font);
  font-size: 0.84rem;
  font-weight: 700;
  letter-spacing: -0.01em;
  cursor: pointer;
  transition: border-color 0.15s ease, background 0.15s ease, transform 0.15s var(--ease);
}
.vhop__ask:hover {
  border-color: rgba(249, 114, 17, 0.45);
  background: #fff7f0;
  transform: translateY(-1px);
}
.vhop__ask:focus-visible {
  outline: 2px solid var(--accent, #f97211);
  outline-offset: 2px;
}
.vhop__tickets {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 16px;
}
.vhop__ticket {
  --ticket-ink: #0b1730;
  --ticket-paper: #f7f9fc;
  --ticket-line: rgba(11, 23, 48, 0.12);
  position: relative;
  display: grid;
  grid-template-columns: minmax(0, 1fr) 108px;
  width: 100%;
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 18px;
  background: var(--ticket-paper);
  color: var(--ticket-ink);
  text-align: left;
  font-family: var(--font);
  cursor: pointer;
  overflow: hidden;
  box-shadow:
    0 0 0 1px rgba(11, 23, 48, 0.08),
    0 16px 36px rgba(0, 20, 56, 0.1);
  transition: transform 0.2s var(--ease), box-shadow 0.2s var(--ease);
}
.vhop__ticket:hover {
  transform: translateY(-3px) rotate(-0.35deg);
  box-shadow:
    0 0 0 1px rgba(11, 23, 48, 0.12),
    0 22px 44px rgba(0, 20, 56, 0.14);
}
.vhop__ticket:nth-child(2):hover {
  transform: translateY(-3px) rotate(0.35deg);
}
.vhop__ticket:focus-visible {
  outline: 2px solid var(--accent, #f97211);
  outline-offset: 3px;
}
.vhop__ticket-main {
  display: grid;
  gap: 8px;
  padding: 20px 22px 22px;
  min-width: 0;
  background:
    repeating-linear-gradient(
      -12deg,
      transparent,
      transparent 11px,
      rgba(11, 23, 48, 0.015) 11px,
      rgba(11, 23, 48, 0.015) 12px
    );
}
.vhop__route {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--ticket-ink);
}
.vhop__code {
  font-size: clamp(1.55rem, 2.4vw, 1.9rem);
  font-weight: 800;
  letter-spacing: -0.04em;
  line-height: 1;
  font-variant-numeric: tabular-nums;
}
.vhop__arrow {
  display: inline-flex;
  color: rgba(11, 23, 48, 0.45);
  flex: 1;
  min-width: 36px;
}
.vhop__arrow svg { width: 100%; height: 12px; }
.vhop__city {
  font-size: 1.05rem;
  font-weight: 750;
  letter-spacing: -0.025em;
  line-height: 1.2;
}
.vhop__hint {
  font-size: 0.82rem;
  font-weight: 500;
  color: rgba(11, 23, 48, 0.58);
  line-height: 1.35;
}
.vhop__ticket-stub {
  position: relative;
  display: grid;
  align-content: space-between;
  justify-items: center;
  gap: 10px;
  padding: 18px 12px;
  background: #0b1730;
  color: #e8eef6;
  text-align: center;
}
.vhop__ticket-stub::before {
  content: "";
  position: absolute;
  left: -7px;
  top: 0;
  bottom: 0;
  width: 14px;
  background:
    radial-gradient(circle at 0 10px, transparent 6px, var(--ticket-paper) 7px) 0 0 / 14px 20px repeat-y;
  mask-image: linear-gradient(#000, #000);
}
.vhop__stub-label {
  font-size: 0.62rem;
  font-weight: 750;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(249, 114, 17, 0.95);
  writing-mode: horizontal-tb;
}
.vhop__stub-action {
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  max-width: 7ch;
  line-height: 1.25;
}
@media (prefers-reduced-motion: reduce) {
  .vhop,
  .vhop__ticket,
  .vhop__ask {
    transition: none;
    transform: none;
    opacity: 1;
  }
}

/* Hotel cards — compact stay tiles (media + title + inline price) */

.hcard {
  scroll-snap-align: start;
  display: grid;
  grid-template-rows: 152px auto;
  width: 100%;
  border: 1px solid #e2e8f0;
  background: #fff;
  border-radius: 16px;
  overflow: hidden;
  padding: 0;
  cursor: pointer;
  text-align: left;
  font-family: var(--font);
  color: var(--navy);
  isolation: isolate;
  transition: border-color 0.18s, box-shadow 0.22s, transform 0.22s;
}
.hcard:hover {
  border-color: #c5d0de;
  box-shadow: 0 14px 36px rgba(0, 20, 56, 0.09);
  transform: translateY(-3px);
}
.hcard:focus-visible {
  outline: 2px solid var(--navy);
  outline-offset: 2px;
}
.hcard__media {
  position: relative;
  background: #dbe3ee;
  overflow: hidden;
  border-radius: 16px 16px 0 0;
}
.hcard__media.is-fallback,
.route-lead__media.is-fallback,
.route-lane__media.is-fallback {
  /* Last resort only — JS prefers Unsplash swap before this paints */
  background:
    linear-gradient(145deg, rgba(10, 22, 40, 0.35), rgba(26, 43, 69, 0.55)),
    url("https://images.unsplash.com/photo-1488646953014-85cb44e25828?auto=format&fit=crop&w=900&q=70")
      center / cover no-repeat;
}
.hcard__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
  transition: transform 0.45s var(--ease);
}
.hcard__media img.is-broken,
.route-lead__media img.is-broken,
.route-lane__media img.is-broken {
  display: none;
}
.hcard:hover .hcard__media img { transform: scale(1.04); }
.hcard--skeleton {
  pointer-events: none;
  border-color: #e8edf4;
  background: linear-gradient(90deg, #f1f4f8 0%, #e8edf4 45%, #f1f4f8 100%);
  background-size: 200% 100%;
  animation: hcard-shimmer 1.15s ease-in-out infinite;
  min-height: 248px;
}
@keyframes hcard-shimmer {
  0% { background-position: 100% 0; }
  100% { background-position: -100% 0; }
}
@media (prefers-reduced-motion: reduce) {
  .hcard--skeleton { animation: none; }
}
.hcard__badge {
  position: absolute;
  left: 10px;
  bottom: 10px;
  display: inline-flex;
  align-items: baseline;
  gap: 5px;
  background: rgba(0, 20, 56, 0.9);
  color: #fff;
  border-radius: 999px;
  padding: 5px 10px;
  font-size: 0.68rem;
  font-weight: 650;
  letter-spacing: 0.01em;
  backdrop-filter: blur(8px);
  box-shadow: 0 4px 14px rgba(0, 12, 32, 0.28);
}
.hcard__badge b {
  font-size: 0.8rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}
.hcard__body {
  display: grid;
  gap: 6px;
  padding: 12px 14px 14px;
  align-content: start;
  min-width: 0;
}
.hcard__body > strong {
  display: -webkit-box;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
  line-clamp: 2;
  overflow: hidden;
  font-size: 0.92rem;
  font-weight: 750;
  letter-spacing: -0.022em;
  line-height: 1.28;
}
.hcard__body .hcard__where {
  font-size: 0.75rem;
  font-weight: 500;
  color: var(--muted);
  line-height: 1.3;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
.hcard__foot {
  display: flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px 6px;
  margin-top: 4px;
  padding-top: 10px;
  border-top: 1px solid #eef2f6;
}
.hcard__cta-soft {
  font-size: 0.78rem;
  font-weight: 650;
  color: var(--accent, #f97211);
  letter-spacing: -0.01em;
}
.hcard__price {
  display: inline-flex;
  align-items: baseline;
  flex-wrap: wrap;
  gap: 4px 6px;
  min-width: 0;
}
.hcard__price small {
  font-size: 0.68rem;
  font-weight: 600;
  color: var(--muted);
}
.hcard__price strong {
  font-size: 1.05rem;
  font-weight: 800;
  letter-spacing: -0.03em;
  line-height: 1;
}
.hcard__night {
  font-size: 0.72rem;
  font-weight: 500;
  color: var(--muted);
}

/* Vero invite — USP right under hero */
.invite {
  padding: 64px 24px 56px;
  background:
    radial-gradient(900px 420px at 8% 0%, rgba(0, 20, 56, 0.05), transparent 55%),
    radial-gradient(780px 360px at 96% 12%, rgba(249, 114, 17, 0.08), transparent 50%),
    var(--wash);
}
.invite--after-hero {
  position: relative;
  z-index: 3;
  /* Starts after the full-viewport hero — space above Ask Vero, no overlap into image */
  margin-top: 0;
  padding: 72px 24px 48px;
  border: 0;
  background:
    radial-gradient(900px 420px at 8% 0%, rgba(0, 20, 56, 0.045), transparent 55%),
    radial-gradient(780px 360px at 96% 10%, rgba(249, 114, 17, 0.07), transparent 50%),
    var(--wash);
}
.invite--after-hero .invite__intro {
  margin-bottom: 22px;
}
.invite--after-hero .invite__shell {
  max-width: 1120px;
  box-shadow:
    0 0 0 1px rgba(0, 20, 56, 0.06),
    0 24px 56px rgba(0, 12, 28, 0.12);
}
.invite__intro {
  max-width: 720px;
  margin: 0 auto 28px;
  text-align: center;
}
.invite__eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  margin: 0 0 12px;
  font-size: 0.78rem;
  font-weight: 650;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: var(--accent);
}
.invite__eyebrow-spark {
  display: inline-flex;
  color: var(--accent);
  animation: invite-spark 2.8s ease-in-out infinite;
}
.invite__intro h2 {
  margin: 0 auto;
  font-size: clamp(1.75rem, 3.6vw, 2.35rem);
  font-weight: 700;
  letter-spacing: -0.035em;
  line-height: 1.12;
  color: var(--navy);
  max-width: 14ch;
}
.invite__lead {
  margin: 14px auto 0;
  max-width: 38ch;
  font-size: 1.05rem;
  font-weight: 400;
  line-height: 1.55;
  color: var(--muted);
}
.invite__shell {
  position: relative;
  max-width: 1080px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: minmax(280px, 0.95fr) 1.15fr;
  border-radius: 24px;
  overflow: hidden;
  background: #fff;
  border: 1px solid rgba(0, 20, 56, 0.08);
  box-shadow:
    0 0 0 1px rgba(0, 20, 56, 0.04),
    0 20px 48px rgba(15, 23, 42, 0.08);
}
.invite__shell::before {
  content: "";
  position: absolute;
  inset: -1px;
  border-radius: inherit;
  padding: 1px;
  background: linear-gradient(
    135deg,
    rgba(249, 114, 17, 0.45),
    rgba(0, 20, 56, 0.12),
    rgba(249, 114, 17, 0.28)
  );
  -webkit-mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  mask:
    linear-gradient(#fff 0 0) content-box,
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
  opacity: 0.55;
  z-index: 2;
