.invite__brand {
  position: relative;
  z-index: 1;
  padding: 30px 28px;
  color: #fff;
  background:
    radial-gradient(420px 240px at 12% -8%, rgba(249, 114, 17, 0.18), transparent 55%),
    linear-gradient(165deg, #001a44 0%, #001438 52%, #0b2244 100%);
  display: flex;
  flex-direction: column;
  gap: 22px;
  min-height: 100%;
}
.invite__who {
  display: flex;
  align-items: center;
  gap: 14px;
}
.invite__face-wrap {
  position: relative;
  flex-shrink: 0;
}
.invite__face {
  width: 76px;
  height: 76px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.45);
  box-shadow:
    0 12px 32px rgba(0, 0, 0, 0.3),
    0 0 0 6px rgba(249, 114, 17, 0.14);
  display: block;
}
.invite__face-spark {
  position: absolute;
  top: -2px;
  right: -4px;
  width: 20px;
  height: 20px;
  color: #fdba74;
  filter: drop-shadow(0 0 6px rgba(249, 114, 17, 0.4));
  animation: invite-spark 2.4s ease-in-out infinite;
}
.invite__face-spark svg {
  display: block;
  width: 20px;
  height: 20px;
}
.invite__who-meta {
  display: flex;
  flex-direction: column;
  gap: 5px;
}
.invite__who-meta strong {
  font-size: 1.25rem;
  font-weight: 700;
  letter-spacing: -0.02em;
}
.invite__live {
  display: inline-flex;
  align-items: center;
  gap: 7px;
  font-size: 0.8rem;
  font-weight: 600;
  color: #a7f3d0;
}
.invite__live::before {
  content: "";
  width: 7px;
  height: 7px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.22);
  animation: invite-pulse 2s ease-in-out infinite;
