  z-index: 1;
  background: #fff;
  padding: 30px 28px 24px;
  display: flex;
  flex-direction: column;
  justify-content: center;
  gap: 16px;
  min-width: 0;
}
.invite__ask-label {
  margin: 0;
  font-size: 0.8rem;
  font-weight: 600;
  letter-spacing: 0.02em;
  color: #94a3b8;
}
.invite__chips {
