  flex-wrap: wrap;
  gap: 8px;
}
.invite__chips button {
  border: 1px solid #e8eef5;
  background: #f8fafc;
  color: #0f172a;
  border-radius: 999px;
  padding: 10px 14px;
  font-family: var(--font);
  font-size: 0.86rem;
  font-weight: 500;
