  padding: 13px 14px;
  font-family: var(--font);
  font-size: 1.02rem;
  font-weight: 400;
  color: #0f172a;
  min-width: 0;
  outline: none;
}
.invite__form input::placeholder { color: #94a3b8; }
.invite__form .vero-cta {
  align-self: stretch;
  min-height: 50px;
  border-radius: 12px;
}
.invite__more {
  margin: 2px 0 0;
  font-size: 0.86rem;
  font-weight: 500;
  color: #94a3b8;
}
.invite__more a {
  color: #0f172a;
  text-decoration: none;
  border-bottom: 1px solid transparent;
  transition: color 0.15s, border-color 0.15s;
}
.invite__more a:hover {
  color: var(--accent);
  border-bottom-color: rgba(249, 114, 17, 0.4);
}
.invite__more span {
  margin: 0 6px;
  color: #cbd5e1;
}

@keyframes invite-spark {
  0%, 100% { opacity: 0.65; transform: scale(0.92); }
  50% { opacity: 1; transform: scale(1.06); }
}
@keyframes invite-pulse {
  0%, 100% { box-shadow: 0 0 0 3px rgba(52, 211, 153, 0.18); }
  50% { box-shadow: 0 0 0 5px rgba(52, 211, 153, 0.28); }
}
@media (prefers-reduced-motion: reduce) {
  .invite__eyebrow-spark,
  .invite__face-spark,
  .invite__live::before {
    animation: none;
  }
}

/* Brand footer — final polish */
.footer {
  color: #e8edf4;
  background: #001439;
  position: relative;
}
.footer::before {
  content: "";
  position: absolute;
  left: 50%;
  top: 0;
  width: min(160px, 28%);
  height: 2px;
  transform: translateX(-50%);
  border-radius: 99px;
  background: var(--accent);
  opacity: 0.9;
}
.footer__inner {
  max-width: 1120px;
  margin: 0 auto;
  padding: 56px 24px 26px;
  padding-bottom: max(26px, env(safe-area-inset-bottom));
}
.footer__main {
  display: grid;
  grid-template-columns: minmax(200px, 1.1fr) minmax(0, 1.4fr) minmax(250px, 0.95fr);
  gap: 36px 40px;
  align-items: start;
  padding-bottom: 36px;
  border-bottom: 1px solid rgba(232, 237, 244, 0.09);
}
.footer__brand {
  display: grid;
  gap: 12px;
  justify-items: start;
}
.footer__logoLink {
  display: inline-flex;
  text-decoration: none;
  margin-bottom: 2px;
}
.footer__logoImg {
  object-fit: contain;
  width: auto;
  max-width: 200px;
  height: 36px;
  transform: scaleX(1.22);
  transform-origin: left center;
}
.footer__tagline {
  margin: 0;
  max-width: 12ch;
  font-size: clamp(1.5rem, 2.2vw, 1.8rem);
  font-weight: 800;
  letter-spacing: -0.045em;
  line-height: 1.08;
  color: #fff;
}
.footer__tagline em {
  color: var(--accent);
  font-style: normal;
  font-weight: 800;
}
.footer__promise {
  margin: 2px 0 0;
  max-width: 30ch;
  font-size: 0.86rem;
  font-weight: 500;
  line-height: 1.5;
  color: rgba(232, 237, 244, 0.52);
}
.footer__links {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 18px 24px;
  padding-top: 4px;
}
.footer__col {
  display: grid;
  gap: 8px;
  align-content: start;
}
.footer__col-title {
  margin: 0 0 4px;
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(232, 237, 244, 0.38);
}
.footer__col-link {
  color: rgba(255, 255, 255, 0.78);
  font-size: 0.88rem;
  font-weight: 600;
  line-height: 1.35;
  text-decoration: none;
  transition: color 0.15s;
  width: fit-content;
}
.footer__col-link:hover { color: #fff; }

.footer__aside {
  display: grid;
  gap: 20px;
  align-content: start;
  padding-top: 4px;
}
.footer__subscribe {
  display: flex;
  flex-direction: column;
  gap: 10px;
  width: 100%;
}
.footer__subscribeLabel {
  margin: 0;
  color: rgba(232, 237, 244, 0.38);
  font-size: 0.66rem;
  font-weight: 700;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}
.footer__subscribeRow {
  display: flex;
  gap: 0;
  border: 1px solid rgba(232, 237, 244, 0.16);
  border-radius: 12px;
  overflow: hidden;
  background: rgba(255, 255, 255, 0.04);
  transition: border-color 0.15s;
}
.footer__subscribeRow:focus-within {
  border-color: rgba(249, 114, 17, 0.5);
}
.footer__subscribeRow input {
  flex: 1;
  min-width: 0;
  color: #fff;
  font: inherit;
  font-size: 0.9rem;
  font-weight: 500;
  background: transparent;
  border: 0;
  padding: 12px 14px;
  outline: none;
}
.footer__subscribeRow input::placeholder { color: rgba(232, 237, 244, 0.38); }
.footer__subscribeRow button {
  flex-shrink: 0;
  color: #fff;
  cursor: pointer;
  background: var(--accent);
  border: 0;
  padding: 12px 18px;
  font: inherit;
  font-size: 0.88rem;
  font-weight: 700;
  transition: background 0.15s;
}
.footer__subscribeRow button:hover { background: var(--accent-hover); }
.footer__subscribeRow button:disabled {
  opacity: 0.7;
  cursor: wait;
}
.footer__subscribeStatus {
  color: rgba(255, 255, 255, 0.72);
  margin: 0;
  font-size: 0.8rem;
}
.footer__ig {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 0;
  border: 0;
  background: transparent;
  text-decoration: none;
  color: #fff;
  width: fit-content;
  transition: color 0.15s;
}
.footer__ig:hover { color: var(--accent); }
.footer__ig:hover .footer__ig-icon { background: rgba(249, 114, 17, 0.22); }
.footer__ig-icon {
  display: grid;
  place-items: center;
  width: 32px;
  height: 32px;
  border-radius: 9px;
  background: rgba(249, 114, 17, 0.12);
  color: var(--accent);
  flex-shrink: 0;
  transition: background 0.15s;
}
.footer__ig-text {
  display: grid;
  gap: 1px;
  min-width: 0;
}
.footer__ig-label {
  font-size: 0.64rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(232, 237, 244, 0.4);
}
.footer__ig-handle {
  font-size: 0.92rem;
  font-weight: 700;
  letter-spacing: -0.015em;
}

.footer__bar {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  flex-wrap: wrap;
  padding-top: 18px;
}
.footer__copy,
.footer__bar-note {
  margin: 0;
  color: rgba(255, 255, 255, 0.36);
  font-size: 0.76rem;
  font-weight: 500;
}

@media (max-width: 980px) {
  .top__nav a:nth-child(n + 4) { display: none; }
}

@media (max-width: 900px) {
