  .invite { padding: 44px 18px 40px; }
  .browse { padding: 40px 0 56px; }
  .invite--after-hero {
    margin-top: 0;
    padding: 56px 18px 40px;
    background:
      radial-gradient(720px 360px at 8% 0%, rgba(196, 181, 253, 0.14), transparent 58%),
