  .invite__intro h2 { margin-inline: 0; max-width: none; }
  .invite__lead { margin-inline: 0; }
  .invite__shell { grid-template-columns: 1fr; border-radius: 22px; }
  .invite__brand { padding: 22px 20px; min-height: 0; gap: 18px; }
  .invite__face { width: 64px; height: 64px; }
  .invite__work { padding: 20px 18px; }
  .invite__form { grid-template-columns: 1fr; }
  .invite__form .vero-cta { width: 100%; min-height: 48px; }
  .invite__bubbles { gap: 10px; }
  .shelf--flights,
  .shelf--routes { padding: 0 18px; margin-bottom: 36px; }
  .routes--editorial {
    grid-template-columns: 1fr;
    gap: 12px;
  }
  .route-lead,
  .route-lead__copy { min-height: 280px; }
  .route-lane {
    grid-template-columns: 84px 1fr auto;
    min-height: 88px;
  }
  .route-lane__media {
    width: 84px;
