  }
  .top__tools { gap: 8px; }
  .deal-stage { height: 200px; min-height: 200px; }
  .flight-spot__content { padding: 14px 16px 16px; }
  .flight-spot__city { font-size: 1.45rem; }
  .flight-spot__blurb { font-size: 0.8rem; }
  .flight-spot__foot { gap: 12px; }
  .flight-spot__cta { padding: 8px 12px; font-size: 0.7rem; }
  .flight-stack__list {
    display: flex;
    gap: 8px;
