  .top__nav { display: none; }
  .top__signin { display: none; }
  .top__account-label { display: none; }
  .top__account-btn { padding-right: 5px; }
  .top__icon {
    width: 40px;
    height: 40px;
  }
  .sheet { place-items: start center; padding-top: 64px; }
  .trust__row { grid-template-columns: 1fr; gap: 12px; }

  .stage {
