  }
  .footer__main {
    grid-template-columns: 1fr;
    gap: 32px;
    padding-bottom: 32px;
  }
  .footer__links {
    grid-template-columns: repeat(3, minmax(0, 1fr));
    gap: 18px 12px;
  }
  .footer__logoImg {
    height: 34px;
    max-width: 170px;
  }
  .footer__tagline {
    max-width: 16ch;
    font-size: 1.45rem;
  }
  .footer__bar-note { display: none; }
}

@media (max-width: 480px) {
  .stage__body {
    width: min(100% - 20px, 920px);
    padding-bottom: max(22px, env(safe-area-inset-bottom));
  }
  .stage__line { font-size: 1.12rem; }
  .dock__fields { grid-template-columns: 1fr; }
  .cell {
    border-right: 0 !important;
    border-bottom: 1px solid rgba(255, 255, 255, 0.14);
  }
  .cell:last-child { border-bottom: 0; }
  .deal-stage { height: 176px; min-height: 176px; }
  .flight-spot__blurb {
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }
  .flight-ticket { flex-basis: min(140px, 46vw); }
  .invite__brand { padding: 18px 16px; }
  .invite__work { padding: 18px 16px; }
  .shelf__head h2 { font-size: 1.28rem; }
