/* Dark mode — remap homepage tokens when shared theme sets html[data-theme="dark"] */
html[data-theme="dark"] {
  color-scheme: dark;
  --ink: #e8eef6;
  --muted: #9aa8bc;
  --line: #2a3b55;
  --wash: #070d16;
  --select: rgba(215, 230, 247, 0.08);
  --navy: #d7e6f7;
  --navy-mid: #8eabcc;
}
html[data-theme="dark"],
html[data-theme="dark"] body {
  background: var(--wash);
  color: var(--ink);
}
html[data-theme="dark"] .invite,
html[data-theme="dark"] .browse,
html[data-theme="dark"] .recent,
html[data-theme="dark"] .footer {
  background: var(--wash);
  color: var(--ink);
}
html[data-theme="dark"] .shelf__head h2,
html[data-theme="dark"] .invite__intro h2,
html[data-theme="dark"] .recent__intro h2 {
  color: var(--ink);
}
html[data-theme="dark"] .shelf__head p,
html[data-theme="dark"] .invite__lead,
html[data-theme="dark"] .recent__eyebrow {
  color: var(--muted);
}
html[data-theme="dark"] .hcard,
html[data-theme="dark"] .route-card,
html[data-theme="dark"] .route-lane,
html[data-theme="dark"] .flight-ticket,
html[data-theme="dark"] .recent__card,
html[data-theme="dark"] .invite__shell {
  background: #101a2a;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .vhop__title { color: var(--ink); }
html[data-theme="dark"] .vhop__kicker,
html[data-theme="dark"] .vhop__sub { color: var(--muted); }
html[data-theme="dark"] .vhop__ask {
  background: #101a2a;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .vhop__ask:hover {
  background: #152033;
  border-color: rgba(249, 114, 17, 0.4);
}
html[data-theme="dark"] .vhop__ticket {
  --ticket-ink: #e8eef6;
  --ticket-paper: #101a2a;
  --ticket-line: rgba(232, 238, 246, 0.12);
  box-shadow:
    0 0 0 1px rgba(232, 238, 246, 0.1),
    0 16px 36px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .vhop__ticket-stub {
  background: #070d16;
}
html[data-theme="dark"] .vhop__hint { color: var(--muted); }
html[data-theme="dark"] .vhop__arrow { color: rgba(232, 238, 246, 0.4); }
html[data-theme="dark"] .route-card__city,
html[data-theme="dark"] .route-lane__city,
html[data-theme="dark"] .hcard__cta-soft {
  color: var(--ink);
}
html[data-theme="dark"] .route-card__cta,
html[data-theme="dark"] .route-lane__go {
  background: #1c3358;
  color: #fff;
}
html[data-theme="dark"] .hcard__where,
html[data-theme="dark"] .hcard__price small,
html[data-theme="dark"] .hcard__night,
html[data-theme="dark"] .route-card__blurb,
html[data-theme="dark"] .route-card__pair,
html[data-theme="dark"] .route-lane__blurb,
html[data-theme="dark"] .route-lane__pair,
html[data-theme="dark"] .flight-ticket__meta,
html[data-theme="dark"] .recent__meta,
html[data-theme="dark"] .recent__kind {
  color: var(--muted);
}
html[data-theme="dark"] .hcard__foot {
  border-top-color: var(--line);
}
html[data-theme="dark"] .invite__work {
  background: #101a2a;
}
html[data-theme="dark"] .invite__chips button,
html[data-theme="dark"] .invite__form {
  background: #0b1422;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .invite__form input {
  color: var(--ink);
}
html[data-theme="dark"] .invite__ask-label,
html[data-theme="dark"] .invite__more {
  color: var(--muted);
}
html[data-theme="dark"] .invite__more a {
  color: var(--ink);
}
html[data-theme="dark"] .recent__clear {
  border-color: rgba(215, 230, 247, 0.18);
  color: var(--muted);
}
html[data-theme="dark"] .recent__nav {
  background: #101a2a;
  border-color: var(--line);
  color: var(--ink);
}
html[data-theme="dark"] .stage::before {
  background:
    radial-gradient(ellipse 70% 55% at 50% 48%, rgba(0, 8, 20, 0.5), transparent 68%),
    linear-gradient(
      180deg,
      rgba(0, 10, 24, 0.62) 0%,
      rgba(0, 8, 20, 0.28) 42%,
      rgba(7, 13, 22, 0.55) 100%
    );
}
html[data-theme="dark"] .top.is-solid {
  background: rgba(7, 13, 22, 0.94);
  box-shadow: 0 10px 30px rgba(0, 0, 0, 0.35);
}
html[data-theme="dark"] .drawer__panel,
html[data-theme="dark"] .sheet__card {
  background: #101a2a;
  color: var(--ink);
}
/* Drawer, dark: every light-only colour above gets a token so nothing renders dark-on-dark. */
html[data-theme="dark"] .drawer__panel {
  box-shadow: -20px 0 48px rgba(0, 0, 0, 0.45);
}
/* Logo day/night swap lives next to .drawer__brand img (higher specificity). */
html[data-theme="dark"] .drawer__label,
html[data-theme="dark"] .drawer__foot p {
  color: var(--muted);
}
html[data-theme="dark"] .drawer__nav a,
html[data-theme="dark"] .drawer__linkbtn {
  color: var(--ink);
}
html[data-theme="dark"] .drawer__nav a small,
html[data-theme="dark"] .drawer__linkbtn small {
  color: var(--muted);
}
html[data-theme="dark"] .drawer__nav a:hover,
html[data-theme="dark"] .drawer__linkbtn:hover {
  background: var(--paper-2);
}
html[data-theme="dark"] .drawer__ico {
  background: var(--paper-2);
  color: var(--navy-mid);
  border: 1px solid var(--line);
  box-shadow: none;
}
html[data-theme="dark"] .drawer__nav a:hover .drawer__ico,
